private <BE extends @Nullable BlockEntity> TransitResponse insertUnchecked(Level level, BE outputter, TransitRequest request, TransporterStack stack, int min,
          @Nullable TransactionContext transaction, PathCalculator<BE> pathCalculator) {
        //TODO: Technically if we still have more of the same item input, we want to allow trying to insert it into different transport
        // destinations, which this doesn't do as it only checks once, rather than trying to check all destinations we can send to
        // if the amount would be split between multiple destinations
        TransitResponse response = pathCalculator.calculate(stack, level, request, outputter, this, min, transaction);
        if (!response.isEmpty()) {
            stack.setStack(response.itemType(), response.sendingAmount());
            if (transaction == null) {
                //If there is no current transaction context, just directly emit the stack
                emitStack(stack);
            } else {
                //Otherwise, queue it to emit when the transaction chain finishes
                RootCommitJournal onRootCommit = new RootCommitJournal(() -> emitStack(stack));
                onRootCommit.updateSnapshots(transaction);
            }
        }
        return response;
    }

public int getTotalPromisedAndRemoveExpired(ItemStack stack, int expiryTime) {
		int promised = 0;
		List<RequestPromise> list = promisesByItem.get(stack.getItem());
		if (list == null)
			return promised;

		for (Iterator<RequestPromise> iterator = list.iterator(); iterator.hasNext();) {
			RequestPromise promise = iterator.next();
			if (!ItemStack.isSameItemSameComponents(promise.promisedStack.stack, stack))
				continue;
			if (expiryTime != -1 && promise.ticksExisted >= expiryTime) {
				iterator.remove();
				onChanged.run();
				continue;
			}

			promised += promise.promisedStack.count;
		}
		return promised;
	}

private boolean tryUseOn(ServerPlayer player, ItemStack stack) {
        return readBlockPos(stack).map(gPos -> {
            Level level = player.getServer().getLevel(gPos.dimension());
            if (level != player.level() || !player.level().isLoaded(gPos.pos())) {
                player.displayClientMessage(Component.translatable("ftbquests.message.task_screen_inaccessible").withStyle(ChatFormatting.RED), true);
                return false;
            }
            if (level.getBlockEntity(gPos.pos()) instanceof ITaskScreen taskScreen) {
                if (TaskScreenBlock.hasPermissionToEdit(player, taskScreen)) {
                    taskScreen.getCoreScreen().ifPresent(coreScreen -> new TaskScreenConfigRequest(coreScreen.getBlockPos()).sendTo(player));
                    return true;
                } else {
                    player.displayClientMessage(Component.translatable("block.ftbquests.screen.no_permission").withStyle(ChatFormatting.RED), true);
                }
            } else {
                player.displayClientMessage(Component.translatable("ftbquests.message.missing_task_screen").withStyle(ChatFormatting.RED), true);
            }
            return false;
        }).orElse(false);
    }

public static void handle(ClaimChoiceRewardMessage message, NetworkManager.PacketContext context) {
		context.queue(() -> {
			Reward reward = ServerQuestFile.INSTANCE.getReward(message.id);

			if (reward instanceof ChoiceReward choiceReward && context.getPlayer() instanceof ServerPlayer serverPlayer) {
				ServerQuestFile.INSTANCE.getTeamData(serverPlayer).ifPresent(data -> {
					RewardTable table = choiceReward.getTable();

                    if (table != null
                            && data.isCompleted(reward.getQuest())
                            && message.index >= 0 && message.index < table.getWeightedRewards().size()
                            && data.isRewardReadyToClaim(serverPlayer.getUUID(), reward)
							&& table.getWeightedRewards().get(message.index).getReward().tryClaim(serverPlayer, true))
					{
                        data.markRewardAsClaimed(serverPlayer.getUUID(), reward, System.currentTimeMillis());
                    }
				});
			}
		});
	}

public static void handle(PacketTileData message, IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      ServerPlayer player = (ServerPlayer) ctx.player();
      Level world = player.getCommandSenderWorld();
      BlockEntity tile = world.getBlockEntity(message.pos);
      if (tile instanceof TileBlockEntityCyclic) {
        TileBlockEntityCyclic base = (TileBlockEntityCyclic) tile;
        if (message.autoIncrement) {
          //ignore message.value, do a ++
          int incr = base.getField(message.field) + 1;
          base.setField(message.field, incr);
        }
        else {
          base.setField(message.field, message.value);
        }
        base.setChanged();
      }
    });

  }

protected void checkAndPerformAttack(LivingEntity enemy, boolean inRange) {
        long currentTime = mob.level.getGameTime();
        if (inRange) {
            if (currentTime > attackEndTick + 20) {
                ServerAnimationInfo animationInfo = mob.startAttack();
                if (animationInfo.usesAttackBox && enemy instanceof ServerPlayer player) {
                    MessageHandler.SYNC_CHANNEL.sendToPlayers(List.of(player), new S2CActivateAttackBoxesMessage(mob, animationInfo.animation.animationLength));
                    doingHeavyAttack = true;
                } else {
                    attackDamageTick = (long) (currentTime + animationInfo.actionDelay + 5);
                }
                attackEndTick = (long) (currentTime + animationInfo.animation.animationLength + 5);
                if (attackDamageTick > attackEndTick) attackDamageTick = attackEndTick;
            }
            if (attackDamageTick > 0 && currentTime == attackDamageTick) {
                mob.attackTarget(enemy);
                attackDamageTick = -1;
            }
        }
    }

public void handlerToggleRender(final CPacketToggleRender data, final IPayloadContext ctx) {
    ctx.enqueueWork(() -> {
      Player player = ctx.player();
      CuriosApi.getCuriosInventory(player)
          .flatMap(handler -> handler.getStacksHandler(data.identifier()))
          .ifPresent(stacksHandler -> {
            NonNullList<Boolean> renderStatuses = stacksHandler.getRenders();

            if (renderStatuses.size() > data.index()) {
              boolean value = !renderStatuses.get(data.index());
              renderStatuses.set(data.index(), value);
              PacketDistributor.sendToPlayersTrackingEntityAndSelf(player,
                                                                   new SPacketSyncRender(
                                                                       player.getId(),
                                                                       data.identifier(),
                                                                       data.index(), value));
            }
          });
    });
  }

public static void onServerLevelTick(LevelTickEvent.Pre event) {
        Level level = event.getLevel();
        if (level.isClientSide()) {
            return;
        }

        ResourceKey<Level> dim = level.dimension();
        Long2ObjectMap<LongSet> chunks = UPDATED_POSITIONS.get(dim);
        if (chunks != null && !chunks.isEmpty()) {
            for (Long2ObjectMap.Entry<LongSet> entry : chunks.long2ObjectEntrySet()) {
                long chunk = entry.getLongKey();
                PacketDistributor.sendToPlayersTrackingChunk(
                        (ServerLevel) level,
                        ChunkPos.unpack(chunk),
                        new ClientboundCullingUpdatePayload(chunk, entry.getValue())
                );
            }
            chunks.clear();
        }
    }

