    }

private void handleLoopTracking(Entity entity) {
        var trackerData = loopTrackerLookup.get(entity.getUUID());
        if (trackerData == null) {
            trackerData = new LoopTrackerData(level.getGameTime(), 1);
            loopTrackerLookup.put(entity.getUUID(), trackerData);
        } else {
            IronsSpellbooks.LOGGER.debug("looping");
            if (++trackerData.loopCount > loopMax && level.getGameTime() - trackerData.gameTick <= loopTickWindow) {
                if (Objects.equals(getOwnerUUID(), entity.getUUID())) {
                    entity.hurt(new PortalDamageSource(entity.level().damageSources().genericKill().typeHolder(), entity), Float.MAX_VALUE);
                    if (entity instanceof LivingEntity livingEntity && Float.isNaN(livingEntity.getHealth())) {
                        livingEntity.setHealth(0.0f);
                    }
                }
                discard();
            } else if (level.getGameTime() - trackerData.gameTick > loopTickWindow) {
                //Cleanup old tracking information
                loopTrackerLookup.remove(entity.getUUID());
            }
        }
    }

default void setCooldown(World world, @Nullable EntityPlayer player, @Nullable EnumHand hand, ItemStack stack, @Nonnull SpellData data) {
		int maxCooldown = 0;

		List<SpellRing> rings = SpellUtils.getAllSpellRings(stack);

		for (SpellRing ring : rings) {
			if (ring.isContinuous()) return;

			if (ring.getModule() != null && ring.getModule().getModuleClass() instanceof IOverrideCooldown) {

				maxCooldown = ring.getCooldownTime(world, data);
				break;
			}
			if (ring.getCooldownTime() > maxCooldown)
				maxCooldown = ring.getCooldownTime();
		}

		if (maxCooldown <= 0) return;

		if (player != null && hand != null) {
			player.stopActiveHand();
			player.swingArm(hand);
			if (!world.isRemote)
				if (hand == EnumHand.MAIN_HAND)
					PacketHandler.NETWORK.sendTo(new PacketSyncCooldown(true, false), (EntityPlayerMP) player);
				else PacketHandler.NETWORK.sendTo(new PacketSyncCooldown(false, true), (EntityPlayerMP) player);
		}

		NBTHelper.setInt(stack, NBTConstants.NBT.LAST_COOLDOWN, maxCooldown);
		NBTHelper.setLong(stack, NBTConstants.NBT.LAST_CAST, world.getTotalWorldTime());
	}

@Override
  public void afterMeleeHit(IToolStackView tool, ToolAttackContext context, float damage) {
    // sweep code from Player#attack(Entity)
    // basically: no crit, no sprinting and has to stand on the ground for sweep. Also has to move regularly slowly
    LivingEntity attacker = context.getAttacker();
    if (context.isFullyCharged() && !attacker.isSprinting() && !context.isCritical() && !context.isProjectile() && attacker.onGround() && (attacker.walkDist - attacker.walkDistO) < attacker.getSpeed()) {
      // loop through all nearby entities
      double range = this.ranges.compute(tool.getVolatileData().getInt(IModifiable.EXPANDED));
      double rangeSq = (2 + range); // TODO: why do we add 2 here? should that not be defined in the datagen?
      rangeSq *= rangeSq;
      // if the modifier is missing, sweeping damage will be 0, so easiest to let it fully control this
      float sweepDamage = getSweepingDamage(tool, damage);
      Entity target = context.getTarget();
      Level level = attacker.level();
      DamageSource source = context.makeDamageSource();
      for (LivingEntity aoeTarget : level.getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(range, 0.25D, range))) {
        if (aoeTarget != attacker && aoeTarget != target && !attacker.isAlliedTo(aoeTarget)
            && !(aoeTarget instanceof ArmorStand armorStand && armorStand.isMarker()) && attacker.distanceToSqr(aoeTarget) < rangeSq) {
          float angle = attacker.getYRot() * ((float) Math.PI / 180F);
          aoeTarget.knockback(0.4F, Mth.sin(angle), -Mth.cos(angle));
          aoeTarget.hurt(source, sweepDamage);
        }
      }

      level.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.PLAYER_ATTACK_SWEEP, attacker.getSoundSource(), 1.0F, 1.0F);
      if (attacker instanceof Player player) {
        player.sweepAttack();
      }
    }
  }

public static void sweepAttack(ItemStack itemStack, LivingEntity target, LivingEntity attacker, int sweepingLevel) {
        boolean trueSweep = EffectHelper.getEffectLevel(itemStack, ItemEffect.truesweep) > 0;
        float damage = (float) Math.max(attacker.getAttributeValue(Attributes.ATTACK_DAMAGE) * (sweepingLevel * 0.125f), 1);
        float knockback = trueSweep ? (EnchantmentHelper.getItemEnchantmentLevel(Enchantments.KNOCKBACK, itemStack) + 1) * 0.5f : 0.5f;
        double range = 1 + EffectHelper.getEffectEfficiency(itemStack, ItemEffect.sweeping);
        double reach = attacker.getAttributeValue(ForgeMod.ENTITY_REACH.get());

        // range values set up to mimic vanilla behaviour
        attacker.level().getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(range, 0.25d, range)).stream()
                .filter(entity -> entity != attacker)
                .filter(entity -> entity != target)
                .filter(entity -> !attacker.isAlliedTo(entity))
                .filter(entity -> attacker.distanceToSqr(entity) < (range + reach) * (range + reach))
                .forEach(entity -> {
                    entity.knockback(knockback,
                            Mth.sin(attacker.getYRot() * (float) Math.PI / 180F),
                            -Mth.cos(attacker.getYRot() * (float) Math.PI / 180F));

                    DamageSource damageSource = attacker instanceof Player
                            ? attacker.damageSources().playerAttack((Player) attacker)
                            : attacker.damageSources().mobAttack(attacker);

                    if (trueSweep) {
                        ItemEffectHandler.applyHitEffects(itemStack, entity, attacker);
                        EffectHelper.applyEnchantmentHitEffects(itemStack, entity, attacker);

                        causeTruesweepDamage(damageSource, damage, itemStack, attacker, entity);
                    } else {
                        entity.hurt(damageSource, damage);
                    }

                });

        attacker.level().playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(),
                SoundEvents.PLAYER_ATTACK_SWEEP, attacker.getSoundSource(), 1.0F, 1.0F);

        CastOptional.cast(attacker, Player.class).ifPresent(Player::sweepAttack);
    }

public void tick() {
        super.tick();

        if (this.level().isClientSide) {
            if (this.clientSideAttackStarted) {
                ++this.lifeTicks;
                if (this.lifeTicks == 55) {

                    double d0 = (2.0F * random.nextFloat() - 1.0F) * 0.4D;
                    double d1 = (2.0F * random.nextFloat() - 1.0F) * 0.4D ;
                    double d2 = this.getX() + d0;
                    double d3 = this.getY() + (double)random.nextFloat() * 2;
                    double d4 = this.getZ() + d1;
                    this.level().addParticle(ModParticle.PHANTOM_EMITTER.get(), d2, d3, d4, 0.0, 0.25D * random.nextDouble(), 0.0);

                }
                if (this.lifeTicks == 4) {

                    double d0 = this.getX();
                    double d1 = this.getY() + 0.1;
                    double d2 = this.getZ();

                    this.level().addParticle(new Cursed_MarkParticleOption(0.7F + this.random.nextFloat() * 0.3F), d0, d1, d2, 0, 0, 0);

                }
            }
        } else if (--this.warmupDelayTicks < 0) {
            if (this.warmupDelayTicks == -10) {
                if(getState() == 0) {
                    this.setState(1 + random.nextInt(4));
                }
            }
            if (this.warmupDelayTicks < -12 && this.warmupDelayTicks > -34) {
                for(LivingEntity livingentity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox())) {
                    this.damage(livingentity);
                }
            }


            if (!this.sentSpikeEvent) {
                this.level().broadcastEntityEvent(this, (byte)4);
                this.sentSpikeEvent = true;
            }

            if (++this.lifeTicks > 70) {
                this.discard();
            }
        }

    }

private static void enqueueBlockBreak(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, Direction direction, BlockPos pos, float refHardness, ToolAction refTool, int remaining) {
        ServerScheduler.schedule(1, () -> {
            BlockState offsetState = world.getBlockState(pos);

            float blockHardness = offsetState.getDestroySpeed(world, pos);
            if (ToolActionHelper.playerCanDestroyBlock(player, offsetState, pos, itemStack)
                    && blockHardness != -1
                    && blockHardness <= refHardness
                    && ToolActionHelper.isEffectiveOn(refTool, offsetState)) {
                if (EffectHelper.breakBlock(world, player, itemStack, pos, offsetState, true, false)) {
                    EffectHelper.sendEventToPlayer((ServerPlayer) player, 2001, pos, Block.getId(offsetState));

                    item.applyBlockBreakEffects(itemStack, world, offsetState, pos, player);

                    if (remaining > 0) {
                        enqueueBlockBreak(world, player, item, itemStack, direction, pos.relative(direction), refHardness, refTool, remaining - 1);
                    }
                }
            }
        });
    }

public static void consume(PlayerEntity player, float progress, SpellContainerSource.SourcedContainer spellSource, Identifier spellId, RegistryEntry<Spell> spellEntry, ItemStack heldItemStack, Ammo.Result ammoResult, boolean scheduled) {
        var spell = spellEntry.value();
        var batching = spell.cost.batching;
        if (batching && !scheduled) {
            if (((SpellBatcher)player).hasBatchedCost(spellId)) {
                return;
            }
            ((WorldScheduler)player.getWorld()).schedule(0, () -> consume(player, progress, spellSource, spellId, spellEntry, heldItemStack, ammoResult, true));
            ((SpellBatcher)player).batchCost(spellId, true);
            return;
        }

        // Consume things
        // Cooldown
        SpellCooldowns.imposeCooldown(player, spellSource, spellEntry, progress);
        // Exhaust
        player.addExhaustion(spell.cost.exhaust * SpellEngineMod.config.spell_cost_exhaust_multiplier);
        // Durability
        if (SpellEngineMod.config.spell_cost_durability_allowed && spell.cost.durability > 0) {
            var stackToDamage = (spellSource.itemStack() != null && spellSource.itemStack().isDamageable()) ? spellSource.itemStack() : heldItemStack;
            stackToDamage.damage(spell.cost.durability, player, EquipmentSlot.MAINHAND);
        }
        // Item
        Ammo.consume(ammoResult, player);
        // Status effect
        if (spell.cost.effect_id != null) {
            var effect = Registries.STATUS_EFFECT.getEntry(Identifier.of(spell.cost.effect_id));
            if (effect.isPresent()) {
                player.removeStatusEffect(effect.get());
            }
        }
        if (SpellEvents.COST_CONSUME.isListened()) {
            var args = new SpellEvents.SpellCostConsumeEvent.Args(player, spellEntry, heldItemStack);
            SpellEvents.COST_CONSUME.invoke(l -> l.onSpellCostConsume(args));
        }
    }

public static boolean performPourAction(ItemStack stack, LivingEntity entity, InteractionHand hand)
    {
        if (!(entity instanceof Player player && stack.is(ModItems.FILLED_WATERSKIN))) return false;

        // Play empty sound
        if (!player.level().isClientSide)
        {
            double temperature = stack.getOrCreateTag().getDouble(FilledWaterskinItem.NBT_TEMPERATURE);
            double wetnessTemp = 0.05 * CSMath.sign(temperature == 0 ? 1 : temperature);
            // Replace or add water temp modifier
            Placement modPlacement = Placement.of(Mode.REPLACE, Order.FIRST, mod -> mod instanceof WaterTempModifier).orElse(Placement.LAST);
            Temperature.addModifier(player, new WaterTempModifier(wetnessTemp).tickRate(5), Temperature.Trait.WORLD, modPlacement);

            WorldHelper.playEntitySound(ModSounds.WATERSKIN_POUR, player, player.getSoundSource(), 2f, (float) ((Math.random() / 5) + 0.9));
        }

        consumeWaterskin(stack, player, hand);
        MinecraftForge.EVENT_BUS.post(new LivingEntityUseItemEvent.Finish(player, stack, 1, stack.getCraftingRemainingItem()));
        player.swing(hand, true);

        // spawn falling water particles
        Random rand = new Random();
        for (int i = 0; i < 6; i++)
        {
            TaskScheduler.scheduleServer(() ->
            {
                ParticleBatchMessage particleBatch = new ParticleBatchMessage(2);
                for (int p = 0; p < 10; p++)
                {
                    AABB playerBB = player.getDimensions(player.getPose()).makeBoundingBox(player.position()).inflate(0.2);
                    particleBatch.addParticle(ParticleTypes.FALLING_WATER,
                                              Mth.lerp(rand.nextFloat(), playerBB.minX, playerBB.maxX),
                                              playerBB.maxY,
                                              Mth.lerp(rand.nextFloat(), playerBB.minZ, playerBB.maxZ),
                                              0.3, 0.3, 0.3);
                }
                particleBatch.sendEntity(player);
            }, i);
        }
        player.getCooldowns().addCooldown(ModItems.FILLED_WATERSKIN, 10);
        player.getCooldowns().addCooldown(ModItems.WATERSKIN, 10);

        return true;
    }

@SubscribeEvent
        public static void onLivingDamage(LivingDamageEvent.Pre event) {
            var source = event.getSource().getEntity();
            var damage = event.getOriginalDamage();
            var entity = event.getEntity();

            var level = entity.level();
            var random = level.getRandom();

            if (damage >= 1) {
                for (var stack : EntityUtils.findEquippedCurios(entity, RelicsItems.REFLECTIVE_NECKLACE.get())) {
                    var relic = (ReflectiveNecklaceItem) stack.getItem();

                    if (level.getRandom().nextDouble() > relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("chance").getValue())
                        continue;

                    var orbDamage = Math.clamp((float) (damage * relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("damage").getValue()), Float.MIN_VALUE, Float.MAX_VALUE);

                    var orb = new ReflectiveOrbEntity(RelicsEntities.REFLECTIVE_ORB.get(), level);

                    orb.setPiercings(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("piercing").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("piercings").getValue() : 0);
                    orb.setBounces(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("bounce").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("bounces").getValue() : 0);
                    orb.setStun(relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getRankModifierData("stun").isEnabled() ? (int) relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("stun").getValue() : 0);
                    orb.setLifetime((int) (relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatData("lifetime").getValue() * 20));
                    orb.setFlawless(relic.getRelicData(entity, stack).isVisuallyFlawless());
                    orb.setPos(entity.getEyePosition());
                    orb.setDamage(orbDamage);
                    orb.setOwner(entity);
                    orb.setStack(stack);

                    if (source != null)
                        orb.setDeltaMovement(entity.position().subtract(source.position()).normalize().add(MathUtils.randomFloat(random) * 0.5D, 0, MathUtils.randomFloat(random) * 0.5D));
                    else
                        orb.setDeltaMovement(MathUtils.randomFloat(random) * 0.5D, 0.5D + random.nextFloat() * 0.25D, MathUtils.randomFloat(random) * 0.5D);

                    level.addFreshEntity(orb);

                    relic.getRelicData(entity, stack).getLevelingData().addExperience("reflection", "construct", orbDamage * 0.1D);

                    relic.getRelicData(entity, stack).getAbilitiesData().getAbilityData("reflection").getStatisticData().getMetricData("total_orbs").addValue(1);
                }
            }

            if (!(event.getSource().getEntity() instanceof LivingEntity livingSource))
                return;

            var stack = EntityUtils.findEquippedCurio(livingSource, RelicsItems.REFLECTIVE_NECKLACE.get());

            if (!stack.isEmpty()) {
                var step = 0;

                for (var orb : level.getEntitiesOfClass(ReflectiveOrbEntity.class, livingSource.getBoundingBox().inflate(ORB_SEARCH_RADIUS)).stream()
                        .filter(orb -> !orb.isTargeted() && orb.getOwner() instanceof LivingEntity owner && owner.getStringUUID().equals(livingSource.getStringUUID()))
                        .sorted(Comparator.comparingInt(orb -> (int) orb.position().distanceTo(entity.position())))
                        .toList()) {

                    ServerScheduler.schedule(step++ * 2, () -> orb.setTarget(entity.position().add(0D, entity.getBbHeight(), 0D).add(entity.getKnownMovement())));
                }
            }
        }

public static void tickSpread(SculkSpreader spreader, LevelAccessor level, BlockPos origin, int bailoutCounter) {
        spreader.updateCursors(level, origin, level.getRandom(), true);

        if (bailoutCounter > 0 && !spreader.getCursors().isEmpty()) {
            ServerScheduler.schedule(level.getRandom().nextInt(3), () -> tickSpread(spreader, level, origin, bailoutCounter - 1));
        } else if (!spreader.getCursors().isEmpty()) {
            logger.debug("Bailed on spreader, bailout: {}", bailoutCounter);
        }
    }

private static void breakRecursive(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, Direction direction, BlockPos pos,
            float refHardness, ToolAction refTool, int remaining) {
        if (remaining > 0) {
            ServerScheduler.schedule(2, () -> breakInner(world, player, item, itemStack, direction, pos, refHardness, refTool));
        }
        if (remaining > 1) {
            ServerScheduler.schedule(4, () -> breakOuter(world, player, item, itemStack, direction, pos, refHardness, refTool));
        }
        if (remaining > 2) {
            ServerScheduler.schedule(6, () -> {
                BlockPos offsetPos = pos.relative(direction);
                if (breakBlock(world, player, item, itemStack, offsetPos, refHardness, refTool)) {
                    breakRecursive(world, player, item, itemStack, direction, offsetPos, refHardness, refTool, remaining - 2);
                }
            });
        }
    }

private static void breakRecursive(Level world, Player player, ItemModularHandheld item, ItemStack itemStack, Direction direction, BlockPos origin,
            Vec3i limiter, List<BlockPos> positions, List<BlockPos> backupPositions, float refHardness, ToolAction refTool, float remaining) {
        while (positions.size() > 0 || backupPositions.size() > 0) {
            BlockPos target = positions.size() > 0
                    ? positions.remove(player.getRandom().nextInt(positions.size()))
                    : backupPositions.remove(player.getRandom().nextInt(backupPositions.size()));
            if (breakBlock(world, player, item, itemStack, target, refHardness, refTool)) {
                if (remaining > 0) {
                    positions.addAll(getRegularOffsets(target, origin, limiter));
                    backupPositions.addAll(getBackupOffsets(target, origin, limiter));
                    ServerScheduler.schedule(player.getRandom().nextInt(3), () -> breakRecursive(world, player, item, itemStack, direction,
                            origin, limiter, positions, backupPositions, refHardness, refTool, remaining - 1));
                }
                return;
            }
        }
    }

