private void doWaveTick(@Nullable Entity shooter, List<LivingEntity> entities, Vec3 origin, int tick) {
		float distance = tick * 30 / 40f;
		distance *= distance;
		EffectBuilder builder = new EffectBuilder(MobEffects.GLOWING, 7);

		for (Iterator<LivingEntity> iterator = entities.iterator(); iterator.hasNext();) {
			LivingEntity entity = iterator.next();

			if (entity.distanceToSqr(origin) <= distance) {
				EntityUtil.applyPotions(entities, shooter, builder);
				iterator.remove();
			}
		}

		if (!entities.isEmpty() && tick < 40)
			AoAScheduler.schedule(1, tick2 -> doWaveTick(shooter, entities, origin, tick + 1));
	}

private void handleBlockBreak(BlockEvent.BreakEvent ev) {
		BlockState state = ev.getState();

		if (state.getBlock() instanceof CropBlock crop && !state.is(AoATags.Blocks.NO_HARVEST_REPLANT) && testAsChance()) {
			LevelAccessor level = ev.getLevel();
			BlockPos pos = ev.getPos();

			if (InventoryUtil.findItemForConsumption(ev.getPlayer(), stack -> ItemStack.isSameItemSameComponents(stack, crop.getCloneItemStack(level, pos, state)), 1, true))
				AoAScheduler.schedule(1, tick -> {
					if (level.getBlockState(pos).isAir()) {
						level.setBlock(pos, state.setValue(crop.getAgeProperty(), 0), Block.UPDATE_ALL);

						if (!level.isClientSide())
							PlayerUtil.giveXpToPlayer((ServerPlayer)ev.getPlayer(), AoASkills.FARMING.get(), PlayerUtil.getTimeBasedXpForLevel(PlayerUtil.getLevel(ev.getPlayer(), AoASkills.FARMING.get()), 3), false);
					}
				});
		}
	}

public static void applyChanges(LivingEntity livingEntity, List<Diff> changes) {
        for (var change : changes) {
            final var newAmplifier = change.newAmplifier;
            if (change.delay > 0) {
                final var effectType = change.effect.getEffectType();
                ((WorldScheduler)livingEntity.getWorld()).schedule(change.delay - 1, () -> {
                    var effect = livingEntity.getStatusEffect(effectType);
                    if (effect == null) {
                        // If the effect is not present, we can skip processing
                        return;
                    }
                    processRemoval(livingEntity, effect, newAmplifier);
                });
            } else {
                processRemoval(livingEntity, change.effect, newAmplifier);
            }
        }
    }

