@Override
	public void run(int tick) {
		if (shooter == null || target == null || shooter.level().isClientSide || !shooter.blockPosition().equals(shooterPos) || !target.blockPosition().equals(targetPos)) {
			resetStates();

			return;
		}

		float healthPercent = 1 - (GlobalEvents.tick - startingTick) / 200f;
		float targetPostHealth = targetStartHealth * healthPercent;
		float shooterPostHealth = shooterStartHealth * healthPercent;

		if (targetTurn) {
			if (target.getHealth() == 0) {
				resetStates();

				return;
			}

			if (targetPostHealth <= 0) {
				resetStates();
				DamageUtil.doRecoilAttack(target, target.getHealth() - targetPostHealth);
				target.setDeltaMovement(0, 0, 0);

				if (shooter instanceof Player pl) {
					target.setLastHurtByPlayer(pl);
				}
				else {
					target.setLastHurtByMob(shooter);
				}
			}
			else {
				target.setHealth(targetPostHealth);
			}

			((ServerLevel)shooter.level()).sendParticles(ParticleTypes.DAMAGE_INDICATOR, target.getX(), target.getY() + target.getBbHeight(), target.getZ(), (int)Math.ceil(10 * healthPercent), 0, 0, 0, 0);
		}
		else {
			if (!(shooter instanceof Player) || !((Player)shooter).isCreative()) {
				if (shooterPostHealth <= 0) {
					resetStates();
					DamageUtil.doRecoilAttack(shooter, shooter.getHealth() - shooterPostHealth);
				}
				else {
					shooter.setHealth(shooterPostHealth);
				}

				((ServerLevel)shooter.level()).sendParticles(ParticleTypes.DAMAGE_INDICATOR, shooter.getX(), shooter.getY() + shooter.getBbHeight(), shooter.getZ(), (int)Math.ceil(10 * healthPercent), 0, 0, 0, 0);
			}
		}

		targetTurn = !targetTurn;

		AoAScheduler.schedule(1, this);
	}

private void doSlam(BlockPos fromPos, float chance) {
        TMEParticlePacket packet = new TMEParticlePacket();

        for (Direction dir : Direction.values()) {
            if (RandomUtil.percentChance(chance)) {
                BlockPos pos = fromPos.offset(dir.getNormal());
                BlockState state = level().getBlockState(pos);

                if (state.is(AoATags.Blocks.INFERNAL_CAN_CONVERT)) {
                    int tickTime = Math.max(1, 1 - pos.distManhattan(fromPos));

                    packet.particle(ParticleBuilder.forPosition(ParticleTypes.FLAME, pos.getX() + RandomUtil.valueUpTo(1), pos.getY() + 1.1, pos.getZ() + RandomUtil.valueUpTo(1)));
                    level().setBlockAndUpdate(pos, Blocks.MAGMA_BLOCK.defaultBlockState());
                    AoAScheduler.schedule(tickTime, tick -> doSlam(pos, chance * 0.8f));
                    AoAScheduler.schedule(tickTime + 100, tick -> {
                        if (level().getBlockState(pos).getBlock() == Blocks.MAGMA_BLOCK)
                            level().setBlockAndUpdate(pos, state);
                    });
                }
            }
        }

        if (!packet.isEmpty())
            packet.sendToAllPlayersTrackingEntity(this);
    }

@Override
        protected void doDelayedAction(FlamewalkerEntity entity) {
            if (this.target == null)
                return;

            if (!BrainUtils.canSee(entity, this.target) || entity.distanceToSqr(this.target) > this.attackRadius)
                return;

            for (int tick = 1; tick < 12; tick++) {
                final int thisTick = tick;
                final Vec3 targetPos = this.targetingPosition;
                final EasyRandom random = entity.rand();

                AoAScheduler.schedule(thisTick, tick2 -> {
                    TMEParticlePacket packet = new TMEParticlePacket(45);

                    for (int i = 0; i < 8; i++) {
                        if (thisTick == 1) {
                            packet.particle(ParticleBuilder.forPositions(EntityTrackingParticleOptions.fromEntity(AoAParticleTypes.BURNING_FLAME, entity), targetPos.add(random.scaledGaussianValue(0.8f), random.valueBetween(-0.5f, 0), random.scaledGaussianValue(0.8f)))
                                    .scaleMod(random.valueBetween(1, 3))
                                    .lifespan(Mth.ceil(5 / random.valueBetween(0.2f, 1f)))
                                    .velocity(random.scaledGaussianValue(0.05f), 0.5, random.scaledGaussianValue(0.05f)));
                        }

                        packet.particle(ParticleBuilder.forPositions(ParticleTypes.SMOKE, targetPos.add(random.scaledGaussianValue(1), random.valueBetween(-0.5f, 0), random.scaledGaussianValue(1)))
                                .velocity(random.scaledGaussianValue(0.05f), 0.5, random.scaledGaussianValue(0.05f)));
                        packet.particle(ParticleBuilder.forPositions(EntityTrackingParticleOptions.ambient(AoAParticleTypes.BURNING_FLAME), targetPos.add(random.scaledGaussianValue(0.5f), random.valueBetween(-0.5f, 0), random.scaledGaussianValue(0.5f)))
                                .scaleMod(random.valueBetween(0.5f, 1.5f))
                                .velocity(random.scaledGaussianValue(0.05f), 0.5, random.scaledGaussianValue(0.05f)));
                    }

                    packet.sendToAllPlayersTrackingEntity(entity);
                });
            }

            BrainUtils.setForgettableMemory(entity, MemoryModuleType.ATTACK_COOLING_DOWN, true, this.attackIntervalSupplier.apply(entity));
        }

@Override
    public void run() {
        double x = centerX;
        double z = centerZ;

        switch (currentCorner) {
            case 0 -> {
                x += 9;
                z += 9;
            }
            case 1 -> {
                x -= 9;
                z += 9;
            }
            case 2 -> {
                x -= 9;
                z -= 9;
            }
            case 3 -> {
                x += 9;
                z -= 9;
            }
        }

        AoAExplosionBuilder.at(this.level, x, this.centerY, z, AoAExplosions.CREEP_SPAWN, StandardExplosion::new).explode();

        count++;

        if (count >= 4) {
            /*CreepEntity creep = new CreepEntity(AoAMobs.CREEP.get(), world);

            creep.setPos(x, centerY, z);
            world.addFreshEntity(creep);*/

            return;
        }

        currentCorner += 1;

        if (currentCorner > 3)
            currentCorner = 0;

        schedule(2, TimeUnit.SECONDS);
    }

protected void doStomp(EmperorBeastEntity entity) {
            final float scale = entity.getScale();
            final Vec3 stompPos = entity.position().add(MathUtil.getEyelineForward(entity).scale(2.43f * scale).add(MathUtil.getEyelineRight(entity).scale(1.5f * scale)));
            final BlockState feetState = entity.level().getBlockState(BlockPos.containing(stompPos.subtract(0, 0.25f, 0)));

            SoundBuilder.at(AoASounds.ENTITY_TYROSAUR_STOMP, entity.level(), stompPos).varyPitch((float) RandomUtil.scaledGaussianValue(0.1f)).play();
            ParticleBuilder.forRandomPosInCircleRadius(ParticleTypes.CAMPFIRE_SIGNAL_SMOKE, stompPos, 0.2f)
                    .spawnNTimes(35)
                    .addBulkProperty(builder -> builder.scaleMod(RandomUtil.valueBetween(1, 1.25f)))
                    .addBulkProperty(builder -> builder.lifespan(RandomUtil.numberBetween(40, 60)))
                    .addTransition(AwayFromPositionParticleTransition.create(stompPos, 20))
                    .sendToAllPlayersTrackingEntity(entity);

            if (!feetState.isAir()) {
                ParticleBuilder.forRandomPosInCircleRadius(new BlockParticleOption(ParticleTypes.BLOCK, feetState), stompPos, 0.2f)
                        .spawnNTimes(50)
                        .scaleMod(2f)
                        .addBulkProperty(builder -> builder.velocity(RandomUtil.scaledGaussianValue(0.1f), RandomUtil.valueBetween(0.2f, 0.35f), RandomUtil.scaledGaussianValue(0.1f)))
                        .sendToAllPlayersTrackingEntity(entity);
            }

            for (LivingEntity nearby : EntityRetrievalUtil.getEntities(entity.level(), stompPos, entity.getBbWidth(), LivingEntity.class, target -> target != entity)) {
                DamageUtil.safelyDealDamage(DamageUtil.positionedEntityDamage(DamageTypes.MOB_ATTACK_NO_AGGRO, entity, stompPos), nearby, 10);
            }
        }

private void doBlocks(ServerLevel level, T entity, Vec3 earthquakeOrigin, int tick) {
        List<BlockSnapshot> positions = BlockRetrievalUtil.getBlocks(level, reader -> {
            List<BlockSnapshot> list = new ObjectArrayList<>();
            Iterable<Vec3> iterable = MathUtil.inLateralCircle(earthquakeOrigin, tick, 64);
            Set<BlockPos> checkedPositions = new ObjectOpenHashSet<>();

            for (Vec3 vecPos : iterable) {
                BlockPos pos = BlockPos.containing(vecPos);

                if (!checkedPositions.add(pos))
                    continue;

                BlockState state = reader.getBlockState(pos);

                if (!state.blocksMotion()) {
                    int offset = 10;

                    while (offset-- > 0 && !(state = reader.getBlockState(pos = pos.below())).blocksMotion());
                }
                else if (reader.getBlockState(pos.above()).blocksMotion()) {
                    int offset = 10;

                    while (offset-- > 0 && reader.getBlockState(pos = pos.above()).blocksMotion());

                    state = reader.getBlockState(pos = pos.below());
                }

                if (state.blocksMotion() && !reader.getBlockState(pos.above()).blocksMotion())
                    list.add(new BlockSnapshot(pos, state));
            }

            return list;
        });

        TMEParticlePacket packet = new TMEParticlePacket();

        if (entity.tickCount % 3 == 0) {
            for (ServerPlayer player : level.players()) {
                if (player.distanceToSqr(entity) > 32 * 32)
                    continue;

                Vec3 velocity = earthquakeOrigin.vectorTo(player.position()).normalize();

                SoundBuilder.at(AoASounds.FX_RUBBLE, level, earthquakeOrigin.add(velocity.scale(tick)))
                        .customInstance(new BuildableMovingSoundInstance(velocity))
                        .pitch(0.75f)
                        .onlyFor(player)
                        .play();
            }
        }

        for (BlockSnapshot ringPos : positions) {
            EarthquakeBlockEntity block = new EarthquakeBlockEntity(AoAMiscEntities.EARTHQUAKE_BLOCK.get(), level, ringPos.state(), ringPos.pos(), entity);

            block.setDamage(this.damage);
            block.setDeltaMovement(new Vec3(0, 0.35f, 0));
            block.setPos(Vec3.atCenterOf(ringPos.pos()));
            level.addFreshEntity(block);
            packet.particle(ParticleBuilder.forRandomPosInBlock(new BlockParticleOption(ParticleTypes.BLOCK, ringPos.state()), ringPos.pos())
                                    .lifespan(RandomUtil.numberBetween(20, 40))
                                    .scaleMod(0.5f)
                                    .velocity(RandomUtil.scaledGaussianValue(0.1f), RandomUtil.valueBetween(0.2f, 0.4f), RandomUtil.scaledGaussianValue(0.1f)));
        }

        packet.sendToAllPlayersTrackingEntity(entity);
    }

public boolean plungeAttack(Level world, LivingEntity attacker, ItemStack stack) {

        if (attacker.fallDistance <= attacker.getMaxFallDistance() || !isEmpowered(stack) || !useEnergy(stack, true, attacker)) {
            return false;
        }
        float range = getPlungeRange(attacker.fallDistance);
        if (world.isClientSide) {
            // TODO circle particle
            world.addParticle(new CylindricalParticleOptions(CoreParticles.BLAST_WAVE.get(), range * 2.0F, range * 3.0F, 0, VFXHelper.windColor(world.random).toRGBA(), 1.5F), attacker.getX(), attacker.getY(), attacker.getZ(), 0, 0, 0);
            return true;
        }
        if (Utils.getItemEnchantmentLevel(Enchantments.CHANNELING, stack) > 0) {
            if (world.canSeeSky(attacker.blockPosition()) && world instanceof ServerLevel && world.isThundering()) {
                attacker.addEffect(new MobEffectInstance(LIGHTNING_RESISTANCE.get(), 40, 0, false, false));
                Utils.spawnLightningBolt(world, attacker.blockPosition(), attacker);
            }
        }
        double r2 = range * range;
        boolean hit = false;
        for (Entity target : world.getEntities(attacker, attacker.getBoundingBox().inflate(range, 1, range), EntitySelector.NO_CREATIVE_OR_SPECTATOR)) {
            if (attacker.distanceToSqr(target) <= r2) {
                hit |= target.hurt(IFluxItem.fluxDirectDamage(attacker), getPlungeAttackDamage(attacker, stack));
            }
        }
        if (hit) {
            world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_RETURN, SoundSource.PLAYERS, 10.0F, 1.0F);
        } else {
            world.playSound(null, attacker.getX(), attacker.getY(), attacker.getZ(), SoundEvents.TRIDENT_HIT_GROUND, SoundSource.PLAYERS, 3.0F, 1.0F);
        }
        return hit;
    }

@Override
	public boolean hurtEnemy(ItemStack stack, LivingEntity entity, @NotNull LivingEntity attacker) {
		double range = 8;
		IntList alreadyTargetedEntities = new IntArrayList();

		Predicate<Entity> selector = e -> e instanceof LivingEntity && e instanceof Enemy && !(e instanceof Player) && !alreadyTargetedEntities.contains(e.getId());

		LivingEntity prevTarget = entity;
		int hops = entity.level().isThundering() ? 10 : 4;
		int dmg = hops + 1;
		for (int i = 0; i < hops; i++) {
			List<Entity> entities = entity.level().getEntities(prevTarget, new AABB(prevTarget.getX() - range, prevTarget.getY() - range, prevTarget.getZ() - range, prevTarget.getX() + range, prevTarget.getY() + range, prevTarget.getZ() + range), selector);
			if (entities.isEmpty()) {
				break;
			}

			LivingEntity target = (LivingEntity) entities.get(entity.level().getRandom().nextInt(entities.size()));
			if (attacker instanceof Player player) {
				target.hurt(player.damageSources().playerAttack(player), dmg);
			} else {
				target.hurt(attacker.damageSources().mobAttack(attacker), dmg);
			}

			alreadyTargetedEntities.add(target.getId());
			prevTarget = target;
			dmg--;
		}

		if (!alreadyTargetedEntities.isEmpty()) {
			XplatAbstractions.INSTANCE.sendToTracking(attacker,
					new BotaniaEffectPacket(EffectType.THUNDERCALLER_EFFECT,
							attacker.getX(), attacker.getY() + attacker.getBbHeight() / 2.0, attacker.getZ(),
							alreadyTargetedEntities.toArray(new int[0])));
		}

		return super.hurtEnemy(stack, entity, attacker);
	}

@Override
        public void tickTask() {
            ++this.ticks;
            if (this.level.getEntity(this.owner) instanceof LivingEntity living) {
                living.fallDistance = 0;
                living.invulnerableTime = 20;
                double radius = 1.0D;
                if (this.staff){
                    radius += 0.25D;
                }
                for(int i = 0; i < 2; ++i) {
                    double d0 = (2.0D * Math.random() - 1.0D) * 0.2D;
                    double d1 = (2.0D * Math.random() - 1.0D) * 0.2D;
                    double d2 = (2.0D * Math.random() - 1.0D) * 0.2D;
                    this.level.sendParticles(ModParticleTypes.BIG_ELECTRIC.get(), living.getRandomX(1.0D), living.getRandomY(), living.getRandomZ(1.0D), 0, d0, d1, d2, 0.5F);
                }
                ServerParticleUtil.addParticlesAroundMiddleSelf(this.level, ModParticleTypes.ELECTRIC.get(), living);

                List<Entity> list = this.level.getEntities(living, living.getBoundingBox().inflate(radius));
                if (!list.isEmpty()) {
                    for (Entity entity : list) {
                        if (entity instanceof LivingEntity target) {
                            if (!MobUtil.areAllies(living, entity) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(entity) && entity.isAttackable()){
                                float baseDamage = SpellConfig.BoltingDamage.get().floatValue() * WandUtil.damageMultiply();
                                if (target.hurt(ModDamageSource.directShock(living), baseDamage + this.damage)){
                                    float chance = this.staff ? 0.25F : 0.05F;
                                    float chainDamage = this.damage / 2.0F;
                                    if (this.level.isThundering() && this.level.isRainingAt(target.blockPosition())){
                                        chance += 0.25F;
                                        chainDamage = this.damage;
                                    }
                                    if (this.level.random.nextFloat() <= chance){
                                        target.addEffect(new MobEffectInstance(GoetyEffects.SPASMS.get(), MathHelper.secondsToTicks(5)));
                                    }
                                    if (this.staff){
                                        WandUtil.chainLightning(target, living, 2.0D, chainDamage);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

private void onThrowableCollision(HitResult result) {
		Entity thrower = getOwner();
		if (!(thrower instanceof Player) || ((int) getY()) <= 0) {
			discard();
			return;
		}

		for (int i = 0; i < 32; i++) {
			level().addParticle(ParticleTypes.PORTAL, getX(), getY() + random.nextDouble() * 2D, getZ(), random.nextGaussian(), 0.0D, random.nextGaussian());
		}

		if (!level().isClientSide) {
			thrower.fallDistance = 0.0F;

			int x = (int) Math.round(getX());
			int y = (int) Math.round(getY());
			int z = (int) Math.round(getZ());

			if (result.getType() != HitResult.Type.MISS) {
				BlockPos pos;
				if (result.getType() == HitResult.Type.ENTITY) {
					Entity entityHit = ((EntityHitResult) result).getEntity();
					entityHit.hurt(damageSources().thrown(this, thrower), 0);
					pos = entityHit.blockPosition();
				} else {
					BlockHitResult blockResult = (BlockHitResult) result;
					pos = blockResult.getBlockPos().relative(blockResult.getDirection());
				}

				y = pos.getY();
				x = pos.getX();
				z = pos.getZ();
			}
			float targetX = x + 0.5F;
			float targetY = y + 0.5F;
			float targetZ = z + 0.5F;
			if (thrower instanceof ServerPlayer serverPlayer) {
				EventHooks.onEnderPearlLand(serverPlayer, targetX, targetY, targetZ, new ThrownEnderpearl(level(), serverPlayer), 0, result);
			}

			thrower.playSound(SoundEvents.ENDERMAN_TELEPORT, 1.0f, 1.0f);
			thrower.teleportTo(targetX, targetY, targetZ);
		}
		discard();
	}

default void dealAOEDamage(Player player, Entity target, ItemStack stack, long energyPerHit, float damage, double aoe) {
        List<LivingEntity> entities = player.level().getEntitiesOfClass(LivingEntity.class, target.getBoundingBox().inflate(aoe, 0.25D, aoe));
        double aoeAngle = 100;
        double yaw = player.getYRot() - 180;

        int fireAspect = player.level().registryAccess().holder(Enchantments.FIRE_ASPECT).map(e -> EnchantmentHelper.getEnchantmentLevel(e, player)).orElse(0);

        for (LivingEntity entity : entities) {
            if (getEnergyStored(stack) < energyPerHit && !player.getAbilities().instabuild) break;
            float distance = player.distanceTo(entity);
            if (entity == player || entity == target || player.isAlliedTo(entity) || distance < 1 || entity.distanceTo(target) > aoe) continue;
            double angle = Math.atan2(player.getX() - entity.getX(), player.getZ() - entity.getZ()) * MathHelper.todeg;
            double relativeAngle = Math.abs((angle + yaw) % 360);
            if (relativeAngle <= aoeAngle / 2 || relativeAngle > 360 - (aoeAngle / 2)) {
                boolean lit = false;
                float health = entity.getHealth();
                if (fireAspect > 0 && !entity.isOnFire()) {
                    lit = true;
                    entity.setRemainingFireTicks(20);
                }

                if (entity.hurt(entity.level().damageSources().playerAttack(player), damage)) {
                    float damageDealt = health - entity.getHealth();
                    entity.knockback(0.4F, MathHelper.sin(player.getYRot() * MathHelper.torad), (-MathHelper.cos(player.getYRot() * MathHelper.torad)));

                    if (fireAspect > 0) {
                        entity.setRemainingFireTicks(fireAspect * 4 * 20);
                    }

                    if (player.level() instanceof ServerLevel && damageDealt > 2.0F) {
                        int k = (int)((double)damage * 0.5D);
                        ((ServerLevel)player.level()).sendParticles(ParticleTypes.DAMAGE_INDICATOR, entity.getX(), entity.getY(0.5D), entity.getZ(), k, 0.1D, 0.0D, 0.1D, 0.2D);
                    }

                    player.awardStat(Stats.DAMAGE_DEALT, Math.round(damageDealt * 10.0F));
                    if (player.level() instanceof ServerLevel && damageDealt > 2.0F) {
                        int k = (int) ((double) damageDealt * 0.5D);
                        ((ServerLevel) player.level()).sendParticles(ParticleTypes.DAMAGE_INDICATOR, entity.getX(), entity.getY(0.5D), entity.getZ(), k, 0.1D, 0.0D, 0.1D, 0.2D);
                    }
                } else if (lit) {
                    entity.clearFire();
                }
            }
            extractEnergy(player, stack, energyPerHit);
        }
    }

protected void onHitEntity(EntityHitResult p_37626_) {
        if (!this.level.isClientSide) {
            float baseDamage = SpellConfig.IceSpikeDamage.get().floatValue() * WandUtil.damageMultiply();
            Entity entity = p_37626_.getEntity();
            if (this.getPierceLevel() > 0) {
                if (this.piercingIgnoreEntityIds == null) {
                    this.piercingIgnoreEntityIds = new IntOpenHashSet(5);
                }

                if (this.piercedAndKilledEntities == null) {
                    this.piercedAndKilledEntities = Lists.newArrayListWithCapacity(5);
                }

                if (this.piercingIgnoreEntityIds.size() >= this.getPierceLevel() + 1) {
                    this.discard();
                    return;
                }

                this.piercingIgnoreEntityIds.add(entity.getId());
            }
            Entity entity1 = this.getOwner();
            boolean flag;
            baseDamage += this.getExtraDamage();
            if (entity1 instanceof LivingEntity livingentity) {
                if (!entity.isAlive() && this.piercedAndKilledEntities != null) {
                    this.piercedAndKilledEntities.add(livingentity);
                }
                flag = entity.hurt(ModDamageSource.iceSpike(this, livingentity), baseDamage);
                if (flag) {
                    if (entity.isAlive()) {
                        this.doEnchantDamageEffects(livingentity, entity);
                    }
                }
            } else {
                flag = entity.hurt(ModDamageSource.iceSpike(this, this), baseDamage);
            }

            if (flag && entity instanceof LivingEntity livingEntity) {
                livingEntity.addEffect(new MobEffectInstance(GoetyEffects.FREEZING.get(), MathHelper.secondsToTicks(3 + livingEntity.getRandom().nextInt(2))));
                this.playSound(ModSounds.ICE_SPIKE_HIT.get(), 1.0F, 1.2F / (this.random.nextFloat() * 0.2F + 0.9F));
                if (livingEntity.level instanceof ServerLevel serverLevel){
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, new BlockParticleOption(ParticleTypes.BLOCK, Blocks.PACKED_ICE.defaultBlockState()), livingEntity);
                }
                if (this.getPierceLevel() <= 0) {
                    this.discard();
                }
            }

        }
    }

private void executeAttacks() {
		if (this.currentState == State.MORTAR_SHOOTING && this.ticksProgress % 10 == 0) {
			HydraMortar mortar = new HydraMortar(TFEntities.HYDRA_MORTAR.get(), this.headEntity.level(), this.headEntity);

			// launch blasting mortars if the player is hiding
			if (this.targetEntity != null && !this.headEntity.canEntityBeSeen(this.targetEntity)) {
				mortar.setToBlasting();
			}

			this.headEntity.playSound(TFSounds.HYDRA_SHOOT.get(), 10.0F, (this.headEntity.level().getRandom().nextFloat() - this.headEntity.level().getRandom().nextFloat()) * 0.2F + 1.0F);
			this.headEntity.level().addFreshEntity(mortar);

		}
		if (this.headEntity.getState() == State.BITING) {
			// damage nearby things
			List<Entity> nearbyList = this.headEntity.level().getEntities(this.headEntity, this.headEntity.getBoundingBox().inflate(0.0, 1.0, 0.0));

			for (Entity nearby : nearbyList) {
				if (nearby instanceof LivingEntity living && nearby != this.hydra) {
					//is a player holding a shield? Let's do some extra stuff!
					if (nearby instanceof Player player && player.isBlocking()) {
						if (!player.getCooldowns().isOnCooldown(player.getUseItem())) {
							//cause severe damage and play a shatter sound
							this.headEntity.level().playSound(null, player.blockPosition(), player.getUseItem().is(Items.SHIELD) ? TFSounds.WOOD_SHIELD_SHATTERS.get() : TFSounds.METAL_SHIELD_SHATTERS.get(), SoundSource.PLAYERS, 1.0F, player.getVoicePitch());
							player.getUseItem().hurtAndBreak(112, player, player.getUsedItemHand());
						}
						//add cooldown and knockback
						player.getCooldowns().addCooldown(player.getUseItem(), 200);
						player.stopUsingItem();
						PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.15F, -this.headEntity.getDirection().getStepZ() * 0.5F));
					}

					// bite it!
					nearby.hurt(TFDamageTypes.getEntityDamageSource(living.level(), TFDamageTypes.HYDRA_BITE, this.hydra, TFEntities.HYDRA.get()), BITE_DAMAGE);

					//knockback!
					if (living instanceof Player player) {
						PacketDistributor.sendToPlayer((ServerPlayer) player, new MovePlayerPacket(-this.headEntity.getDirection().getStepX() * 0.5F, 0.1F, -this.headEntity.getDirection().getStepZ() * 0.5F));
					} else {
						living.knockback(-this.headEntity.getDirection().getStepX(), 0.1F, -this.headEntity.getDirection().getStepZ());
					}
				}
			}
		}

		if (this.headEntity.getState() == State.FLAMING) {
			Entity target = getHeadLookTarget();

			if (target != null && target != this.headEntity.getParent() && (!(target instanceof HydraPart) || ((HydraPart) target).getParent() != this.headEntity.getParent()) && this.hydra.level() instanceof ServerLevel serverLevel) {
				if (!target.fireImmune() && target.hurtServer(serverLevel, TFDamageTypes.getEntityDamageSource(target.level(), TFDamageTypes.HYDRA_FIRE, this.hydra, TFEntities.HYDRA.get()), FLAME_DAMAGE)) {
					target.igniteForSeconds(FLAME_BURN_FACTOR);
				}
			}
		}
	}

private static Vec3 handleDamageFromTrain(Level world, AbstractContraptionEntity contraptionEntity,
		Vec3 contraptionMotion, Entity entity, Vec3 entityMotion, PlayerType playerType) {

		if (!(contraptionEntity instanceof CarriageContraptionEntity cce))
			return entityMotion;
		if (!entity.onGround())
			return entityMotion;

		CompoundTag persistentData = entity.getPersistentData();
		if (persistentData.contains("ContraptionGrounded")) {
			persistentData.remove("ContraptionGrounded");
			return entityMotion;
		}

		if (cce.collidingEntities.containsKey(entity))
			return entityMotion;
		if (entity instanceof ItemEntity)
			return entityMotion;
		if (cce.nonDamageTicks != 0)
			return entityMotion;
		if (!AllConfigs.server().trains.trainsCauseDamage.get())
			return entityMotion;

		Vec3 diffMotion = contraptionMotion.subtract(entity.getDeltaMovement());

		if (diffMotion.length() <= 0.35f || contraptionMotion.length() <= 0.35f)
			return entityMotion;

		DamageSource source = CreateDamageSources.runOver(world, contraptionEntity);
		double damage = diffMotion.length();
		if (entity.getClassification(false) == MobCategory.MONSTER)
			damage *= 2;

		if (entity instanceof Player p && (p.isCreative() || p.isSpectator()))
			return entityMotion;

		if (playerType == PlayerType.CLIENT) {
			CatnipServices.NETWORK.sendToServer(new TrainCollisionPacket((int) (damage * 16), contraptionEntity.getId()));
			world.playSound((Player) entity, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT,
				SoundSource.NEUTRAL, 1, .75f);
		} else {
			entity.hurt(source, (int) (damage * 16));
			world.playSound(null, entity.blockPosition(), SoundEvents.PLAYER_ATTACK_CRIT, SoundSource.NEUTRAL, 1, .75f);
			if (!entity.isAlive())
				contraptionEntity.getControllingPlayer()
					.map(world::getPlayerByUUID)
					.ifPresent(AllAdvancements.TRAIN_ROADKILL::awardTo);
		}

		Vec3 added = entityMotion.add(contraptionMotion.multiply(1, 0, 1)
			.normalize()
			.add(0, .25, 0)
			.scale(damage * 4))
			.add(diffMotion);

		return VecHelper.clamp(added, 3);
	}

@Override
	public void tick() {
		super.tick();

		if (!level.isClientSide) {
			if (random.nextInt(200) == 0 && !level.dimensionType().ultraWarm() && level.getBlockState(blockPosition()).getMaterial().isReplaceable()) {
				level.setBlockAndUpdate(blockPosition(), Blocks.WATER.defaultBlockState());
				new DracyonCleanupTask(level, blockPosition()).schedule(5, TimeUnit.SECONDS);
			}

			if (random.nextInt(70) == 0 && getTarget() != null) {
				LivingEntity target = getTarget();
				BaseMobProjectile projectile = new SpectralShotEntity(this, BaseMobProjectile.Type.MAGIC);

				double distanceFactorX = target.getX() - projectile.getX();
				double distanceFactorY = target.getBoundingBox().minY + (target.getBbHeight() / 3) - projectile.getY();
				double distanceFactorZ = target.getZ() - projectile.getZ();
				double hyp = MathHelper.sqrt(distanceFactorX * distanceFactorX + distanceFactorZ * distanceFactorZ) * 0.05d;

				level.playSound(null, blockPosition(), AoASounds.ENTITY_DRACYON_AMBIENT.get(), SoundCategory.HOSTILE, 1.0f, 1.0f);
				projectile.shoot(distanceFactorX, distanceFactorY + hyp, distanceFactorZ, 1.6f, (float)(4 - this.level.getDifficulty().getId()));
				level.addFreshEntity(projectile);
			}

			float healthPercent = getHealth() / getMaxHealth();

			if (healthPercent != bossInfo.getPercent())
				bossInfo.setPercent(healthPercent);
		}
	}

@Override
	public ItemStack finishUsingItem(ItemStack stack, Level level, LivingEntity entity) {
		if (WorldUtil.isWorld(level, AoADimensions.NOWHERE) || !(level instanceof ServerLevel serverLevel) || !(entity instanceof ServerPlayer pl))
			return stack;

		ServerLevel nowhere = serverLevel.getServer().getLevel(AoADimensions.NOWHERE);

		if (nowhere == null)
			return stack;

		BlockPos fromPos = entity.blockPosition();

		AoAScheduler.schedule(1, tick -> {
			if (AdvancementUtil.isAdvancementCompleted(pl, AdventOfAscension.id("nowhere/root"))) {
				ServerPlayerDataManager plData = PlayerUtil.getAdventPlayer(pl);
				GlobalPos returnLoc = plData.storage.getPortalReturnFor(nowhere.dimension());

				pl.changeDimension(AoAPortal.getTransitionForLevel(nowhere, pl, AoABlocks.NOWHERE_PORTAL.get()));
				pl.connection.teleport(17.5d, 502.5d, 3.5d, 0, pl.getXRot());

				plData.storage.setPortalReturnLocation(nowhere.dimension(), returnLoc == null ? new GlobalPos(level.dimension(), fromPos) : returnLoc);
			}
			else {
				PlayerUtil.getAdventPlayer(pl).storage.setPortalReturnLocation(nowhere.dimension(), pl.level().dimension(), pl.blockPosition());
				pl.changeDimension(AoAPortal.getTransitionForLevel(nowhere, pl, AoABlocks.NOWHERE_PORTAL.get()));
				pl.connection.teleport(17.5d, 452.5d, 3.5d, 0, pl.getXRot());
			}
		});

		return stack;
	}

private static void onPlayerDamagedPre(final LivingDamageEvent.Pre ev) {
		if (ev.getEntity() instanceof ServerPlayer pl) {
			if (pl.getHealth() <= ev.getContainer().getNewDamage()) {
				ServerPlayerDataManager plData = PlayerUtil.getAdventPlayer(pl);
				PositionAndRotation checkpoint = plData.storage.getActiveCheckpoint();

				if (checkpoint != null) {
					if (CheckpointBlock.isValidCheckpoint(pl.level(), checkpoint)) {
						AoAScheduler.schedule(1, tick -> {
							if (NowhereEvents.isInBossRegion(pl.blockPosition()))
								InventoryUtil.clearItems(pl, AoAItems.RETURN_CRYSTAL);

							PlayerUtil.resetToDefaultStatus(pl);
							pl.sendSystemMessage(LocaleUtil.getLocaleMessage("deathScreen.title", ChatFormatting.DARK_RED));
							pl.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("checkpoint.respawn"), ChatFormatting.GREEN), true);
							checkpoint.applyToEntity(pl);
						});

						ev.getContainer().setNewDamage(0);

						return;
					}
					else {
						plData.storage.clearActiveCheckpoint();
						pl.sendSystemMessage(LocaleUtil.getLocaleMessage(LocaleUtil.createFeedbackLocaleKey("checkpoint.invalid"), ChatFormatting.RED));
					}
				}

				if (ev.getEntity().level().dimension() == AoADimensions.NOWHERE)
					NowhereEvents.doDeathPrevention(ev, plData);
			}
		}
	}

public static void handleNowhereRightClickBlock(final PlayerInteractEvent.RightClickBlock ev) {
		BlockState blockState = ev.getLevel().getBlockState(ev.getPos());
		Block block = blockState.getBlock();
		ItemStack heldStack = ev.getEntity().getItemInHand(ev.getHand());
		Item heldItem = heldStack.getItem();

		if (block == Blocks.JUKEBOX) {
			if (heldItem == Items.AIR || heldStack.has(DataComponents.JUKEBOX_PLAYABLE)) {
				ev.setUseItem(TriState.TRUE);
				ev.setUseBlock(TriState.TRUE);
				ev.getEntity().getAbilities().mayBuild = true;
			}
		}
		else if (blockState.is(AoATags.Blocks.NOWHERE_SAFE_GUI_BLOCK)) {
			ev.setUseItem(TriState.FALSE);
		}
		else if (block == Blocks.WATER_CAULDRON) {
			ev.setUseItem(TriState.FALSE);
			AoAScheduler.schedule(1, tick -> ev.getLevel().setBlock(ev.getPos(), blockState.setValue(LayeredCauldronBlock.LEVEL, LayeredCauldronBlock.MAX_FILL_LEVEL), Block.UPDATE_CLIENTS));
		}
		else if (block == AoABlocks.TEA_SINK.get()) {
			ev.setUseItem(TriState.FALSE);
			AoAScheduler.schedule(1, tick -> ev.getLevel().setBlock(ev.getPos(), blockState.setValue(TeaSink.FILLED, true), Block.UPDATE_CLIENTS));
		}
		else if (heldItem == AoAItems.LOTTO_TOTEM.get()) {
			ev.setUseItem(TriState.TRUE);
			ev.setUseBlock(TriState.FALSE);
			ev.getEntity().getAbilities().mayBuild = true;
		}
		else {
			ev.setCanceled(true);
		}
	}

public static void doDeathPrevention(final LivingDamageEvent.Pre ev, ServerPlayerDataManager plData) {
		ServerPlayer player = plData.getPlayer();

		if (player.server.isHardcore() && NowhereEvents.isInBossRegion(player.blockPosition()))
			return;

		LivingEntity killer = player.getKillCredit();

		player.getScoreboard().forAllObjectives(ObjectiveCriteria.DEATH_COUNT, player, ScoreAccess::increment);

		if (killer != null) {
			player.awardStat(Stats.ENTITY_KILLED_BY.get(killer.getType()));
			killer.awardKillScore(player, 1, ev.getContainer().getSource());
		}

		player.awardStat(Stats.DEATHS);
		player.resetStat(Stats.CUSTOM.get(Stats.TIME_SINCE_DEATH));
		player.resetStat(Stats.CUSTOM.get(Stats.TIME_SINCE_REST));

		if (!AdvancementUtil.isAdvancementCompleted(player, AdventOfAscension.id("nowhere/root"))) {
			AoAScheduler.schedule(1, tick -> {
				PlayerUtil.resetToDefaultStatus(player);
				player.connection.teleport(17.5d, 452.5d, 3.5d, 0, player.getXRot());
				InventoryUtil.clearItems(player, AoAItems.RETURN_CRYSTAL);
				PlayerUtil.getAdventPlayer(player).storage.returnStoredItems();
			});
		}
		else {
			NowhereActivityPortal.Activity.RETURN.activate(plData.getPlayer());
		}

		player.sendSystemMessage(LocaleUtil.getLocaleMessage("deathScreen.title", ChatFormatting.DARK_RED));
		ev.getContainer().setNewDamage(0);
	}

private static void onEntityInteract(final PlayerInteractEvent.EntityInteractSpecific ev) {
		if (!ev.getEntity().level().isClientSide) {
			if (ev.getItemStack().getItem() instanceof StasisCapsule stasisCapsule && ev.getTarget() instanceof LivingEntity target) {
				InteractionResult result = stasisCapsule.tryCapture(ev.getEntity(), target, ev.getItemStack(), ev.getHand());

				if (result != InteractionResult.PASS) {
					ev.setCancellationResult(result);

					return;
				}
			}

			if (ev.getTarget() instanceof Piglin piglin && piglin.getItemBySlot(EquipmentSlot.HEAD).getItem() == Items.GOLDEN_HELMET) {
				ItemStack stack = ev.getEntity().getItemInHand(ev.getHand());

				if ((stack.getItem() == Items.ENCHANTED_GOLDEN_APPLE || stack.getItem() == AoAItems.GOLD_COIN.get()) && piglin.getOffhandItem().isEmpty()) {
					piglin.addTag("BarteringForExplosiveIdol");
					piglin.setItemSlot(EquipmentSlot.OFFHAND, stack.split(1));
					piglin.setGuaranteedDrop(EquipmentSlot.OFFHAND);
					piglin.getBrain().setMemoryWithExpiry(MemoryModuleType.ADMIRING_ITEM, true, 121);
					piglin.getBrain().eraseMemory(MemoryModuleType.WALK_TARGET);
					piglin.getNavigation().stop();

					AoAScheduler.schedule(120, tick -> {
						if (piglin != null && piglin.isAlive() && piglin.getHealth() >= piglin.getMaxHealth()) {
							ItemStack offHandItem = piglin.getItemInHand(InteractionHand.OFF_HAND);

							if (offHandItem.getItem() == Items.ENCHANTED_GOLDEN_APPLE || offHandItem.getItem() == AoAItems.GOLD_COIN.get()) {
								piglin.setItemInHand(InteractionHand.OFF_HAND, Items.GOLD_INGOT.getDefaultInstance());
								piglin.getBrain().eraseMemory(MemoryModuleType.ADMIRING_ITEM);
							}
						}
					});
				}
			}
		}
	}

private static void fireTriggers(Event event) {
        if (event.player.getWorld().isClient()) { return; }
        // Iterate stash effects
        SpellStashHelper.useStashes(event);
        // Iterate passive spells
        var player = event.player;
        var caster = (SpellCaster.Player)player;
        for(var spellEntry: SpellContainerSource.passiveSpellsOf(event.player)) {
            var spell = spellEntry.value();
            var spellId = spellEntry.getKey().get().getValue();
            if (spell.passive != null && !caster.getCooldownManager().isCoolingDown(spellEntry)) {
                for (var trigger : spell.passive.triggers) {
                    if (evaluateTrigger(spellEntry, trigger, event)) {
                        SpellTarget.SearchResult targetResult;
                        if (spell.target.type == Spell.Target.Type.FROM_TRIGGER) {
                            if (event.target == null && event.location != null) {
                                targetResult = SpellTarget.SearchResult.of(event.location);
                            } else {
                                List<Entity> targets = List.of(event.target(trigger));
                                targetResult = SpellTarget.SearchResult.of(targets);
                            }
                        } else {
                            targetResult = SpellTarget.findTargets(player, spellEntry, SpellTarget.SearchResult.empty(), true);
                        }
                        if (trigger.fire_delay > 0) {
                            ((WorldScheduler)player.getWorld()).schedule(trigger.fire_delay - 1, () -> {
                                SpellExecution.performSpell(player.getWorld(), player, spellEntry, targetResult, SpellCast.Action.TRIGGER, 1);
                            });
                        } else {
                            SpellExecution.performSpell(player.getWorld(), player, spellEntry, targetResult, SpellCast.Action.TRIGGER, 1);
                        }
                        break;
                    }
                }
            }
        }
    }

private static void groundSlamEntity(Player attacker, LivingEntity target, ItemModularHandheld item, ItemStack itemStack, Vec3 origin,
            double damageMultiplier, int slowDuration, double momentumEfficiency, int revengeLevel) {
        ServerScheduler.schedule(target.blockPosition().distManhattan(BlockPos.containing(origin)) - 3, () -> {
            float knockback = momentumEfficiency > 0 ? 0.1f : 0.5f;

            AbilityUseResult result = item.hitEntity(itemStack, attacker, target, damageMultiplier, knockback, knockback);

            if (momentumEfficiency > 0) {
                target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.GENERIC_BIG_FALL, SoundSource.PLAYERS, 1, 0.7f);
            } else {
                target.getCommandSenderWorld().playSound(null, target.blockPosition(), SoundEvents.PLAYER_ATTACK_STRONG, SoundSource.PLAYERS, 1, 0.9f);
            }

            if (result != AbilityUseResult.fail) {
                if (slowDuration > 0) {
                    target.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SLOWDOWN, slowDuration, 1, false, true));
                }

                if (momentumEfficiency > 0) {
                    double velocity = momentumEfficiency;
                    velocity *= 1 - target.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
                    target.push(0, velocity, 0);
                    target.addEffect(new MobEffectInstance(StunPotionEffect.instance, 40, 0, false, false));
                }

                if (revengeLevel > 0 && RevengeTracker.canRevenge(attacker, target)) {
                    target.addEffect(new MobEffectInstance(StunPotionEffect.instance, revengeLevel, 0, false, false));
                    RevengeTracker.removeEnemySynced((ServerPlayer) attacker, target);
                }
            }

            if (result == AbilityUseResult.crit) {
                RandomSource rand = target.getRandom();
                CastOptional.cast(target.level(), ServerLevel.class).ifPresent(world ->
                        world.sendParticles(ParticleTypes.CRIT,
                                target.getX(), target.getY(), target.getZ(), 10,
                                rand.nextGaussian() * 0.3, rand.nextGaussian() * 0.5, rand.nextGaussian() * 0.3, 0.1f));
            }
        });
    }

private void setBlock(ServerLevel level, BlockPos pos) {
        if (delay > 0 || randomDelay > 0) {
            int actualDelay = delay + (randomDelay > 0 ? level.getRandom().nextInt(randomDelay) : 0);
            ServerScheduler.schedule(actualDelay, () -> {
                if (blockState.canSurvive(level, pos) && testRequirements(level, level.getBlockState(pos), pos)) {
                    level.setBlock(pos, blockState, Block.UPDATE_ALL);
                    if (particle != null) {
                        level.sendParticles(particle, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
                                8, 0.5, 0.5, 0.5, 0.1);
                    }
                    if (sound != null) {
                        level.playSound(null, pos, sound.type, SoundSource.BLOCKS, sound.volume, sound.pitch);
                    }
                }
            });
            if (intervalParticle != null && fxInterval > 0) {
                for (int i = 1; i * fxInterval < actualDelay; i++) {
                    ServerScheduler.schedule(i * fxInterval, () -> level.sendParticles(intervalParticle, pos.getX() + 0.5, pos.getY() + 0.5,
                            pos.getZ() + 0.5,
                            8, 0.5, 0.5, 0.5, 0.1));
                }
            }
            if (intervalSound != null && fxInterval > 0) {
                for (int i = 1; i * fxInterval < actualDelay; i++) {
                    float volume = intervalSound.volume + i * intervalSoundVolumeChange;
                    float pitch = intervalSound.pitch + i * intervalSoundPitchChange;
                    ServerScheduler.schedule(i * fxInterval, () -> level.playSound(null, pos, intervalSound.type, SoundSource.PLAYERS, volume,
                            pitch));
                }
            }
        } else {
            level.setBlock(pos, blockState, Block.UPDATE_ALL);
            if (particle != null) {
                level.sendParticles(particle, pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
                        8, 0.5, 0.5, 0.5, 0.1);
            }
            if (sound != null) {
                level.playSound(null, pos, sound.type, SoundSource.BLOCKS, sound.volume, sound.pitch);
            }
        }
    }

