        if (living.level instanceof ServerLevel serverLevel) {
            if (living.canChangeDimensions()
                    && !living.getType().is(Tags.EntityTypes.BOSSES)
                    && !living.isDeadOrDying()) {
                int i1 = living.isInvisible() ? 15 : 4;
