public void tick() {
        LivingEntity target = entity.getTarget();
        if (target != null) {
            double dist = entity.distanceTo(target);
            float f = entity.getBbWidth() + target.getBbWidth();
            if (burrowCheckTime++ > 40 && entity.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                burrowCheckTime = 0;
                if (!burrowing) {
                    if (entity.onGround() && dist > f && (!entity.canReach(target.blockPosition()) || dist > 20 || entity.getRandom().nextInt(20) == 0)) {
                        burrowing = true;
                        evadeFor = 60 + entity.getRandom().nextInt(40);
                    }
                } else {
                    if (dist < f + 1 || entity.getRandom().nextInt(10) == 0) {
                        burrowing = false;
                        evadeFor = 0;
                    }
                }
            }
            if (evadeFor > 0) {
                evadeFor--;
                burrowing = true;
                this.entity.setDigging(true);
                if (this.entity.getNavigation().isDone()) {
                    Vec3 vec3 = generateEvadePosition(target.blockPosition());
                    if (vec3 != null) {
                        this.entity.getNavigation().moveTo(vec3.x, vec3.y, vec3.z, 1.0D);
                    }
                }
            } else if (burrowing) {
                if (this.entity.onGround()) {
                    this.entity.setDigging(true);
                }
                this.entity.getNavigation().moveTo(target, 2D);
                if (!this.entity.isInWall()) {
                    this.entity.setDigging(false);
                    this.burrowing = false;
                }
            } else {
                if (!this.entity.isInWall()) {
                    this.entity.setDigging(false);
                } else {
                    this.entity.setDigging(true);
                    this.entity.setDeltaMovement(this.entity.getDeltaMovement().add(0, 0.1D, 0));
                }
                this.entity.getNavigation().moveTo(target, 1.5F);
            }
            if (dist < f + 1.0F) {
                tryAnimation(CorrodentEntity.ANIMATION_BITE);
            }
            if (entity.getAnimation() == CorrodentEntity.ANIMATION_BITE) {
                this.entity.setDigging(false);
                if (entity.getAnimationTick() == 8) {
                    checkAndDealDamage(target, 1.5F);
                    if (entity.getRandom().nextBoolean()) {
                        evadeFor = 60 + entity.getRandom().nextInt(40);
                    }
                }
            }
        }
    }

public void tick() {
        LivingEntity livingentity = this.entity.getTarget();
        if(animationCooldown > 0){
            animationCooldown--;
        }
        if (livingentity != null) {
            double d0 = this.entity.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
            boolean flag = this.entity.hasLineOfSight(livingentity);
            boolean flag1 = this.seeTime > 0;
            if (flag != flag1) {
                this.seeTime = 0;
            }

            if (flag) {
                ++this.seeTime;
            } else {
                --this.seeTime;
            }

            if (!(d0 > (double)this.maxAttackDistance) && this.seeTime >= 20) {
                this.entity.getNavigation().stop();
                ++this.strafingTime;
            } else {
                this.entity.getNavigation().moveTo(livingentity, this.moveSpeedAmp);
                this.strafingTime = -1;
            }

            if (this.strafingTime >= 20) {
                if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                    this.strafingClockwise = !this.strafingClockwise;
                }

                if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                    this.strafingBackwards = !this.strafingBackwards;
                }

                this.strafingTime = 0;
            }

            if (this.strafingTime > -1) {
                if (d0 > (double)(this.maxAttackDistance * 0.75F)) {
                    this.strafingBackwards = false;
                } else if (d0 < (double)(this.maxAttackDistance * 0.25F)) {
                    this.strafingBackwards = true;
                }

                this.entity.getMoveControl().strafe(this.strafingBackwards ? -0.5F : 0.5F, this.strafingClockwise ? 0.5F : -0.5F);
                this.entity.lookAt(livingentity, 30.0F, 30.0F);
            } else {
                this.entity.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);
            }
            if (!flag && this.seeTime < -60) {
                this.entity.stopUsingItem();
            } else if (flag) {
                if(entity.getAnimation() != EntityStraddler.ANIMATION_LAUNCH){
                    entity.setAnimation(EntityStraddler.ANIMATION_LAUNCH);
                    this.attackTime = this.attackCooldown;
                }
            }
        }
    }

@Override
    public void startAttackBehavior(LivingEntity target) {
        double distance = this.distanceTo(target);
        float f = this.getBbWidth() + target.getBbWidth();
        boolean meleeOnly = this.getItemInHand(InteractionHand.MAIN_HAND).is(ACItemRegistry.ORTHOLANCE.get());
        if ((distance > 15 || !melee) && !meleeOnly) {
            melee = false;
            if (!pickUpTrident() && this.getItemInHand(InteractionHand.MAIN_HAND).is(Items.TRIDENT)) {
                if (this.hasLineOfSight(target) && distance < 35) {
                    this.getNavigation().stop();
                    if (this.getAnimation() == NO_ANIMATION) {
                        this.setAnimation(ANIMATION_THROW);
                    } else if (this.getAnimation() == ANIMATION_THROW && this.getAnimationTick() > 8) {
                        melee = true;
                        throwTrident(target);
                        this.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                    }
                } else {
                    this.getNavigation().moveTo(target, 1.2);
                }
            }
        }
        if (melee || meleeOnly) {
            if (distance < f + 1.0F) {
                if (this.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                    setAnimation(this.getRandom().nextBoolean() ? ANIMATION_SCRATCH : ANIMATION_BITE);
                    this.playSound(ACSoundRegistry.DEEP_ONE_KNIGHT_ATTACK.get());
                }
            } else {
                this.getNavigation().moveTo(target, 1.2);
            }
        }
        if (this.getAnimation() == ANIMATION_SCRATCH) {
            if (this.getAnimationTick() > 5 && this.getAnimationTick() < 9 || this.getAnimationTick() > 12 && this.getAnimationTick() < 16) {
                checkAndDealMeleeDamage(target, 1.0F);
            }
        }
        if (this.getAnimation() == ANIMATION_BITE) {
            if (this.getAnimationTick() > 3 && this.getAnimationTick() <= 7) {
                checkAndDealMeleeDamage(target, 1.0F);
            }
        }
    }

