public void tick() {
        LivingEntity livingentity = this.entity.getTarget();
        if(crossbowCooldown > 0){
            crossbowCooldown--;
        }
        if (livingentity != null) {
            double d0 = this.entity.distanceToSqr(livingentity.getX(), livingentity.getY(), livingentity.getZ());
            boolean flag = this.entity.hasLineOfSight(livingentity);
            boolean flag1 = this.seeTime > 0;
            if (flag != flag1) {
                this.seeTime = 0;
            }

            if (flag) {
                ++this.seeTime;
            } else {
                --this.seeTime;
            }

            if (!(d0 > (double)this.maxAttackDistance) && this.seeTime >= 20) {
                this.entity.getNavigation().stop();
                ++this.strafingTime;
            } else {
                this.entity.getNavigation().moveTo(livingentity, this.moveSpeedAmp);
                this.strafingTime = -1;
            }

            if (this.strafingTime >= 20) {
                if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                    this.strafingClockwise = !this.strafingClockwise;
                }

                if ((double)this.entity.getRandom().nextFloat() < 0.3D) {
                    this.strafingBackwards = !this.strafingBackwards;
                }

                this.strafingTime = 0;
            }

            if (this.strafingTime > -1) {
                if (d0 > (double)(this.maxAttackDistance * 0.75F)) {
                    this.strafingBackwards = false;
                } else if (d0 < (double)(this.maxAttackDistance * 0.25F)) {
                    this.strafingBackwards = true;
                }

                this.entity.getMoveControl().strafe(this.strafingBackwards ? -0.5F : 0.5F, this.strafingClockwise ? 0.5F : -0.5F);
                this.entity.lookAt(livingentity, 30.0F, 30.0F);
            } else {
                this.entity.getLookControl().setLookAt(livingentity, 30.0F, 30.0F);
            }
            boolean crossbow = this.entity.getMainHandItem().getItem() instanceof CrossbowItem;
            if (this.entity.isUsingItem() || crossbow) {
                if (!flag && this.seeTime < -60) {
                    this.entity.stopUsingItem();
                } else if (flag) {
                    int i = this.entity.getTicksUsingItem();
                    if (i >= 20 || crossbow && crossbowCooldown == 0) {
                        this.entity.stopUsingItem();
                        this.entity.performRangedAttack(livingentity, BowItem.getPowerForTime(i));
                        this.attackTime = this.attackCooldown;
                        crossbowCooldown = 20;
                    }
                }
            } else if (--this.attackTime <= 0 && this.seeTime >= -60) {
                this.entity.startUsingItem(ProjectileUtil.getWeaponHoldingHand(this.entity, Items.BOW));
            }

        }
    }

@Override
    public void aiStep() {
        super.aiStep();
        setFlying(true);
        boolean flying = this.isFlying() && !this.onGround;
        setTicksAlive(getTicksAlive() + 1);
        if (flying) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, -0.08D, 0));
            if (this.moveControl.getWantedY() > this.getY()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, 0.08D, 0));
            }
        }
        if (this.onGround) {
            this.setDeltaMovement(this.getDeltaMovement().add(0, 0.2D, 0));
        }
        if (this.getTarget() != null) {
            this.moveControl.setWantedPosition(this.getTarget().getX(), this.getTarget().getBoundingBox().minY, this.getTarget().getZ(), 1.0F);
            if (this.getAttackBounds().intersects(this.getTarget().getBoundingBox())) {
                this.setAnimation(random.nextBoolean() ? ANIMATION_BITE : ANIMATION_STING);
            }
        }
        if (this.getTicksAlive() > 1800) {
            this.kill();
        }
        if (this.getAnimation() == ANIMATION_BITE && this.getTarget() != null && this.getAnimationTick() == 6) {
            this.playBiteSound();
            double dist = this.distanceToSqr(this.getTarget());
            if (dist < attackDistance()) {
                this.getTarget().hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue()));
            }
        }
        if (this.getAnimation() == ANIMATION_STING && this.getTarget() != null && this.getAnimationTick() == 6) {
            this.playStingSound();
            double dist = this.distanceToSqr(this.getTarget());
            if (dist < attackDistance()) {
                this.getTarget().hurt(DamageSource.mobAttack(this), ((int) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue() * 2));
                // After calling hurt the target can become null due to forge hooks
                if (this.getTarget() != null)
                    this.getTarget().addEffect(new MobEffectInstance(MobEffects.POISON, 70, 1));
            }
        }
    }

@Override
    public void updateTask() {
        int tick = this.entity.getAnimationTick();

        if (this.animation == EntityAnimation.PREPARE_LEAP && tick < this.prevTick) {
            this.animation = EntityAnimation.LEAP;

            this.entity.playSound(this.entity.getSoundForAnimation(EntityAnimation.ATTACKING.get()), this.entity.getSoundVolume(), this.entity.getSoundPitch());

            double targetSpeedX = this.target.posX - (!this.ticked ? this.target.prevPosX : this.targetPrevPosX);
            double targetSpeedZ = this.target.posZ - (!this.ticked ? this.target.prevPosZ : this.targetPrevPosZ);

            double length = this.entity.width * 6.0F;

            double destX = this.target.posX + targetSpeedX * length;
            double destZ = this.target.posZ + targetSpeedZ * length;

            double delta = Math.sqrt((destX - this.entity.posX) * (destX - this.entity.posX) + (destZ - this.entity.posZ) * (destZ - this.entity.posZ));
            double angle = Math.atan2(destZ - this.entity.posZ, destX - this.entity.posX);

            this.entity.motionX = delta / length * Math.cos(angle);
            this.entity.motionZ = (delta / length * Math.sin(angle));
            this.entity.motionY = Math.min(0.3, Math.max(0, (this.target.posY - this.entity.posY) * 0.1)) + 0.6;
        } else if (this.animation == EntityAnimation.LEAP && this.entity.motionY < 0) {
            this.animation = EntityAnimation.LEAP_LAND;
        } else if (this.animation == EntityAnimation.LEAP_LAND && (this.entity.onGround || this.entity.isSwimming())) {
            this.animation = EntityAnimation.IDLE;

            if (this.entity.getEntityBoundingBox() != null && this.target.getEntityBoundingBox() != null && this.entity.getEntityBoundingBox().intersects(this.target.getEntityBoundingBox().expand(2.0, 2.0, 2.0))) {
                this.entity.attackEntityAsMob(this.target);
            }
        }

        this.targetPrevPosX = this.target.posX;
        this.targetPrevPosZ = this.target.posZ;
        this.ticked = true;

        if (this.entity.getAnimation() != this.animation.get()) {
            this.entity.setAnimation(this.animation.get());
            this.entity.setAnimationTick(this.prevTick + 1);
        }

        this.prevTick = tick;
    }

public void tick() {
        if (peppermintCooldown > 0) {
            peppermintCooldown--;
        }
        if (hexCooldown > 0) {
            hexCooldown--;
        }
        if (potionCooldown > 0) {
            potionCooldown--;
        }
        if (checkReachCooldown > 0) {
            checkReachCooldown--;
        }
        LivingEntity target = licowitch.getTarget();
        if(duration > 200 && checkReachCooldown == 0 && target != null){
            checkReachCooldown = 100 + licowitch.getRandom().nextInt(40);
            if(licowitch.canTeleport() && !licowitch.canReach(target.blockPosition())){
                licowitch.setTeleportingToPos(Vec3.atBottomCenterOf(target.blockPosition()));
                return;
            }
        }
        if (target != null && target.isAlive() && licowitch.getTeleportingToPos() == null) {
            double distance = licowitch.distanceTo(target);
            double distanceXZ = Mth.sqrt((float) licowitch.distanceToSqr(target.getX(), licowitch.getY(), target.getZ()));
            double attackDistance = licowitch.getBbWidth() + target.getBbWidth() + 5;
            licowitch.lookAt(target, 30.0F, 30.0F);
            if (licowitch.getAnimation() == LicowitchEntity.ANIMATION_EAT || enqueuedAttackType == 0 && distance < attackDistance - 1 || licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1 && distanceXZ < 6.0F) {
                licowitch.getMoveControl().strafe(-4, 0.0F);
                licowitch.getNavigation().stop();
            } else if (distance > attackDistance || !this.licowitch.hasLineOfSight(target)) {
                this.licowitch.getNavigation().moveTo(target, 1.0D);
            }
            if (this.licowitch.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                if (enqueuedAttackType == 0) {
                    if (this.licowitch.hasLineOfSight(target)) {
                        if (peppermintCooldown <= 0 && licowitch.getRandom().nextBoolean()) {
                            enqueuedAttackType = 1;
                            peppermintCooldown = 80;
                        } else if (hexCooldown <= 0 && licowitch.getRandom().nextBoolean()) {
                            enqueuedAttackType = 2;
                            hexCooldown = 200;
                        } else if (potionCooldown <= 0 && distance < 10.0D && !target.hasEffect(MobEffects.HUNGER)) {
                            enqueuedAttackType = 3;
                            licowitch.updateHeldItems = false;
                            licowitch.setItemInHand(InteractionHand.MAIN_HAND, LicowitchEntity.hungerPotion.copy());
                            potionCooldown = 100;
                        }
                    }
                } else {
                    if (enqueuedAttackType == 1 && distance < 10.0D) {
                        this.licowitch.setAnimation(LicowitchEntity.ANIMATION_SPELL_0);
                    }
                    if ((enqueuedAttackType == 2 || enqueuedAttackType == 4) && distance < 7.0D) {
                        this.licowitch.setAnimation(LicowitchEntity.ANIMATION_SPELL_1);
                    }
                    if (enqueuedAttackType == 3 && distance < 10.0D) {
                        this.licowitch.setAnimation(licowitch.getMainArm() == HumanoidArm.RIGHT ? LicowitchEntity.ANIMATION_SWING_RIGHT : LicowitchEntity.ANIMATION_SWING_LEFT);
                    }
                }
            }
            if (enqueuedAttackType == 1 && licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_0 && licowitch.getAnimationTick() == 18) {
                peppermintAttack(target);
                enqueuedAttackType = 0;
            }
            if (enqueuedAttackType == 2 && licowitch.getAnimation() == LicowitchEntity.ANIMATION_SPELL_1 && licowitch.getAnimationTick() == 36) {
                hexAttack(target);
                enqueuedAttackType = 0;
            }
            if (enqueuedAttackType == 3 && (licowitch.getAnimation() == LicowitchEntity.ANIMATION_SWING_RIGHT || licowitch.getAnimation() == LicowitchEntity.ANIMATION_SWING_LEFT) && licowitch.getAnimationTick() == 6) {
                potionAttack(target);
                licowitch.updateHeldItems = true;
                enqueuedAttackType = 0;
            }
        }
        duration++;
    }

protected void hurtCollidingEntities(LivingEntityPatch<?> entitypatch, float prevElapsedTime, float elapsedTime, EntityState prevState, EntityState state, Phase phase) {
		LivingEntity entity = entitypatch.getOriginal();
		float prevPoseTime = prevState.attacking() ? prevElapsedTime : phase.preDelay;
		float poseTime = state.attacking() ? elapsedTime : phase.contact;
		List<Entity> list = this.getPhaseByTime(elapsedTime).getCollidingEntities(entitypatch, this, prevPoseTime, poseTime, this.getPlaySpeed(entitypatch, this));

		if (!list.isEmpty()) {
			HitEntityList hitEntities = new HitEntityList(entitypatch, list, phase.getProperty(AttackPhaseProperty.HIT_PRIORITY).orElse(HitEntityList.Priority.DISTANCE));
			int maxStrikes = this.getMaxStrikes(entitypatch, phase);

			while (entitypatch.getCurrentlyActuallyHitEntities().size() < maxStrikes && hitEntities.next()) {
				Entity target = hitEntities.getEntity();
				LivingEntity trueEntity = this.getTrueEntity(target);

				if (trueEntity != null && trueEntity.isAlive() && !entitypatch.getCurrentlyAttackTriedEntities().contains(trueEntity) && !entitypatch.isTargetInvulnerable(target)) {
					if (target instanceof LivingEntity || target instanceof PartEntity) {
						AABB aabb = target.getBoundingBox();

						if (MathUtils.canBeSeen(target, entity, target.position().distanceTo(entity.getEyePosition()) + aabb.getCenter().distanceTo(new Vec3(aabb.maxX, aabb.maxY, aabb.maxZ)))) {
							EpicFightDamageSource damagesource = this.getEpicFightDamageSource(entitypatch, target, phase);
							int prevInvulTime = target.invulnerableTime;
							target.invulnerableTime = 0;

							AttackResult attackResult = entitypatch.attack(damagesource, target, phase.effectiveHand(entitypatch));
							target.invulnerableTime = prevInvulTime;

							if (attackResult.resultType.dealtDamage()) {
                                SoundEvent hitSound = this.getHitSound(entitypatch, phase);

                                if (hitSound != null) {
								    target.level().playSound(null, target.getX(), target.getY(), target.getZ(), hitSound, target.getSoundSource(), 1.0F, 1.0F);
                                }

								this.spawnHitParticle((ServerLevel)target.level(), entitypatch, target, phase);
							}

							entitypatch.getCurrentlyAttackTriedEntities().add(trueEntity);

							if (attackResult.resultType.shouldCount()) {
								entitypatch.getCurrentlyActuallyHitEntities().add(trueEntity);
							}
						}
					}
				}
			}
		}
	}

@Override
    protected void onImpact(RayTraceResult result) {
        if (!this.world.isRemote) {
            AxisAlignedBB hitBB = this.getEntityBoundingBox().grow(4.0D, 2.0D, 4.0D);
            List<EntityLivingBase> hitEntities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, hitBB);
            if (!hitEntities.isEmpty()) {
                Iterator<EntityLivingBase> hitEntitiesIT = hitEntities.iterator();
                while (hitEntitiesIT.hasNext()) {
                    EntityLivingBase affectedEntity = hitEntitiesIT.next();
                    double entityDst = this.getDistanceSq(affectedEntity);
                    if (entityDst < 16.0D) {
                        double modifier = 1.0D - Math.sqrt(entityDst) / 4.0D;
                        if (affectedEntity == result.entityHit) {
                            modifier = 1.0D;
                        }
                        PotionEffect effect = ItemRegistry.ELIXIR.createPotionEffect(getElixirStack(), modifier);
                        SplashPotionEvent event = new SplashPotionEvent(this, affectedEntity, effect, effect.getPotion().isInstant());
                        MinecraftForge.EVENT_BUS.post(event);
                        if(!event.isCanceled()) {
                        	affectedEntity.addPotionEffect(effect);
                        }
                    }
                }
            }
            this.world.playEvent(2002, new BlockPos(this), ItemRegistry.ELIXIR.getColorMultiplier(getElixirStack(), 0));
            this.entityDropItem(new ItemStack(ItemRegistry.ELIXIR.getDentrothystType(getElixirStack()) == EnumDentrothyst.GREEN ? ItemRegistry.DENTROTHYST_SHARD_GREEN : ItemRegistry.DENTROTHYST_SHARD_ORANGE,
            		this.world.rand.nextInt(2) + 2), this.height / 2);
            if(this.world.rand.nextInt(2) == 0) this.entityDropItem(EnumItemMisc.RUBBER_BALL.create(1), this.height / 2);
            this.setDead();
        }
    }

@Override
    protected void onHitEntity(EntityHitResult hitResult) {
        Entity hit = hitResult.getEntity();
        if (properties().damageMultiplier() <= 0f) {
            if (!level().isClientSide() && hit instanceof LivingEntity target) {
                ItemStack arrow = getPickupItem();
                if (arrow.getItem() instanceof IVampirismQuarrel<?> quarrel) {
                    quarrel.onHitEntity(arrow, target, this, getOwner());
                }
            }
            return;
        }

        if (this.ignoreHurtTimer && !level().isClientSide() && hit instanceof LivingEntity living && living.getData(ModAttachments.QUARREL_HURT_BYPASS).registerHit(living.level().getGameTime())) {
            living.invulnerableTime = 0;
        }

        float knockbackFactor = properties().knockbackMultiplier();
        Vec3 preHitVelocity = knockbackFactor != 1f && hit instanceof LivingEntity ? hit.getDeltaMovement() : null;

        double ballistaScale = ballistaDamageScale();
        if (ballistaScale > 1) {
            double launchDamage = launchBaseDamage(properties());
            super.setBaseDamage(launchDamage * ballistaScale);
            super.onHitEntity(hitResult);
            super.setBaseDamage(launchDamage);
        } else {
            super.onHitEntity(hitResult);
        }

        if (preHitVelocity != null && hit.isAlive()) {
            Vec3 imparted = hit.getDeltaMovement().subtract(preHitVelocity);
            hit.setDeltaMovement(preHitVelocity.add(imparted.scale(knockbackFactor)));
            hit.hurtMarked = true; // resync the corrected velocity to clients
        }
    }

@Override
	protected void onHit(HitResult result) {
		if (!this.level().isClientSide) {

			this.clearInvincibility();

			if (result.getType() == HitResult.Type.ENTITY) {
				Entity entity = ((EntityHitResult) result).getEntity();

				if (entity == this.getOwner())
					return;

				if (this.getOwner() != null) {
					if (entity.hurt(entity.damageSources().indirectMagic(this, this.getOwner()), this.isSkullInvulnerable() ? 24.0F : 8.0F)) {
						if (entity.isAlive()) {
							this.doEnchantDamageEffects((LivingEntity) this.getOwner(), entity);
						}
					}
				} else {
					entity.hurt(entity.damageSources().magic(), this.isSkullInvulnerable() ? 16.0F : 5.0F);
				}

				if (entity instanceof LivingEntity) {

					((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.WITHER, 20 * 30, 1));

				}
			}

			float explosionRadius = this.isSkullInvulnerable() ? 1.5F : 1.0F;
			WitherExplosion explosion = new WitherExplosion(this.level(), this, this.getX(), this.getY(), this.getZ(), explosionRadius, false, Explosion.BlockInteraction.DESTROY);


			if (!net.minecraftforge.event.ForgeEventFactory.onExplosionStart(this.level(), explosion)) {
				explosion.explode();
				explosion.finalizeExplosion(true);

				for(ServerPlayer serverPlayer : this.level().getServer().getLevel(this.level().dimension()).players()) {
					if (serverPlayer.distanceToSqr(explosion.getPosition().x, explosion.getPosition().y, explosion.getPosition().z) < 4096.0D) {
						serverPlayer.connection.send(new ClientboundExplodePacket(explosion.getPosition().x, explosion.getPosition().y, explosion.getPosition().z, explosionRadius, explosion.getToBlow(), explosion.getHitPlayers().get(serverPlayer)));
					}
				}
			}

			EnigmaticLegacy.packetInstance.send(PacketDistributor.NEAR.with(() -> new PacketDistributor.TargetPoint(this.getX(), this.getY(), this.getZ(), 64, this.level().dimension())), new PacketWitherParticles(this.getX(), this.getY() + (this.getBbHeight() / 2), this.getZ(), this.isSkullInvulnerable() ? 20 : 16, false));

			this.discard();
		}

	}

@Override
  protected void onHitEntity(EntityHitResult result) {
    Entity target = result.getEntity();
    DamageSource source;
    // use a melee damage type if its targeting enderman
    if (TinkerEffects.needsEnderferenceOverride(target)) {
      source = CombatHelper.damageSource(TinkerDamageTypes.MELEE_THROWN, this, this.getOwner());
    } else {
      source = damageSources().thrown(this, this.getOwner());
    }
    boolean hit = target.hurt(source, power);

    if (hit && knockback > 0 && target instanceof LivingEntity living) {
      // knockback logic based on arrows
      double resistance = Math.max(0, 1 - living.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE));
      Vec3 motion = this.getDeltaMovement().multiply(1, 0, 1).normalize().scale(knockback * 0.6 * resistance);
      if (motion.lengthSqr() > 0) {
        target.push(motion.x, 0.1f, motion.z);
      }
    }

    Level level = level();
    if (!level.isClientSide) {
      if ((!hit || reclaim) && !this.isRemoved()) {
        this.spawnAtLocation(stack.copy());
      } else {
        level.broadcastEntityEvent(this, (byte) 3); // TODO: find the proper constant for this event ID
      }
      this.discard();
    }
  }

protected void onHitEntity(EntityHitResult entityHitResult) {
        Entity entity = entityHitResult.getEntity();
        Entity owner = this.getOwner();
        float damage = this.getDamage();
        if(owner instanceof GumbeeperEntity gumbeeper && gumbeeper.getPossessedByLicowitchId() != -1){
            LicowitchEntity witch = gumbeeper.getPossessingLicowitch(level());
            if(witch != null && entity instanceof LivingEntity living && witch.isFriendlyFire(living)){
                return;
            }
        }
        DamageSource damageSource = ACDamageTypes.causeGumballDamage(entity.level().registryAccess(), owner);
        if ((owner == null || !entity.is(owner) && !entity.isAlliedTo(owner) && !owner.isAlliedTo(entity))) {
            this.playSound(ACSoundRegistry.GUMBALL_HIT.get());
            entity.hurt(damageSource, damage);
        }
        if(splitsOnHit()){
            for(int i = 0; i < 3; i++){
                GumballEntity gumballEntity = ACEntityRegistry.GUMBALL.get().create(level());
                Vec3 vec3 = this.getDeltaMovement().normalize();
                float f = -((float) Mth.atan2(vec3.x, vec3.z)) * 180.0F / (float) Math.PI;
                Vec3 vec31 = new Vec3(0, 0, this.isExplosive() ? 0.7F : 1.5F).yRot((float) -Math.toRadians(f + 30.0F - 30.0F * i));
                gumballEntity.setPos(entity.getEyePosition().add(vec31));
                gumballEntity.setDeltaMovement(vec31);
                gumballEntity.setSplitsOnHit(false);
                gumballEntity.setDamage(this.getDamage());
                gumballEntity.setTargetsOnBounce(this.targetsOnBounce());
                gumballEntity.setExplosive(this.isExplosive());
                gumballEntity.setMaximumBounces(this.getMaximumBounces());
                level().addFreshEntity(gumballEntity);
            }
            this.discard();
        }
    }

@Override
    protected void onHit(@NotNull HitResult movingObject) {
        boolean flag = false;
        Entity shootingEntity = this.getOwner();
        if (!this.level.isClientSide) {
            if (movingObject.getType() == HitResult.Type.ENTITY && !((EntityHitResult) movingObject).getEntity().is(shootingEntity)) {
                Entity entity = ((EntityHitResult) movingObject).getEntity();
                if (shootingEntity != null && shootingEntity.equals(entity)) {
                    flag = true;
                } else {
                    if (entity instanceof LivingEntity) {
                        ((LivingEntity) entity).addEffect(new MobEffectInstance(MobEffects.LEVITATION, 100, 0));
