@Override
    public boolean hurt(DamageSource source, float amount) {
        if (getSynchedData(ARMOUR) > 0 && !level().isClientSide && !DamageUtil.isEnvironmentalDamage(source)) {
            float armourDamage = amount;

            if (source.is(DamageTypeTags.IS_PROJECTILE) && !DamageUtil.isMagicDamage(source) && !source.is(AoADamageTypes.HEAVY_GUN))
                armourDamage *= 0.25f;

            if (!source.is(DamageTypeTags.BYPASSES_ARMOR)) {
                if (DamageUtil.isMeleeDamage(source) && source.getDirectEntity() instanceof LivingEntity attacker) {
                    ItemStack weapon = attacker.getMainHandItem();

                    if (weapon.canPerformAction(ItemAbilities.PICKAXE_DIG)) {
                        armourDamage *= 1 + (weapon.getDestroySpeed(Blocks.STONE.defaultBlockState()) * 0.075f) + (float)attacker.getAttributeValue(Attributes.MINING_EFFICIENCY) * 0.04f;
                    }
                    else {
                        armourDamage *= 0.5f;
                    }
                }
                else if (source.is(DamageTypeTags.IS_EXPLOSION)) {
                    armourDamage *= 1.25f;
                }

                if (IntegrationManager.isTESActive())
                    TESIntegration.sendParticle(this, armourDamage, 0xFFAAAAAA);

                ParticleBuilder.forRandomPosInEntity(ParticleTypes.CRIT, this)
                        .spawnNTimes(50)
                        .sendToAllPlayersTrackingEntity(this);

                updateArmour(getSynchedData(ARMOUR) - armourDamage);
            }
        }

        return super.hurt(source, amount);
    }

@Override
    public boolean hurt(DamageSource source, float damage) {
        Entity entity = source.getDirectEntity();

        if (!source.is(DamageTypeTags.BYPASSES_SHIELD) &&!this.isNoAi() && this.getAttackState() == 4) {
            Vec3 vector3d2 = source.getSourcePosition();
            if (vector3d2 != null) {
                Vec3 vector3d = this.getViewVector(1.0F);
                Vec3 vector3d1 = vector3d2.vectorTo(this.position()).normalize();
                vector3d1 = new Vec3(vector3d1.x, 0.0D, vector3d1.z);
                if(vector3d1.dot(vector3d) < 0.0D){
                    if (this.attackTicks >= 7 && this.attackTicks <= 17) {
                        if(entity instanceof LivingEntity living) {
                            this.block_stage = 1;
                            if (!this.level().isClientSide ) {
                                living.addEffect(new MobEffectInstance(ModEffect.EFFECTSTUN.get(), 50));
                            }
                            this.playSound(ModSounds.PARRY.get(),0.8F,1.0F);
                        }
                        return false;

                    }else if (this.attackTicks > 17 && this.attackTicks <= 43){
                        if(entity instanceof LivingEntity living) {
                            this.block_stage =2;
                            living.knockback(0.5F, this.getX() - living.getX(), this.getZ() - living.getZ());
                        }
                        return false;
                    } else{
                        return super.hurt(source, damage);
                    }
                }
            }
        }


        return super.hurt(source, damage);
    }

@SubscribeEvent
    public static void onEntityHit(LivingAttackEvent event)
    {
        if (event.getSource().getEntity() instanceof Player attacker && !(event.getEntity() instanceof Player))
        {
            Level level = attacker.level();
            ItemStack stack = attacker.getMainHandItem();
            if (!(stack.getItem() instanceof SoulspringLampItem)) return;

            LivingEntity target = event.getEntity();

            // If fuel < 64 and target NOT player
            if (getFuel(stack) < 64
            && target.getMobType() != MobType.UNDEAD
            && !target.getPersistentData().getBoolean("SoulSucked"))
            {
                target.getPersistentData().putBoolean("SoulSucked", true);

                // Add fuel
                addFuel(stack, (int) Math.min(8, target.getMaxHealth() / 2));
                float extraDamage = Math.max(0, 8 - event.getAmount());
                if (extraDamage > 0)
                    target.hurt(level.damageSources().playerAttack(attacker), extraDamage);

                // Spawn particles
                if (!target.level().isClientSide)
                {
                    int particleCount = (int) CSMath.clamp(target.getBbWidth() * target.getBbWidth() * target.getBbHeight() * 3, 5, 50);
                    WorldHelper.spawnParticleBatch(attacker.level(), ParticleTypes.SOUL, target.getX(), target.getY() + target.getBbHeight() / 2, target.getZ(),
                                                   target.getBbWidth() / 2, target.getBbHeight() / 2, target.getBbWidth() / 2, particleCount, 0.05);
                }
                // Play soul stealing sound
                if (attacker.level().isClientSide)
                {   WorldHelper.playEntitySound(ModSounds.SOUL_LAMP_ON, attacker, attacker.getSoundSource(), 1f, (float) Math.random() / 5f + 1.3f);
                }
            }
        }
    }

@Override
	protected void onHitEntity(@NotNull EntityHitResult result) {
		super.onHitEntity(result);
		if (this.level().isClientSide) {
			return;
		}
		Entity entity = result.getEntity();
		if (entity.getType() == EntityType.GHAST && this.level().dimension() == Level.OVERWORLD) {
			this.level().levelEvent(LevelEvent.PARTICLES_SPELL_POTION_SPLASH, blockPosition(), PARTICLE_COLOR);
			DamageSource source = entity.damageSources().thrown(this, getOwner());
			entity.hurt(source, 0);

			// Ghasts render as if they are looking straight ahead, but the look y component
			// can actually be nonzero, correct for that
			Vec3 lookVec = entity.getLookAngle();
			Vec3 vec = new Vec3(lookVec.x(), 0, lookVec.z()).normalize();

			// Position chosen to appear roughly in the ghast's face
			((ServerLevel) this.level()).sendParticles(new ItemParticleOption(ParticleTypes.ITEM, new ItemStack(Items.GHAST_TEAR)),
					entity.getX() + (2.3 * vec.x), entity.getY() + vec.y + 2.6, entity.getZ() + (2.3 * vec.z),
					40,
					Math.abs(vec.z) + 0.15, 0.2, Math.abs(vec.x) + 0.15, 0.2);

			LootTable table = this.level().getServer().getLootData().getLootTable(GHAST_LOOT_TABLE);
			LootParams.Builder builder = new LootParams.Builder(((ServerLevel) level()));
			builder.withParameter(LootContextParams.THIS_ENTITY, entity);
			builder.withParameter(LootContextParams.ORIGIN, entity.position());
			builder.withParameter(LootContextParams.DAMAGE_SOURCE, source);

			LootParams context = builder.create(LootContextParamSets.ENTITY);
			for (ItemStack stack : table.getRandomItems(context)) {
				ItemEntity item = entity.spawnAtLocation(stack, 2);
				item.setDeltaMovement(item.getDeltaMovement().add(vec.scale(0.4)));
			}
		} else {
			convertBlock(BlockPos.containing(result.getLocation()));
		}
		discard();
	}

