@Override
    public boolean hurt(DamageSource source, float amount) {
        boolean flag = false;
        if (amount > 0.0F && this.isDamageSourceBlocked(source)) {
            net.minecraftforge.event.entity.living.ShieldBlockEvent ev = net.minecraftforge.common.ForgeHooks.onShieldBlock(this, source, amount);
            if(!ev.isCanceled()) {
                if(ev.shieldTakesDamage()) {
                    this.hurtCurrentlyUsedShield(amount);
                }
                amount -= ev.getBlockedDamage();
                if (!source.is(DamageTypeTags.IS_PROJECTILE)) {
                    Entity entity = source.getDirectEntity();
                    if (entity instanceof LivingEntity) {
                        this.blockUsingShield((LivingEntity)entity);
                    }
                }

                flag = true;
            }
        }
        if (source.is(DamageTypeTags.IS_FIRE) && !source.is(DamageTypes.LAVA)){
            return false;
        }
        if (flag) {
            this.playSound(SoundEvents.SHIELD_BLOCK, 1.0F, 0.8F + this.level.random.nextFloat() * 0.4F);
            this.level.broadcastEntityEvent(this, (byte)29);
            if (amount <= 1.0F){
                return false;
            }
        }
        if (!this.isGuarding() && this.coolTime > 0 && !this.canDisableShield(source) && !source.is(DamageTypeTags.BYPASSES_ARMOR)){
            this.coolTime -= (int) (amount * 10);
        }
        if (this.level instanceof ServerLevel serverLevel && !this.isDamageSourceBlocked(source)){
            if (!this.getItemBySlot(EquipmentSlot.CHEST).isEmpty()) {
                int j = (int) Math.min(amount, 10);
                for (int i = 0; i < j; ++i) {
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, new ItemParticleOption(ParticleTypes.ITEM, this.getItemBySlot(EquipmentSlot.CHEST)), this);
                }
            }
        }
        return super.hurt(source, amount);
    }

public boolean hurt(DamageSource pSource, float pAmount) {
        int particles = 5;
        int efficiency = 0;
        boolean damage = false;
        if (!this.level.isClientSide && !this.isEmerging()) {
            if (pSource.is(DamageTypeTags.IS_EXPLOSION) || pSource.is(DamageTypeTags.IS_FIRE)){
                return false;
            }
            if (this.empowered > 0 && !pSource.is(DamageTypeTags.BYPASSES_INVULNERABILITY)){
                this.level.broadcastEntityEvent(this, (byte) 6);
                this.playSound(SoundEvents.LAVA_EXTINGUISH, 1.0F, 0.5F);
                if (pSource.is(DamageTypes.IN_WALL)){
                    if (this.destroyBlocksTick <= 0) {
                        this.destroyBlocksTick = 20;
                    }
                }
                return false;
            }
            if (pSource.is(DamageTypes.IN_WALL) || pSource.is(DamageTypes.OUTSIDE_BORDER)){
                if (this.getTrueOwner() instanceof Apostle apostle) {
                    this.teleportTowards(apostle);
                }
            }
            if (ModDamageSource.physicalAttacks(pSource)) {
                if (pSource.getDirectEntity() instanceof LivingEntity living) {
                    if (living.getMainHandItem().isCorrectToolForDrops(this.getState())){
                        damage = true;
                        efficiency += EnchantmentHelper.getBlockEfficiency(living);
                    }
                }
            }
            if (damage){
                pAmount *= 2.0F + (efficiency / 2.0F);
                particles = 20;
            }
            if (this.level instanceof ServerLevel serverLevel){
                for(int i = 0; i < particles; ++i) {
                    ServerParticleUtil.addParticlesAroundSelf(serverLevel, this.getParticles(), this);
                }
            }
        }
        return super.hurt(pSource, pAmount);
    }

protected void onImpact(RayTraceResult target) {
		if(target.entityHit instanceof EntityFortressBossProjectile == false) {
			if (target.entityHit != null && target.entityHit instanceof EntityLivingBase) {
				if(target.entityHit instanceof EntityFortressBoss) {
					EntityFortressBoss boss = (EntityFortressBoss) target.entityHit;
					Vec3d ray = new Vec3d(this.motionX, this.motionY, this.motionZ);
					ray = ray.normalize().scale(64.0D);
					int shieldHit = EntityFortressBoss.rayTraceShield(boss.shield, new Vec3d(boss.posX + EntityFortressBoss.SHIELD_OFFSET_X, boss.posY + EntityFortressBoss.SHIELD_OFFSET_Y, boss.posZ + EntityFortressBoss.SHIELD_OFFSET_Z), boss.getShieldRotationYaw(1), boss.getShieldRotationPitch(1), boss.getShieldRotationYaw(1), boss.getShieldExplosion(1), new Vec3d(this.posX, this.posY, this.posZ), ray, false);
					if(shieldHit >= 0) {
						if(!this.world.isRemote) {
							boss.shield.setActive(shieldHit, false);

							this.world.playSound(null, this.posX, this.posY, this.posZ, SoundRegistry.FORTRESS_BOSS_SHIELD_DOWN, SoundCategory.HOSTILE, 1.0F, 1.0F);

							double angle = Math.PI * 2.0D / 18;
							for(int i = 0; i < 18; i++) {
								Vec3d dir = new Vec3d(Math.sin(angle * i), 0, Math.cos(angle * i));
								dir = dir.normalize();
								float speed = 0.8F;
								EntityFortressBossProjectile bullet = new EntityFortressBossProjectile(this.world, this.getOwner());
								bullet.setLocationAndAngles(boss.posX, boss.posY, boss.posZ, 0, 0);
								bullet.shoot(dir.x, dir.y, dir.z, speed, 0.0F);
								this.world.spawnEntity(bullet);
							}
						}
					} else {
						boss.attackEntityFrom(DamageSource.GENERIC, 10);
					}

					if(!this.world.isRemote) {
						boss.setFloating(false);
					}
				} else {
					target.entityHit.attackEntityFrom(DamageSource.causeIndirectMagicDamage(this, this.getOwner()), 2);
				}

				if(!this.world.isRemote) {
					this.setDead();
				}
			} else if(target.typeOfHit == RayTraceResult.Type.BLOCK) {
				this.setDead();
			}
		}
	}

@Override
    protected void onHit(HitResult result) {
        HitResult.Type raytraceresult$type = result.getType();
        Vec3 vec3 = this.getDeltaMovement();
        double motionX = vec3.x();
        double motionY = vec3.y();
        double motionZ = vec3.z();
        if (raytraceresult$type == HitResult.Type.BLOCK) {
            BlockHitResult hitResult = (BlockHitResult) result;
            BlockState blockstate = this.level.getBlockState(hitResult.getBlockPos());
            if (!blockstate.getCollisionShape(this.level, hitResult.getBlockPos()).isEmpty()) {
                Direction face = hitResult.getDirection();
                blockstate.onProjectileHit(this.level, blockstate, hitResult, this);
                if (face.getAxis() == Direction.Axis.X) {
                    motionX = -motionX;
                } else if (face.getAxis() == Direction.Axis.Z) {
                    motionZ = -motionZ;
                } else if (face.getAxis().isVertical()) {
                    motionY = -motionY;
                }
                Vec3 vec31 = new Vec3(motionX, motionY, motionZ);
                this.setDeltaMovement(vec31);
                if (this.getBounceTimes() >= 6) {
                    this.explode();
                } else {
                    this.playSound(SoundEvents.GENERIC_SPLASH, 1.0F, (this.random.nextFloat() - this.random.nextFloat()) * 0.2F + 1.0F);
                    this.setBounceTimes(this.getBounceTimes() + 1);
                }
            }
        } else if (raytraceresult$type == HitResult.Type.ENTITY) {
            Entity entity = ((EntityHitResult) result).getEntity();
            if (!this.level.isClientSide) {
                if (this.canHitEntity(entity)) {
                    if (this.getBounceTimes() >= 6) {
                        this.explode();
                    } else {
                        if (entity.hurt(ModDamageSource.indirectDrench(this, this.getOwner() == null ? this : this.getOwner()), this.damage + this.getExtraDamage())){
                            this.setBounceTimes(this.getBounceTimes() + 1);
                        }
                    }
                }
            }
        }
    }

public void tick() {
        super.tick();
        if (this.level instanceof ServerLevel serverLevel) {
            float f5 = (float) Math.PI * this.radius() * this.radius();
            if (serverLevel.random.nextFloat() <= 0.05F) {
                for (int j1 = 0; j1 < serverLevel.random.nextInt(16) + 1; ++j1) {
                    for (int k1 = 0; (float) k1 < f5; ++k1) {
                        float f6 = this.random.nextFloat() * ((float) Math.PI * 2F);
                        float f7 = Mth.sqrt(this.random.nextFloat()) * this.radius();
                        float f8 = Mth.cos(f6) * f7;
                        float f9 = Mth.sin(f6) * f7;
                        serverLevel.sendParticles(ParticleTypes.WITCH, this.getX() + (double) f8, this.getY(), this.getZ() + (double) f9, 0, 0, 0.5D, 0, 0.5F);
                    }
                }
            }
        }
        List<LivingEntity> targets = new ArrayList<>();
        for (Entity entity : this.level.getEntitiesOfClass(Entity.class, this.getBoundingBox())) {
            LivingEntity livingEntity = MobUtil.getLivingTarget(entity);
            if (livingEntity != null) {
                if (this.getOwner() != null) {
                    if (livingEntity != this.getOwner() && !MobUtil.areAllies(this.getOwner(), livingEntity)) {
                        targets.add(livingEntity);
                    }
                } else {
                    targets.add(livingEntity);
                }
            }
        }
        if (!targets.isEmpty()){
            for (LivingEntity livingEntity : targets) {
                livingEntity.hurt(damageSources().magic(), 4.0F);
                if (this.getOwner() != null){
                    float damage = 4.0F;
                    if (this.getOwner() instanceof Mob mob && mob.getAttribute(Attributes.ATTACK_DAMAGE) != null){
                        damage = (float) (mob.getAttributeValue(Attributes.ATTACK_DAMAGE) / 2.0F);
                    }
                    livingEntity.hurt(damageSources().indirectMagic(this, this.getOwner()), damage);
                }
            }
        }
        if (this.tickCount >= this.getDuration()) {
            this.discard();
        }
    }

