@Override
	protected void tick(ServerLevel level, Yak yak, long gameTime) {
		Brain<?> brain = yak.getBrain();
		LivingEntity attackTarget = brain.getMemory(MemoryModuleType.ATTACK_TARGET).orElse(null);

		List<LivingEntity> list = level.getNearbyEntities(LivingEntity.class, TargetingConditions.forCombat().selector(entity -> Objects.equals(entity, attackTarget)), yak, yak.getBoundingBox());

		if (list.isEmpty()) {
			Optional<WalkTarget> destination = brain.getMemory(MemoryModuleType.WALK_TARGET);
			Optional<Vec3> ramTarget = brain.getMemory(MemoryModuleType.RAM_TARGET);
			if (destination.isEmpty() || ramTarget.isEmpty() || destination.get().getTarget().currentPosition().closerThan(ramTarget.get(), 0.25D)) {
				this.finishRam(level, yak);
			}
			return;
		}

		LivingEntity target = list.get(0);
		target.hurt(level.damageSources().mobAttack(yak), (float) yak.getAttributeValue(Attributes.ATTACK_DAMAGE));

		int speedFactor = yak.hasEffect(MobEffects.MOVEMENT_SPEED) ? yak.getEffect(MobEffects.MOVEMENT_SPEED).getAmplifier() + 1 : 0;
		int slownessFactor = yak.hasEffect(MobEffects.MOVEMENT_SLOWDOWN) ? yak.getEffect(MobEffects.MOVEMENT_SLOWDOWN).getAmplifier() + 1 : 0;
		float effectSpeed = 0.25F * (speedFactor - slownessFactor);

		float speedForce = Mth.clamp(yak.getSpeed() * RAM_SPEED_FORCE_FACTOR, 0.2F, 3.0F) + effectSpeed;
		float knockbackForce = target.isDamageSourceBlocked(level.damageSources().mobAttack(yak)) ? 0.5F : 1.0F;

		target.knockback((knockbackForce * speedForce) * this.getKnockbackForce.applyAsDouble(yak), this.ramDirection.x(), this.ramDirection.z());
		this.finishRam(level, yak);
		level.playSound(null, yak, this.getImpactSound.apply(yak), SoundSource.NEUTRAL, 1.0F, 1.0F);
	}

public void attackMobs(LivingEntity pTarget, Player pPlayer, ItemStack pStack){
        float f = (float)pPlayer.getAttributeValue(Attributes.ATTACK_DAMAGE);
        float f1 = EnchantmentHelper.getDamageBonus(pStack, pTarget.getMobType());
        int j = EnchantmentHelper.getFireAspect(pPlayer);
        double area = 1.75D;
        area += pStack.getEnchantmentLevel(ModEnchantments.RADIUS.get());
        for (LivingEntity livingentity : pPlayer.level.getEntitiesOfClass(LivingEntity.class, pTarget.getBoundingBox().inflate(area, 0.25D, area))) {
            if (livingentity != pPlayer && livingentity != pTarget && !MobUtil.areAllies(pPlayer, livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && livingentity != pPlayer.getVehicle()) {
                livingentity.knockback(0.4F, (double) Mth.sin(pPlayer.getYRot() * ((float) Math.PI / 180F)), (double) (-Mth.cos(pPlayer.getYRot() * ((float) Math.PI / 180F))));
                if (livingentity.hurt(pPlayer.damageSources().playerAttack(pPlayer), f + f1)) {
                    if (j > 0) {
                        livingentity.setSecondsOnFire(j * 4);
                    }
                    EnchantmentHelper.doPostHurtEffects(livingentity, pPlayer);
                    EnchantmentHelper.doPostDamageEffects(pPlayer, livingentity);
                }
            }
        }
        for (LivingEntity livingentity : pPlayer.level.getEntitiesOfClass(LivingEntity.class, pTarget.getBoundingBox().inflate(area * 2.0D, 1.0D, area * 2.0D))) {
            if (livingentity != pPlayer && livingentity != pTarget && !MobUtil.areAllies(pPlayer, livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && livingentity != pPlayer.getVehicle()) {
                Vec3 vec3 = livingentity.position().subtract(pTarget.position());
                vec3 = vec3.normalize();
                livingentity.level.playSound((Player) null, livingentity.getX(), livingentity.getY(), livingentity.getZ(), ModSounds.GRAVITY.get(), pPlayer.getSoundSource(), 1.0F, 1.0F);
                MobUtil.pull(livingentity, vec3.x, vec3.y, vec3.z);
                if (livingentity.level instanceof ServerLevel serverLevel) {
                    serverLevel.sendParticles(new TeleportInShockwaveParticleOption(), livingentity.getX(), livingentity.getY() + 0.25F, livingentity.getZ(), 0, 0, 0, 0, 0.5F);
                }
            }
        }

        pPlayer.level.playSound((Player) null, pPlayer.getX(), pPlayer.getY(), pPlayer.getZ(), ModSounds.BONEHEAD_HAMMER_IMPACT.get(), pPlayer.getSoundSource(), 1.0F, 1.0F);
    }

public static void slam(BroodEetle broodEetle, RandomSource random, float power) {
		ServerLevel world = (ServerLevel) broodEetle.level();
		double posX = broodEetle.getX();
		double posY = broodEetle.getY();
		double posZ = broodEetle.getZ();
		for (BlockState state : sampleGround(world, broodEetle.blockPosition().below(), random)) {
			world.sendParticles(new BlockParticleOption(EEParticleTypes.FAST_BLOCK.get(), state), posX, posY, posZ, 8, 0.0D, 0.0D, 0.0D, 0.225F);
		}
		float attackDamage = (float) broodEetle.getAttributeValue(Attributes.ATTACK_DAMAGE) * power;
		double knockback = broodEetle.getAttributeValue(Attributes.ATTACK_KNOCKBACK);
		for (LivingEntity livingEntity : world.getEntitiesOfClass(LivingEntity.class, broodEetle.getBoundingBox().inflate(4.5D), entity1 -> entity1 != broodEetle)) {
			float damage;
			if ((int) attackDamage > 0.0F) {
				damage = attackDamage / 2.0F + random.nextInt((int) attackDamage);
			} else {
				damage = attackDamage;
			}

			if (livingEntity instanceof AbstractEetle) {
				damage = 0.0F;
			}

			if (livingEntity.hurt(world.damageSources().mobAttack(broodEetle), damage)) {
				broodEetle.doEnchantDamageEffects(broodEetle, livingEntity);
				double knockbackForce = knockback - livingEntity.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
				float inAirFactor = livingEntity.onGround() ? 1.0F : 0.75F;
				Vec3 horizontalVelocity = new Vec3(livingEntity.getX() - posX, 0.0D, livingEntity.getZ() - posZ).normalize().scale((knockbackForce * (random.nextFloat() * 0.75F + 0.5F)) * inAirFactor * power);
				livingEntity.push(horizontalVelocity.x, knockbackForce * 0.5F * random.nextFloat() * 0.5F * inAirFactor, horizontalVelocity.z);
				livingEntity.hurtMarked = true;
			}
		}
	}

