private void onSting(HitResult result) {
		HitResult.Type resultType = result.getType();
		if (resultType == HitResult.Type.ENTITY) {
			EntityHitResult entityResult = (EntityHitResult) result;
			Entity entity = entityResult.getEntity();
			if (entity.hurt(this.level().damageSources().mobProjectile(this, this), (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue())) {
				this.setInflated(true);
				this.removeFireDirection();
				this.stuckInBlock = false;

				if (!this.getActiveEffects().isEmpty() && entity instanceof LivingEntity) {
					for (MobEffectInstance effects : this.getActiveEffects()) {
						((LivingEntity) entity).addEffect(effects);
					}
					this.removeAllEffects();
				}
			}
		} else {
			BlockHitResult blockraytraceresult = (BlockHitResult) result;
			this.stuckInBlockState = this.level().getBlockState(blockraytraceresult.getBlockPos());
			this.stuckInBlock = true;

			Vec3 end = result.getLocation();
			this.setPos(end.x(), end.y(), end.z());
			this.setDeltaMovement(Vec3.ZERO);

			if (!this.level().isClientSide) {
				NetworkUtil.setPlayingAnimation(this, EEPlayableEndimations.PUFF_BUG_LAND);
			}

			this.level().playSound(null, this, EESoundEvents.PUFFBUG_LAND.get(), SoundSource.HOSTILE, 0.5F, this.getVoicePitch());
		}
	}

public void lifeSpanDamage(){
        if (this.getTrueOwner() != null
                && this.getTrueOwner().isAlive()
                && !this.getTrueOwner().isDeadOrDying()
                && (this.getStoredEffect() == null || this.getStoredEffect().getEffect().isBeneficial())){
            this.getNavigation().moveTo(this.getTrueOwner(), 1.25F);
            this.setTarget(null);
            ++this.searchTime;
            if (this.getBoundingBox().intersects(this.getTrueOwner().getBoundingBox())){
                this.getTrueOwner().heal(this.getHealth());
                for (MobEffectInstance mobEffectInstance : this.getActiveEffects()){
                    if (mobEffectInstance.getEffect().isBeneficial()){
                        this.getTrueOwner().addEffect(mobEffectInstance);
                    }
                }
                if (this.getStoredEffect() != null && this.getStoredEffect().getEffect().isBeneficial()){
                    this.getTrueOwner().addEffect(this.getStoredEffect());
                }
                this.playSound(SoundEvents.SCULK_BLOCK_SPREAD, 1.0F, 1.0F);
                if (!this.level.isClientSide) {
                    this.level.broadcastEntityEvent(this, (byte) 15);
                }
                this.discard();
            } else if (this.searchTime >= MathHelper.secondsToTicks(5)){
                this.hurt(this.damageSources().starve(), this.getMaxHealth());
            }
        } else {
            this.limitedLifeTicks = 20;
            this.hurt(this.damageSources().starve(), this.getMaxHealth());
        }
    }

@Override
    public boolean applyEffectTick(LivingEntity livingEntity, int amplifier) {
        var self = livingEntity.getEffect(MobEffectRegistry.IMMOLATE);
        if (DELAYED_INSTANCES.containsKey(self) && !(DELAYED_INSTANCES.get(self) - duration > 4)) {
            return true;
        }
        float explosionRadius = 6;
        var level = livingEntity.level;
        if (level.isClientSide) {
            return true;
        }
        @Nullable Entity attacker = EFFECT_CREDIT.remove(livingEntity);
        double baseDamage = damageFor(attacker);

        var source = new DamageSource(level.damageSources().damageTypes.getHolderOrThrow(ISSDamageTypes.FIRE_MAGIC), attacker);
        var explosionRadiusSqr = explosionRadius * explosionRadius;
        var entities = level.getEntities(null, livingEntity.getBoundingBox().inflate(explosionRadius));
        Vec3 losPoint = Utils.raycastForBlock(level, livingEntity.position(), livingEntity.position().add(0, 1, 0), ClipContext.Fluid.NONE).getLocation();
        for (Entity entity : entities) {
            double distanceSqr = entity.distanceToSqr(livingEntity.position());
            if (distanceSqr < explosionRadiusSqr && entity.canBeHitByProjectile() && !DamageSources.isFriendlyFireBetween(attacker, entity) && Utils.hasLineOfSight(level, losPoint, entity.getBoundingBox().getCenter(), true)) {
                double p = (1 - distanceSqr / explosionRadiusSqr);
                float damage = (float) (baseDamage * p);
                entity.invulnerableTime = 0; // ensure explosion can hit after the damage that procs it
                if (entity.hurt(source, damage) && entity instanceof LivingEntity livingVictim) {
                    var inst = addImmolateStack(livingVictim, attacker);
                    DELAYED_INSTANCES.put(inst, inst.getDuration());
                }
            }
        }
        PacketDistributor.sendToPlayersTrackingEntityAndSelf(livingEntity, new FieryExplosionParticlesPacket(livingEntity.getBoundingBox().getCenter(), 1.5f));
        level.playSound(null, livingEntity.getX(), livingEntity.getY(), livingEntity.getZ(), SoundEvents.GENERIC_EXPLODE.value(), livingEntity.getSoundSource(), 4.0F, (1.0F + (level.random.nextFloat() - level.random.nextFloat()) * 0.2F) * 0.7F);
        return false;
    }

