@Override
	public void scheduledTick(BlockState state, ServerWorld world, BlockPos pos, Random random) {
		if (state.get(OPENING)) {
			if (!world.isClient) {
				BlockEntity blockEntity = world.getBlockEntity(pos);
				if (blockEntity instanceof PresentBlockEntity presentBlockEntity) {
					int openingTick = presentBlockEntity.openingTick();
					Vec3d posVec = new Vec3d(pos.getX() + 0.5, pos.getY() + 0.25, pos.getZ() + 0.5);
					if (openingTick >= OPENING_STEPS) {
						spawnParticles(world, pos, presentBlockEntity.colors);
						presentBlockEntity.triggerAdvancement();
						if (presentBlockEntity.isEmpty()) {
							world.playSound(null, posVec.x, posVec.y, posVec.z, SoundEvents.BLOCK_FIRE_EXTINGUISH, SoundCategory.BLOCKS, 0.5F, 0.8F);
							SpectrumS2CPacketSender.playParticleWithExactVelocity(world, posVec, ParticleTypes.SMOKE, 5, Vec3d.ZERO);
						} else {
							world.playSound(null, posVec.x, posVec.y, posVec.z, SoundEvents.ENTITY_GENERIC_EXPLODE, SoundCategory.BLOCKS, 0.5F, 4.0F);
							SpectrumS2CPacketSender.playParticleWithExactVelocity(world, posVec, ParticleTypes.EXPLOSION, 1, Vec3d.ZERO);
							processInteractions(presentBlockEntity.stacks, presentBlockEntity, world, pos, random);
							ItemScatterer.spawn(world, pos, presentBlockEntity.stacks);
						}
						world.setBlockState(pos, Blocks.AIR.getDefaultState());
					} else {
						world.playSound(null, posVec.x, posVec.y, posVec.z, SoundEvents.BLOCK_SAND_PLACE, SoundCategory.BLOCKS, 0.8F + openingTick * 0.1F, 1.0F);
						spawnParticles(world, pos, presentBlockEntity.colors);
					}
				}
				world.scheduleBlockTick(pos, state.getBlock(), TICKS_PER_OPENING_STEP);
			}
		}
	}

@Override
	public void scheduledTick(BlockState state, ServerWorld world, BlockPos pos, Random random) {
		int age = state.get(AGE);
		boolean extend = state.get(EXTEND);
		if (extend && age > 1) {
			for (Direction direction : Direction.Type.HORIZONTAL) {
				BlockPos offsetPos = pos.offset(direction);
				BlockState directionState = world.getBlockState(offsetPos);
				if (directionState.getBlock() instanceof EtherealPlatformBlock && age > directionState.get(AGE)) {
					world.setBlockState(offsetPos, directionState.with(AGE, age - 1).with(EXTEND, true), Block.NOTIFY_LISTENERS);
					world.scheduleBlockTick(offsetPos, this, 2);
				}
			}
			world.setBlockState(pos, state.with(EXTEND, false));
		} else if (!extend && this.increaseAge(state, world, pos)) {
			BlockPos.Mutable mutable = new BlockPos.Mutable();

			for (Direction direction : Direction.values()) {
				mutable.set(pos, direction);
				BlockState blockState = world.getBlockState(mutable);
				if (blockState.isOf(this) && !this.increaseAge(blockState, world, mutable)) {
					world.scheduleBlockTick(mutable, this, 4);
				}
			}
		}
		if (age > 0) {
			world.scheduleBlockTick(pos, this, 10);
		}
	}

@Override
	@SuppressWarnings("deprecation")
	public void scheduledTick(BlockState state, ServerWorld world, BlockPos pos, Random random) {
		super.scheduledTick(state, world, pos, random);

		// convert all neighboring decay blocks to this
		for (BlockPos targetBlockPos : BlockPos.iterateOutwards(pos, 1, 1, 1)) {
			BlockState currentBlockState = world.getBlockState(targetBlockPos);
			if (currentBlockState.isIn(SpectrumBlockTags.DECAY_AWAY_CURABLES)) {
				world.setBlockState(targetBlockPos, getTargetStateForCurable(currentBlockState));
				world.scheduleBlockTick(targetBlockPos, state.getBlock(), 8);
			} else if (currentBlockState.isIn(SpectrumBlockTags.DECAY_AWAY_REMOVABLES)) {
				world.setBlockState(targetBlockPos, this.getDefaultState().with(TARGET_CONVERSION, TargetConversion.AIR));
				world.scheduleBlockTick(targetBlockPos, state.getBlock(), 8);
			}
		}

		// and turn this to the leftover block state
		BlockState currentState = world.getBlockState(pos);
		TargetConversion targetConversion = currentState.get(TARGET_CONVERSION);
		world.setBlockState(pos, targetConversion.getTargetState(world), 3);
	}

