private int tick(IFluidHandlerItem storageFluidHandler, @Nullable Entity entity, Level level, BlockPos pos) {
		if (shouldInteractWithHand()) {
			if (entity instanceof Player player) {
				if (handleFluidContainerInHands(player, storageFluidHandler)) {
					lastHandActionTime = level.getGameTime();
					return HAND_INTERACTION_COOLDOWN_TIME;
				}
			} else if (handleFluidContainersInHandsOfNearbyPlayers(level, pos, storageFluidHandler)) {
				lastHandActionTime = level.getGameTime();
				return HAND_INTERACTION_COOLDOWN_TIME;
			}
		}
		return handleInWorldInteractions(storageFluidHandler, entity, level, pos)
				.orElseGet(() -> lastHandActionTime + 10 * HAND_INTERACTION_COOLDOWN_TIME > level.getGameTime()
						? HAND_INTERACTION_COOLDOWN_TIME
						: DID_NOTHING_COOLDOWN_TIME);
	}

public static void tick() {
		ticks++;

		int before = hangingPlayers.size();

		ObjectIterator<Object2IntMap.Entry<UUID>> iterator = hangingPlayers.object2IntEntrySet().iterator();
		while (iterator.hasNext()) {
			Map.Entry<UUID, Integer> entry = iterator.next();
			int newTTL = entry.getValue() - 1;
			if (newTTL <= 0) {
				iterator.remove();
			} else {
				entry.setValue(newTTL);
			}
		}

		int after = hangingPlayers.size();

		if (ticks % 10 != 0 && before == after)
			return;

		sync();

	}

public static void tick(LevelTickEvent.Post event) {
		if (!(event.getLevel() instanceof ServerLevel serverLevel)) {
			return;
		}

		ResourceKey<Level> dim = serverLevel.dimension();
		if (!worldStorageSoundInfos.containsKey(dim)) {
			return;
		}

		removeFinished(serverLevel, dim);

		if (lastWorldCheck.computeIfAbsent(dim, key -> serverLevel.getGameTime()) > serverLevel.getGameTime() - KEEP_ALIVE_CHECK_INTERVAL) {
			return;
		}
		lastWorldCheck.put(dim, serverLevel.getGameTime());

		worldStorageSoundInfos.get(dim).entrySet().removeIf(entry -> {
			if (entry.getValue().getLastKeepAliveTime() < serverLevel.getGameTime() - KEEP_ALIVE_CHECK_INTERVAL) {
				sendStopMessage(serverLevel, entry.getValue().getLastPosition(), entry.getKey());
				return true;
			}
			return false;
		});
	}

