@Override
    public void tick() {
        if (attackTime > 0) {
            attackTime--;
        } else {
            LivingEntity target = entity.getTarget();
            if (target != null) {
                double d0 = this.entity.distanceToSqr(target.getX(), target.getBoundingBox().minY, target.getZ());
                boolean canSee = this.entity.getSensing().hasLineOfSight(target);
                boolean couldSee = this.seeTime > 0;

                if (canSee != couldSee) {
                    this.seeTime = 0;
                }

                if (canSee) {
                    ++this.seeTime;
                    this.entity.lookAt(target, 19.0F, 10.0F);


                    this.entity.lookAt(EntityAnchorArgument.Anchor.EYES, target.getEyePosition(1.0F));
                } else {
                    --this.seeTime;
                }

                if (d0 <= (double) this.maxAttackDistance && this.seeTime >= 20) {
                    attack(target);
                    this.attackTime = attackCooldown;
                    entity.addEffect(new MobEffectInstance(MobEffects.SLOWNESS, 20));


                } else {
                    this.entity.getNavigation().moveTo(target, 1.0);

                }
            }
        }
    }

@Override
	public void tick() {
		double targetDistance = this.taskOwner.distanceToSqr(this.target.getX(), this.target.getY(), this.target.getZ());
		boolean canSeeTarget = this.taskOwner.getSensing().hasLineOfSight(this.target);

		if (canSeeTarget) {
			++this.seeTime;
		}
		else {
			this.seeTime = 0;
		}

		if (!(targetDistance > (double)this.attackRadius * this.attackRadius) && this.seeTime >= 5) {
			this.taskOwner.getNavigation().stop();
		}
		else {
			this.taskOwner.getNavigation().moveTo(this.target, this.speedModifier);
		}

		this.taskOwner.getLookControl().setLookAt(this.target, 30f, 30f);

		if (--this.attackTime <= 0 && this.attackTime >= -preAttackTime) {
			if (!canSeeTarget)
				return;

			if (this.attackTime == 0)
				this.taskOwner.swing(InteractionHand.MAIN_HAND);

			if (this.attackTime == -preAttackTime) {
				float distMod = (float)Math.sqrt(targetDistance) / this.attackRadius;
				float distFactor = Mth.clamp(distMod, 0.1f, 1);

				this.taskOwner.performRangedAttack(this.target, distFactor);
				this.attackTime = Mth.floor(distMod * (float)(this.attackCooldownMax - this.attackCooldownMin) + (float)this.attackCooldownMin);
			}
		}
		else if (this.attackTime < 0) {
			this.attackTime = Mth.floor(Mth.lerp(Math.sqrt(targetDistance) / (double)this.attackRadius, this.attackCooldownMin, this.attackCooldownMax));
		}
	}

public void onUpdate(){

		if(this.ticksExisted % 40 == 1){
			this.playSound(WizardrySounds.ENTITY_FIRE_RING_AMBIENT, 4.0f, 0.7f);
		}

		super.onUpdate();

		if(this.ticksExisted % 5 == 0 && !this.world.isRemote){

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinCylinder(this.width/2, this.posX, this.posY, this.posZ, this.height, this.world);

			for(EntityLivingBase target : targets){

				if(this.isValidTarget(target)){

					double velX = target.motionX;
					double velY = target.motionY;
					double velZ = target.motionZ;

					if(!MagicDamage.isEntityImmune(DamageType.FIRE, target)){

						target.setFire(Spells.ring_of_fire.getProperty(Spell.BURN_DURATION).intValue());

						float damage = Spells.ring_of_fire.getProperty(Spell.DAMAGE).floatValue() * damageMultiplier;

						if(this.getCaster() != null){
							target.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(),
									DamageType.FIRE), damage);
						}else{
							target.attackEntityFrom(DamageSource.MAGIC, damage);
						}
					}

					// Removes knockback
					target.motionX = velX;
					target.motionY = velY;
					target.motionZ = velZ;
				}
			}
		}
	}

