public boolean shriek(ServerLevel serverLevel, @Nullable Player player, int soulEnergy) {
        BlockPos blockpos = this.getBlockPos();
        BlockState blockstate = this.getBlockState();
        int cost = (soulEnergy / MobsConfig.IllagerAssaultSEThreshold.get()) * MainConfig.ShriekObeliskCost.get();
        if (blockstate.getValue(ShriekObeliskBlock.POWERED)) {
            if (this.cursedCageTile != null) {
                if (this.cursedCageTile.getSouls() >= cost) {
                    if (!blockstate.getValue(ShriekObeliskBlock.SHRIEKING)) {
                        this.cursedCageTile.decreaseSouls(cost);
                        serverLevel.setBlock(blockpos, blockstate.setValue(ShriekObeliskBlock.SHRIEKING, Boolean.TRUE), 2);
                        serverLevel.scheduleTick(blockpos, blockstate.getBlock(), 90);
                        for (int j = 0; j < 10; ++j) {
                            serverLevel.sendParticles(new ShriekParticleOption(j * 5), (double) blockpos.getX() + 0.5D, (double) blockpos.getY() + 1.0D, (double) blockpos.getZ() + 0.5D, 1, 0.0D, 0.0D, 0.0D, 0.5F);
                        }
                        ModNetwork.sendToALL(new SPlayWorldSoundPacket(blockpos.above(), SoundEvents.SCULK_SHRIEKER_SHRIEK, 2.0F, 0.25F));
                        serverLevel.gameEvent(GameEvent.SHRIEK, blockpos, GameEvent.Context.of(player));
                        return true;
                    }
                }
            }
        }
        return false;
    }

@Override
	protected void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, @Nullable Orientation orientation, boolean movedByPiston) {
		if (level.isClientSide()) {
			return;
		}

		TowerDeviceVariant variant = state.getValue(STATE);

		if (variant == TowerDeviceVariant.BUILDER_INACTIVE && level.hasNeighborSignal(pos)) {
			level.setBlockAndUpdate(pos, state.setValue(STATE, TowerDeviceVariant.BUILDER_ACTIVE));
			level.playSound(null, pos, TFSounds.BUILDER_ON.get(), SoundSource.BLOCKS, 0.3F, 0.6F);
			level.scheduleTick(pos, this, 4);
		}

		if (variant == TowerDeviceVariant.BUILDER_ACTIVE && !level.hasNeighborSignal(pos)) {
			level.setBlockAndUpdate(pos, state.setValue(STATE, TowerDeviceVariant.BUILDER_INACTIVE));
			level.playSound(null, pos, TFSounds.BUILDER_OFF.get(), SoundSource.BLOCKS, 0.3F, 0.6F);
			level.scheduleTick(pos, this, 4);
		}

		if (variant == TowerDeviceVariant.BUILDER_TIMEOUT && !level.hasNeighborSignal(pos)) {
			level.setBlockAndUpdate(pos, state.setValue(STATE, TowerDeviceVariant.BUILDER_INACTIVE));
		}
	}

public void activateNukeVirus(int pos) {
        int neighbour = getHackedNeighbour(pendingNukePos);
        if (neighbour >= 0) {
            boolean found = false;
            Node neighbourNode = getNodeAt(neighbour);
            if (neighbourNode != null) {
                for (Pair<Integer, Float> conn : neighbourNode.outGoingHacks) {
                    if (conn.getLeft() == pendingNukePos) {
                        conn.setValue(1f);
                        found = true;
                    }
                }
                if (!found) {
                    neighbourNode.outGoingHacks.add(Pair.of(pendingNukePos, 1f));
                }
                Node node = getNodeAt(pos);
                if (node != null) {
                    node.setHackProgress(pos, 1f, false);
                }
                if (controller != null) controller.getHacker().playSound(SoundEvents.GENERIC_EXPLODE.value(), 1f, 1f);
                nukeVirusCooldown = 60;
            }
        }
        pendingNukePos = -1;
    }

@Override
    public void entityInside(@NotNull BlockState state, @NotNull Level worldIn, @NotNull BlockPos pos, @NotNull Entity entityIn) {
        super.entityInside(state, worldIn, pos, entityIn);
        List<Entity> entities = worldIn.getEntitiesOfClass(Entity.class, getShape(state, worldIn, pos, CollisionContext.empty()).bounds().move(pos), EntitySelector.NO_SPECTATORS.and((p_289691_) -> {
            return !p_289691_.isIgnoringBlockTriggers();
        }));
        if (!entities.isEmpty() && worldIn.getBlockEntity(pos) instanceof RuneTile rune) {
            if (rune.spell != null) {
                // Ignore form and its augment, only check effects
                for (AbstractSpellPart part : rune.spell.recipe()) {
                    if (part instanceof AbstractEffect) {
                        // If the effect is not a filter, proceed with rune activation
                        if (part instanceof IFilter filter) {
                            // If one or more filters are detected, all must match to let the rune activate
                            if (!filter.shouldResolveOnEntity(new EntityHitResult(entityIn), worldIn)) {
                                return;
                            }
                        } else break;
                    }
                }
            }
            rune.touchedEntity = entities.getFirst();
            worldIn.scheduleTick(pos, this, 1);
        }
    }

