private void playerTick(Player player) {
		ServerQuestFile file = ServerQuestFile.INSTANCE;

		if (player instanceof ServerPlayer serverPlayer && file != null && !PlayerHooks.isFake(player)) {
			if (autoSubmitTasks == null) {
				autoSubmitTasks = file.collect(Task.class, t -> t.autoSubmitOnPlayerTick() > 0);
			}

			// Don't be deceived, it's somehow possible to be null here
			if (autoSubmitTasks == null || autoSubmitTasks.isEmpty()) {
				return;
			}

			file.getTeamData(player).ifPresent(data -> {
				long now = player.level().getGameTime();

				file.withPlayerContext(serverPlayer, () -> {
					for (Task task : autoSubmitTasks) {
						long interval = task.autoSubmitOnPlayerTick();
						if (interval > 0L && now % interval == 0L) {
							if (!data.isCompleted(task) && data.canStartTasks(task.getQuest())) {
								task.submitTask(data, serverPlayer);
							}
						}
					}
				});
			});
		}
	}

public static void onLivingUpdate(EntityTickEvent.Post event) {
		Entity entity = event.getEntity();
		if (entity.level().isClientSide() || entity instanceof Player || !(entity instanceof LivingEntity livingEntity)) {
			return;
		}
		if (livingEntity instanceof Monster monster && hasPendingBackpackAddition(monster)) {
			setPendingBackpackAddition(monster, false);
			if (monster.getItemBySlot(EquipmentSlot.CHEST).isEmpty()) {
				addBackpack(monster, entity.level(), entity.level().getRandom());
			}
		}
		if (!hasSpawnedJukeboxUpgrade(livingEntity)) {
			return;
		}
		ItemStack backpack = livingEntity.getItemBySlot(EquipmentSlot.CHEST);
		if (!(backpack.getItem() instanceof BackpackItem)) {
			clearSpawnedBackpackData(livingEntity);
			return;
		}

		IBackpackWrapper backpackWrapper = BackpackWrapper.fromStack(backpack);
		backpackWrapper.getUpgradeHandler().getTypeWrappers(JukeboxUpgradeItem.TYPE).forEach(wrapper -> {
			if (wrapper.isPlaying()) {
				wrapper.tick(livingEntity, entity.level(), entity.blockPosition());
			} else {
				wrapper.play(livingEntity);
			}
		});
	}

public boolean hurt(DamageSource pSource, float pAmount) {
        if (this.getHealth() <= 10.0F){
            if (pSource.is(DamageTypes.CACTUS) || pSource.is(DamageTypes.SWEET_BERRY_BUSH) || pSource.is(DamageTypeTags.WITCH_RESISTANT_TO)){
                return false;
            }
        }

        if (pSource.getEntity() instanceof LivingEntity livingentity && livingentity != this){
            this.toHealTime = MathHelper.secondsToTicks(15);
            if (MobsConfig.CroneThornDefense.get()) {
                if (!pSource.is(DamageTypeTags.AVOIDS_GUARDIAN_THORNS) && !pSource.is(DamageTypes.THORNS)) {
                    float thorn = 2.0F;
                    if (this.level.getDifficulty() == Difficulty.HARD) {
                        thorn *= 2.0F;
                    }
                    livingentity.hurt(this.damageSources().thorns(this), thorn);
                }
            }
            if (pAmount >= 6 && this.overwhelmed <= 0) {
                this.hitTimes += 1;
                this.lastHitTime = 25;
            }
            if (pAmount >= 15 || this.hitTimes > 3){
                this.overwhelmed = MathHelper.secondsToTicks(15);
            }
        }

        return super.hurt(pSource, pAmount);
    }

public static <T extends IFactionPlayer<T> & ISkillPlayer<T>> void handleToggleActionPacket(ServerboundToggleActionPacket msg, IPayloadContext context) {
        context.enqueueWork(() -> {
            Player player = context.player();
            IActionHandler.<T>get(player).ifPresent(handler -> {
                IAction.ActivationContext activationContext = msg.target() != null ? msg.target().map(entityId -> {
                    Entity e = player.level().getEntity(entityId);
                    if (e == null) {
                        LOGGER.warn("Could not find entity {} the player was looking at when toggling action", entityId);
                    }
                    return new ActionHandler.ActivationContext(e);
                }, ActionHandler.ActivationContext::new) : new ActionHandler.ActivationContext();

                Holder<? extends IAction<?>> action = msg.action();
                if (action != null) {
                    @SuppressWarnings("unchecked")
                    IActionResult r = handler.toggleAction((Holder<IAction<T>>) (Object) action, activationContext);
                    if (!r.successful()) {
                        if (r.sendToStatusBar()) {
                            player.sendOverlayMessage(r.message());
                        } else {
                            player.sendSystemMessage(r.message());
                        }
                    } else {
                        handler.sync();
                    }
                }
            });
        });
    }

