private boolean updateHeat() {
        if (heatQueue > 0) {
            // if received heat from overvolting or overamping, add heat
            setTemperature(temperature + heatQueue);
        }

        if (temperature >= meltTemp) {
            // cable melted
            level.setBlockAndUpdate(worldPosition, Blocks.FIRE.defaultBlockState());
            return false;
        }

        if (temperature <= getDefaultTemp()) {
            unsubscribeHeat();
            return false;
        }

        if (getPipeType().isCable() && temperature >= 1500 && GTValues.RNG.nextFloat() < 0.1f) {
            // insulation melted
            uninsulate();
            return false;
        }

        if (heatQueue <= 0) {
            // otherwise cool down
            setTemperature((int) (temperature - Math.pow(temperature - getDefaultTemp(), 0.35f)));
        }
        heatQueue = 0;
        return true;
    }

public InteractionResult useOn(UseOnContext pContext) {
        Level world = pContext.getLevel();
        ItemStack stack = pContext.getItemInHand();
        Player player = pContext.getPlayer();
        if (player != null) {
            if (!stack.isEmpty() && !hasRecall(stack)) {
                CompoundTag compoundTag = stack.getOrCreateTag();
                if (stack.getItem() instanceof RecallFocus) {
                    BlockPos blockpos = pContext.getClickedPos();
                    BlockEntity tileEntity = world.getBlockEntity(blockpos);
                    if (tileEntity instanceof ArcaBlockEntity arcaTile) {
                        if (pContext.getPlayer() == arcaTile.getPlayer() && arcaTile.getLevel() != null) {
                            this.addRecallTags(arcaTile.getLevel().dimension(), arcaTile.getBlockPos(), compoundTag);
                            stack.setTag(compoundTag);
                            player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                            return InteractionResult.sidedSuccess(world.isClientSide);
                        }
                    }
                    BlockState blockstate = world.getBlockState(blockpos);
                    if (blockstate.is(ModTags.Blocks.RECALL_BLOCKS)) {
                        this.addRecallTags(world.dimension(), blockpos, compoundTag);
                        stack.setTag(compoundTag);
                        player.playSound(SoundEvents.ARROW_HIT_PLAYER, 1.0F, 0.45F);
                        return InteractionResult.sidedSuccess(world.isClientSide);
                    }
                }
            }
        }
        return InteractionResult.PASS;
    }

@Override
	public void tickServer()
	{
		tickCommon();
		if(level.getGameTime()%64==((getBlockPos().getX()^getBlockPos().getZ())&63))
			markContainingBlockForUpdate(null);

		int energy = IEServerConfig.MACHINES.turret_consumption.get();
		if(isRSPowered()^config.redstoneControlInverted)
		{
			if(energyStorage.extractEnergy(energy, true)==energy)
			{
				energyStorage.extractEnergy(energy, false);
				if(target==null||!target.isAlive()||level.getEntity(target.getId())==null||target.getHealth() <= 0||!canShootEntity(target))
				{
					target = getTarget();
					if(target!=null)
					{
						this.setChanged();
						markContainingBlockForUpdate(null);
					}
				}

				//has target, Redstone control check and has power+ammo
				if(target!=null&&canActivate())
				{
					tick++;
					int chargeup = getChargeupTicks();
					if(tick==chargeup)
						this.activate();
					else if(tick > chargeup)
					{
						if(loopActivation())
							this.activate();
						else if(tick==chargeup+getActiveTicks())
							tick = 0;
					}
				}
				else
					tick = 0;
			}
		}
		else if(target!=null)
			target = null;
	}

@Override
        protected void tick(ArkbackEntity entity) {
            if (this.runningTime == 25) {
                entity.setSynchedData(RESTING, true);
            }
            else if (this.shakeTick >= 0) {
                if (this.shakeTick++ > 16) {
                    entity.setSynchedData(RESTING, false);
                }
                else {
                    Vec3 shakeDirection = MathUtil.getBodyRight(entity).scale(Mth.floor(Mth.sin(45 * this.shakeTick) * 2)).add(0, 1, 0);
                    AABB plateBounds = AABB.ofSize(entity.position().add(0, entity.getBbHeight(), 0), entity.getBbWidth(), 1.5f * entity.getScale(), entity.getBbWidth());

                    for (Entity rider : EntityRetrievalUtil.<Entity>getEntities(entity.level(), plateBounds, rider -> rider != entity)) {
                        rider.setDeltaMovement(shakeDirection);
                        rider.hurtMarked = true;
                    }

                    if (this.shakeTick < 10 && entity.getSandLevel() > 0) {
                        float sine = Mth.sin(45 * this.shakeTick);

                        if (Mth.abs(sine) >= 0.9f) {
                            TMEParticlePacket packet = new TMEParticlePacket();
                            shakeDirection = MathUtil.getBodyRight(entity).scale(sine * 0.25f).add(0, 0.25f, 0);
                            plateBounds = plateBounds.move(0, 0.5f, 0);

                            for (int i = 0; i < 100; i++) {
                                packet.particle(ParticleBuilder.forRandomPosInBounds(new BlockParticleOption(ParticleTypes.BLOCK, Blocks.SAND.defaultBlockState()), plateBounds)
                                        .velocity(shakeDirection.add(entity.random.nextGaussian() * 0.05f, entity.random.nextGaussian() * 0.05f, entity.random.nextGaussian() * 0.05f))
                                        .scaleMod((float)entity.random.nextGaussian() * 0.4f + 0.8f));
                                packet.particle(ParticleBuilder.forRandomPosInBounds(new BlockParticleOption(ParticleTypes.FALLING_DUST, Blocks.SAND.defaultBlockState()), plateBounds)
                                        .velocity(shakeDirection.scale(0.1f).add(entity.random.nextGaussian() * 0.05f, entity.random.nextGaussian() * 0.05f, entity.random.nextGaussian() * 0.05f))
                                        .scaleMod(entity.random.nextFloat() * 0.4f + 0.3f));
                            }

                            packet.sendToAllPlayersTrackingEntity(entity);
                            entity.setSandLevel(entity.getSandLevel() - 10);
                        }
                    }
                }
            }

            if (this.shakeTick == -1 && timedOut(entity.level().getGameTime() + 37)) {
                this.shakeTick = 0;
                entity.triggerAnim("Main", "rest_stop");
            }
        }

public void tick() {
        this.baseTick();
        if (this.lightningState == 2) {
            Difficulty difficulty = this.level.getDifficulty();

            this.level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.LIGHTNING_BOLT_THUNDER, SoundSource.WEATHER, 1.0f, 0.8F + this.random.nextFloat() * 0.2F);
            this.level.playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.LIGHTNING_BOLT_IMPACT, SoundSource.WEATHER, 1.0F, 0.5F + this.random.nextFloat() * 0.2F);
        }

        --this.lightningState;
        if (this.lightningState < 0) {
            if (this.boltLivingTime == 0) {
                this.remove(RemovalReason.DISCARDED);
            } else if (this.lightningState < -this.random.nextInt(10)) {
                --this.boltLivingTime;
                this.lightningState = 1;
                this.boltVertex = this.random.nextLong();
            }
        }

        if (this.lightningState >= 0) {
            if (!(this.level instanceof ServerLevel)) {
                this.level.setSkyFlashTime(2);
            } else if (!this.effectOnly) {
                List<Entity> list = this.level.getEntities(this, new AABB(this.getX() - 3.0D, this.getY() - 3.0D, this.getZ() - 3.0D, this.getX() + 3.0D, this.getY() + 6.0D + 3.0D, this.getZ() + 3.0D), Entity::isAlive);
                for (Entity entity : list) {
                    if (!net.neoforged.neoforge.event.EventHooks.onEntityStruckByLightning(entity, this)) {
                        float origDamage = this.getDamage();
                        this.setDamage(this.getDamage(entity));
                        EntityStruckByLightningEvent event = new EntityStruckByLightningEvent(entity, this);
                        NeoForge.EVENT_BUS.post(event);
                        if (event.isCanceled())
                            continue;
                        entity.thunderHit((ServerLevel) this.level, this);
                        this.setDamage(origDamage);
                        if (!level.isClientSide && !hitEntities.contains(entity.getId()) && entity instanceof LivingEntity) {
                            MobEffectInstance effectInstance = ((LivingEntity) entity).getEffect(ModPotions.SHOCKED_EFFECT);
                            int amp = effectInstance != null ? effectInstance.getAmplifier() : -1;
                            ((LivingEntity) entity).addEffect(new MobEffectInstance(ModPotions.SHOCKED_EFFECT, 200 + 10 * 20 * extendTimes, Math.min(2, amp + 1)));
                        }
                        if (!level.isClientSide && !hitEntities.contains(entity.getId()))
                            hitEntities.add(entity.getId());

                    }
                }

                if (this.caster != null) {
                    CriteriaTriggers.CHANNELED_LIGHTNING.trigger(this.caster, list);
                }
            }
        }
    }

