@Override
	public void onUpdate(){

		double extensionSpeed = 0;

		if(!world.isRemote){
			if(lifetime - this.ticksExisted < 15){
				extensionSpeed = -0.01 * (this.ticksExisted - (lifetime - 15));
			}else if(lifetime - this.ticksExisted < 25){
				extensionSpeed = 0;
			}else if(lifetime - this.ticksExisted < 28){
				extensionSpeed = 0.25;
			}

			if(facing != null){ // Will probably be null on the client side, but should never be on the server side
				this.move(MoverType.SELF, this.facing.getXOffset() * extensionSpeed, this.facing.getYOffset() * extensionSpeed,
						this.facing.getZOffset() * extensionSpeed);
			}
		}

		if(lifetime - this.ticksExisted == 30) this.playSound(WizardrySounds.ENTITY_ICE_SPIKE_EXTEND, 1, 2.5f);

		if(!this.world.isRemote){
			for(Object entity : this.world.getEntitiesWithinAABBExcludingEntity(this, this.getEntityBoundingBox())){
				if(entity instanceof EntityLivingBase && this.isValidTarget((EntityLivingBase)entity)){
					DamageSource source = this.getCaster() == null ? DamageSource.MAGIC : MagicDamage.causeDirectMagicDamage(this.getCaster(), DamageType.FROST);
					// Potion effect only gets added if the damage succeeded
					// We DO want knockback here or the entity gets stuck on the spike, which is a bit of a cheat
					if(((EntityLivingBase)entity).attackEntityFrom(source, Spells.ice_spikes.getProperty(Spell.DAMAGE).floatValue() * this.damageMultiplier))
						((EntityLivingBase)entity).addPotionEffect(new PotionEffect(WizardryPotions.frost,
								Spells.ice_spikes.getProperty(Spell.EFFECT_DURATION).intValue(),
								Spells.ice_spikes.getProperty(Spell.EFFECT_STRENGTH).intValue()));
				}
			}
		}

		super.onUpdate();
	}

@Override
        public void tick() {
            checkForMobsTime--;
            LivingEntity target = GammaroachEntity.this.getTarget();
            if (target != null && target.isAlive()) {
                if (checkForMobsTime < 0) {
                    checkForMobsTime = 120 + GammaroachEntity.this.random.nextInt(100);
                    Predicate<Entity> monsterAway = (animal) -> animal instanceof Enemy && !(animal instanceof GammaroachEntity) && animal.distanceTo(target) > 5 && !animal.isPassenger();
                    List<Mob> list = GammaroachEntity.this.level().getEntitiesOfClass(Mob.class, GammaroachEntity.this.getBoundingBox().inflate(30, 12, 30), EntitySelector.NO_SPECTATORS.and(monsterAway));
                    list.sort(Comparator.comparingDouble(GammaroachEntity.this::distanceToSqr));
                    if (!list.isEmpty()) {
                        pickupMonster = list.get(0);
                    }
                }
                if (pickupMonster == null || pickupMonster.isPassengerOfSameVehicle(GammaroachEntity.this)) {
                    GammaroachEntity.this.getNavigation().moveTo(target, 1.0D);
                    GammaroachEntity.this.lookAt(target, 180, 30);
                    if (GammaroachEntity.this.distanceTo(target) < 1.5F + target.getBbWidth()) {
                        if (GammaroachEntity.this.getAnimation() == NO_ANIMATION) {
                            GammaroachEntity.this.setAnimation(GammaroachEntity.ANIMATION_RAM);
                        } else if (GammaroachEntity.this.getAnimation() == GammaroachEntity.ANIMATION_RAM && GammaroachEntity.this.getAnimationTick() > 8 && GammaroachEntity.this.getAnimationTick() < 15) {
                            GammaroachEntity.this.playSound(ACSoundRegistry.GAMMAROACH_ATTACK.get());
                            target.hurt(damageSources().mobAttack(GammaroachEntity.this), (float) GammaroachEntity.this.getAttributeValue(Attributes.ATTACK_DAMAGE));
                        }
                        if (pickupMonster != null) {
                            pickupMonster.stopRiding();
                            pickupMonster = null;
                        }
                    }
                } else if (pickupMonster.isAlive() && (!pickupMonster.isPassenger())) {
                    GammaroachEntity.this.getNavigation().moveTo(pickupMonster, 1.0D);
                    GammaroachEntity.this.lookAt(pickupMonster, 180, 30);
                    if (GammaroachEntity.this.distanceTo(pickupMonster) < 1.5F + pickupMonster.getBbWidth()) {
                        pickupMonster.startRiding(GammaroachEntity.this, true);
                        pickupMonster.hurt(damageSources().cactus(), 1);
                    }
                } else {
                    pickupMonster = null;
                }
            }
        }

public void onUse(World world, BlockPos pos, PlayerEntity player, Hand hand) {
		if (!getCachedState().get(Properties.WATERLOGGED)) {
			ItemStack stack = player.getStackInHand(hand);
			if (getCachedState().get(Properties.LIT)) {
				world.setBlockState(pos, getCachedState().with(Properties.LIT, false));
				world.playSound(null, pos, SoundEvents.BLOCK_FIRE_EXTINGUISH, SoundCategory.BLOCKS, 1, 2);
				reset(hasIncense);
				syncBrazier();
			} else {
				if (stack.getItem() instanceof FlintAndSteelItem) {
					world.setBlockState(pos, getCachedState().with(Properties.LIT, true));
					world.playSound(null, pos, SoundEvents.ITEM_FLINTANDSTEEL_USE, SoundCategory.BLOCKS, 1, 1);
					stack.damage(1, player, stackUser -> stackUser.sendToolBreakStatus(hand));
					IncenseRecipe foundIncenseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.INCENSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
					if (foundIncenseRecipe != null) {
						incenseRecipe = foundIncenseRecipe;
						timer = -6000;
						hasIncense = true;
						syncBrazier();
					} else if (BWConfig.enableCurses) {
						CurseRecipe foundCurseRecipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.CURSE_RECIPE_TYPE).stream().filter(recipe -> recipe.matches(this, world)).findFirst().orElse(null);
						if (foundCurseRecipe != null && getTarget() != null) {
							curseRecipe = foundCurseRecipe;
							timer = -100;
							syncBrazier();
						}
					}
				} else if (!stack.isEmpty()) {
					int firstEmpty = getFirstEmptySlot();
					if (firstEmpty != -1) {
						setStack(firstEmpty, stack.split(1));
						syncBrazier();
					}
				} else {
					reset(hasIncense);
					syncBrazier();
				}
			}
		}
		markDirty();
	}

public void tick() {
        if (this.level != null) {
            ++this.tickCount;
            if (this.level instanceof ServerLevel serverLevel) {
                int radius = 8 + this.getEnchantments().getOrDefault(ModEnchantments.RADIUS.get(), 0);
                if (this.target == null) {
                    for (LivingEntity livingEntity : serverLevel.getEntitiesOfClass(LivingEntity.class, new AABB(this.worldPosition).inflate(radius * 2))) {
                        if (EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(livingEntity) && livingEntity.distanceToSqr(this.getBlockPos().getCenter()) <= Mth.square(radius)) {
                            boolean flag = livingEntity.getHealth() >= livingEntity.getMaxHealth() * 0.25F;
                            if (this.getTrueOwner() != null) {
                                flag &= !MobUtil.areAllies(this.getTrueOwner(), livingEntity);
                            } else {
                                flag &= !this.isAllyWith(livingEntity);
                            }
                            if (flag) {
                                this.target = livingEntity;
                            }
                        }
                    }
                } else {
                    if (!this.target.isAlive() || this.target.getHealth() < this.target.getMaxHealth() * 0.25F || this.target.distanceToSqr(this.getBlockPos().getCenter()) > Mth.square(radius)) {
                        this.attackTick = 0;
                        this.target = null;
                    } else {
                        ++this.attackTick;
                        if (this.attackTick % 20 == 0) {
                            Vec3 vector3d1 = this.getBlockPos().getCenter();
                            DamageSource damageSource = this.getTrueOwner() != null ? ModDamageSource.soulLeech(this.getTrueOwner(), this.getTrueOwner()) : this.level.damageSources().magic();
                            this.target.addEffect(new MobEffectInstance(GoetyEffects.CURSED.get(), 10, 0, false, false));
                            if (this.target.hurt(damageSource, this.target.getMaxHealth() * 0.1F)) {
                                ColorUtil colorUtil1 = new ColorUtil(0x5038dd);
                                serverLevel.sendParticles(new SpirallingParticleOption(1.0F, colorUtil1.red, colorUtil1.green, colorUtil1.blue, 5), vector3d1.x, vector3d1.y, vector3d1.z, 1, 0.0D, 0.0D, 0.0D, 1.0D);
                                Vec3 vec3 = new Vec3(this.target.getX(), this.target.getY() + (this.target.getBbHeight() / 2.0F), this.target.getZ());
                                serverLevel.sendParticles(new GatherTrailParticleOption(colorUtil1, vector3d1), vec3.x, vec3.y, vec3.z, 0, 0.0F, 0.0F, 0.0F, 0.5F);
                                for (int i = 0; i < 8; ++i) {
                                    Vec3 vec31 = new Vec3(this.target.getRandomX(1.0F), this.target.getRandomY(), this.target.getRandomZ(1.0F));
                                    serverLevel.sendParticles(new AbsorbTrailParticleOption(vector3d1, 0x5038dd, 10), vec31.x, vec31.y, vec31.z, 1, 0.0, 0.0, 0.0, 0.0);
                                }
                                this.level.playSound(null, this.worldPosition, ModSounds.SOUL_EAT.get(), SoundSource.BLOCKS, 1.0F, 1.0F);
                                if (this.getTrueOwner() instanceof Player player) {
                                    if (SEHelper.getSoulGiven(this.target) > 0) {
                                        int enchantment = this.getEnchantments().getOrDefault(ModEnchantments.SOUL_EATER.get(), 0);
                                        int soulEater = Mth.clamp(enchantment + 1, 1, 10);
                                        SEHelper.increaseSouls(player, MainConfig.BlackCrystalSouls.get() * soulEater);
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

public void tick() {
        super.tick();
        this.prevGroundProgress = groundProgress;
        this.yBodyRot = this.getYRot();
        if (this.onGround() && groundProgress < 5F) {
            groundProgress++;
        }
        if (!this.onGround() && groundProgress > 0F) {
            groundProgress--;
        }
        if (!level().isClientSide) {
            Entity winch = getWinch();
            if (winch == null) {
                LivingEntity created = createWinch();
                level().addFreshEntity(created);
                this.setWinchUUID(created.getUUID());
                this.entityData.set(WINCH_ID, created.getId());
            } else {
                if (winch instanceof BoundroidWinchEntity winchEntity) {
                    winchEntity.linkWithHead(this);
                }
            }
            LivingEntity target = this.getTarget();
            if (target != null && target.isAlive()) {
                Vec3 distanceVec = target.position().subtract(this.position());
                if (distanceVec.horizontalDistance() < 1.2 && stopSlammingFor == 0) {
                    this.setSlamming(true);
                }
            }
            if (this.isSlamming()) {
                this.setDeltaMovement(new Vec3(this.getDeltaMovement().x, -1, this.getDeltaMovement().z));
                if (this.onGround()) {
                    this.setSlamming(false);
                    this.playSound(ACSoundRegistry.BOUNDROID_SLAM.get());
                    this.stayOnGroundFor = 10;
                    this.stopSlammingFor = 30 + random.nextInt(20);
                    this.level().broadcastEntityEvent(this, (byte) 45);
                    AABB bashBox = new AABB(-1.5F, -2F, -1.5F, 1.5F, 1F, 1.5F);
                    bashBox = bashBox.move(this.position());
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, bashBox)) {
                        if (!isAlliedTo(entity) && !(entity instanceof BoundroidEntity) && !(entity instanceof BoundroidWinchEntity)) {
                            entity.hurt(damageSources().mobAttack(this), 5);
                        }
                    }
                }
            }
        }else if(isAlive()){
            AlexsCaves.PROXY.playWorldSound(this, (byte) 12);
        }
        if (stopSlammingFor > 0) {
            stopSlammingFor--;
        }
        if (stayOnGroundFor > 0) {
            stayOnGroundFor--;
        }
    }

public void tick() {
        super.tick();
        this.setYHeadRot(this.getYRot());
        prevMergeProgress = mergeProgress;
        prevAttackProgress = attackProgress;
        if (prevHeadCount != this.getHeadCount()) {
            refreshDimensions();
            if (this.mergeProgress < 5.0F) {
                this.mergeProgress++;
            } else {
                this.getAttribute(Attributes.MAX_HEALTH).setBaseValue(Mth.clamp(getHeadCount() * 10, 10, 100));
                this.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(Mth.clamp(getHeadCount() * 2, 2, 10));
                double d = this.getAttribute(Attributes.MAX_HEALTH).getValue();
                if(this.getHealth() < d && getHeadCount() > 0){
                    this.heal((float) Math.ceil(d - this.getHealth()));
                }
                prevHeadCount = this.getHeadCount();
            }
        }
        if (this.entityData.get(ATTACK_TICK) > 0) {
            this.entityData.set(ATTACK_TICK, this.entityData.get(ATTACK_TICK) - 1);
            if (attackProgress < 5F) {
                attackProgress++;
            }
        } else {
            LivingEntity target = this.getTarget();
            if (attackProgress >= 3F && target != null && this.distanceTo(target) < getSlimeSize(1.0F)) {
                target.hurt(damageSources().mobAttack(this), 4F + getHeadCount() * 2);
            }
            if (attackProgress > 0F) {
                attackProgress--;
            }
        }
        if (level().isClientSide && isAlive()) {
            float slimeSize = getSlimeSize(1);
            for (int i = 0; i < Math.ceil(slimeSize); i++) {
                double particleX = this.getX() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                double particleY = this.getY() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                double particleZ = this.getZ() + (random.nextDouble() - 0.5F) * (slimeSize + 1.5F);
                level().addParticle(ACParticleRegistry.FERROUSLIME.get(), particleX, particleY, particleZ, this.getId(), 0, 0);
            }
            AlexsCaves.PROXY.playWorldSound(this, (byte) 13);
        } else {
            LivingEntity living = this.getTarget();
            if (living != null && living.isAlive()) {
                if (this.getDeltaMovement().length() < 0.1) {
                    noMoveTime++;
                } else {
                    noMoveTime = 0;
                }
                if (noMoveTime > 40 && mergeCooldown <= 0) {
                    split(1200);
                }
            }
        }
        if (mergeCooldown > 0) {
            mergeCooldown--;
        }
    }

@Override
	public void tick() {
		double lastTickPosX = this.xOld;
		double lastTickPosY = this.yOld;
		double lastTickPosZ = this.zOld;

		super.tick();

		if (!level().isClientSide && (!findTarget() || time > 40)) {
			discard();
			return;
		}

		boolean evil = isEvil();
		Vec3 thisVec = VecHelper.fromEntityCenter(this);
		Vec3 oldPos = new Vec3(lastTickPosX, lastTickPosY, lastTickPosZ);
		Vec3 diff = thisVec.subtract(oldPos);
		Vec3 step = diff.normalize().scale(0.05);
		int steps = (int) (diff.length() / step.length());
		Vec3 particlePos = oldPos;

		SparkleParticleData data = evil ? SparkleParticleData.corrupt(0.8F, 1F, 0.0F, 1F, 2)
				: SparkleParticleData.sparkle(0.8F, 1F, 0.4F, 1F, 2);
		for (int i = 0; i < steps; i++) {
			level().addParticle(data, particlePos.x, particlePos.y, particlePos.z, 0, 0, 0);

			if (level().random.nextInt(steps) <= 1) {
				level().addParticle(data, particlePos.x + (Math.random() - 0.5) * 0.4, particlePos.y + (Math.random() - 0.5) * 0.4, particlePos.z + (Math.random() - 0.5) * 0.4, 0, 0, 0);
			}

			particlePos = particlePos.add(step);
		}

		LivingEntity target = getTargetEntity();
		if (target != null) {
			if (lockY == Integer.MIN_VALUE) {
				lockX = target.getX();
				lockY = target.getY();
				lockZ = target.getZ();
			}

			Vec3 targetVec = evil ? new Vec3(lockX, lockY, lockZ) : VecHelper.fromEntityCenter(target);
			Vec3 diffVec = targetVec.subtract(thisVec);
			Vec3 motionVec = diffVec.normalize().scale(evil ? 0.5 : 0.6);
			setDeltaMovement(motionVec);
			if (time < 10) {
				setDeltaMovement(getDeltaMovement().x(), Math.abs(getDeltaMovement().y()), getDeltaMovement().z());
			}

			List<LivingEntity> targetList = level().getEntitiesOfClass(LivingEntity.class, new AABB(getX() - 0.5, getY() - 0.5, getZ() - 0.5, getX() + 0.5, getY() + 0.5, getZ() + 0.5));
			if (targetList.contains(target)) {
				target.hurt(this.getDamageSource(), evil ? 12 : 7);
				discard();
			}

			if (evil && diffVec.length() < 1) {
				discard();
			}
		}

		time++;
	}

public void onUse(World world, BlockPos pos, LivingEntity user, Hand hand, LivingEntity sacrifice) {
		ItemStack stack = user.getStackInHand(hand);
		if (ritualFunction != null && pos.equals(effectivePos) && stack.getItem() instanceof WaystoneItem && stack.hasNbt() && stack.getOrCreateNbt().contains("LocationPos") && world.getRegistryKey().getValue().toString().equals(stack.getOrCreateNbt().getString("LocationWorld"))) {
			effectivePos = BlockPos.fromLong(stack.getOrCreateNbt().getLong("LocationPos"));
			stack.damage(1, user, stackUser -> stackUser.sendToolBreakStatus(hand));
			syncGlyph();
		} else {
			if (ritualFunction == null) {
				SimpleInventory test = new SimpleInventory(size());
				List<ItemEntity> items = world.getEntitiesByType(EntityType.ITEM, new Box(pos).expand(2, 0, 2), entity -> true);
				for (ItemEntity entity : items) {
					test.addStack(entity.getStack().copy().split(1));
				}
				RitualRecipe recipe = world.getRecipeManager().listAllOfType(BWRecipeTypes.RITUAL_RECIPE_TYPE).stream().filter(ritualRecipe -> ritualRecipe.matches(test, world)).findFirst().orElse(null);
				if (recipe != null && recipe.input.size() == items.size() && hasValidChalk(recipe)) {
					if (recipe.ritualFunction.isValid((ServerWorld) world, pos, test) || (recipe.ritualFunction.sacrifice != null && sacrifice != null && recipe.ritualFunction.sacrifice.test(sacrifice))) {
						boolean cat = user instanceof PlayerEntity player && BewitchmentAPI.getFamiliar(player) == EntityType.CAT;
						if (altarPos != null && ((WitchAltarBlockEntity) world.getBlockEntity(altarPos)).drain((int) (recipe.cost * (cat ? 0.75f : 1)), false)) {
							world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FIRE, SoundCategory.BLOCKS, 1, 1);
							if (user instanceof PlayerEntity player) {
								player.sendMessage(Text.translatable("ritual." + recipe.getId().toString().replace(":", ".").replace("/", ".")), true);
							}
							for (int i = 0; i < items.size(); i++) {
								ItemEntity item = items.get(i);
								PlayerLookup.tracking(item).forEach(foundPlayer -> SpawnSmokeParticlesPacket.send(foundPlayer, item));
								setStack(i, item.getStack().split(1));
							}
							effectivePos = pos;
							ritualFunction = recipe.ritualFunction;
							timer = -100;
							endTime = recipe.runningTime;
							catFamiliar = cat;
							syncGlyph();
							return;
						}
						world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
						if (user instanceof PlayerEntity player) {
							player.sendMessage(Text.translatable(Bewitchment.MOD_ID + ".message.insufficent_altar_power"), true);
						}
						return;
					}
					world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
					if (user instanceof PlayerEntity player) {
						player.sendMessage(Text.translatable(recipe.ritualFunction.getInvalidMessage()), true);
					}
					return;
				}
				world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
				if (user instanceof PlayerEntity player) {
					player.sendMessage(Text.translatable("ritual.none"), true);
				}
			} else if (sacrifice == null) {
				world.playSound(null, pos, BWSoundEvents.BLOCK_GLYPH_FAIL, SoundCategory.BLOCKS, 1, 1);
				ItemScatterer.spawn(world, pos, this);
				effectivePos = null;
				ritualFunction = null;
				timer = 0;
				endTime = 0;
				catFamiliar = false;
				syncGlyph();
			}
		}
	}

@SuppressWarnings("deprecation")
	@Override
	public void tick() {
		Purpoid purpoid = this.purpoid;
		if (purpoid.isNoEndimationPlaying()) {
			Purpoid.TeleportController teleportController = purpoid.getTeleportController();
			if (!teleportController.isTeleporting()) {
				boolean sky = this.teleportPattern.next();
				BlockPos teleportPos = null;
				BlockPos pos = purpoid.blockPosition();
				RandomSource random = purpoid.getRandom();
				Level world = purpoid.level();
				Entity ridingEntity = purpoid.getVehicle();
				if (sky) {
					EntityDimensions size = purpoid.getDimensions(purpoid.getPose());
					for (int i = 0; i < 16; i++) {
						BlockPos randomPos = pos.offset(random.nextInt(32) - random.nextInt(32), random.nextInt(32) + 8, random.nextInt(32) - random.nextInt(32));
						AABB collisionBox = size.makeBoundingBox(randomPos.getX() + 0.5F, randomPos.getY(), randomPos.getZ() + 0.5F);
						if (world.hasChunkAt(randomPos) && world.noCollision(collisionBox) && !world.containsAnyLiquid(collisionBox)) {
							teleportPos = randomPos;
							break;
						}
					}
				} else {
					EntityDimensions size = ridingEntity.getDimensions(ridingEntity.getPose());
					int x = pos.getX();
					int z = pos.getZ();
					for (int i = 0; i < 32; i++) {
						int randomX = x + (random.nextInt(32) - random.nextInt(32));
						int randomZ = z + (random.nextInt(32) - random.nextInt(32));
						BlockPos.MutableBlockPos mutable = new BlockPos.MutableBlockPos(randomX, (int) ridingEntity.getY(), randomZ);
						if (world.hasChunkAt(mutable)) {
							boolean successful = true;
							while (true) {
								int y = mutable.getY();
								if (y > 0 && !world.getBlockState(mutable).blocksMotion()) {
									mutable.setY(y - 1);
								} else if (y <= 0) {
									successful = false;
									break;
								} else {
									break;
								}
							}
							if (successful) {
								mutable.move(Direction.UP);
								AABB collisionBox = size.makeBoundingBox(mutable.getX() + 0.5F, mutable.getY(), mutable.getZ() + 0.5F);
								if (world.noCollision(collisionBox) && !world.containsAnyLiquid(collisionBox)) {
									teleportPos = mutable;
									break;
								}
							}
						}
					}
				}
				if (teleportPos != null) {
					teleportController.beginTeleportation(purpoid, teleportPos, true);
					ridingEntity.hurt(purpoid.level().damageSources().mobAttack(purpoid), (float) purpoid.getAttributeValue(Attributes.ATTACK_DAMAGE));
					if (ridingEntity instanceof ServerPlayer) {
						EndergeticExpansion.CHANNEL.send(PacketDistributor.PLAYER.with(() -> (ServerPlayer) ridingEntity), new S2CEnablePurpoidFlash());
					}
				}
			}
		}
	}

@Override
    public void tick() {
        super.tick();
        prevStab = this.getStab();
        Entity entity = getTargetEntity();
        if (level().isClientSide) {
            level().addParticle(DustParticleOptions.REDSTONE, (double) this.getRandomX(0.75F), (double) this.getRandomY(), (double) this.getRandomZ(0.75F), 0.0D, 0.0D, 0.0D);
        }
        if (!playedSummonNoise) {
            this.playSound(ACSoundRegistry.DESOLATE_DAGGER_SUMMON.get());
            playedSummonNoise = true;
        }
        if (entity != null) {
            this.noPhysics = true;
            float invStab = 1F - getStab();
            Vec3 orbitAround = entity.position().add(0, entity.getBbHeight() * 0.25F, 0);
            orbitRandom.setSeed(this.getId());
            if (orbitOffset == 0) {
                orbitOffset = orbitRandom.nextInt(360);
            }
            Vec3 orbitAdd = new Vec3(0, (orbitRandom.nextFloat() + entity.getBbHeight()) * invStab, (orbitRandom.nextFloat() + entity.getBbWidth()) * invStab).yRot((float) Math.toRadians((orbitOffset)));
            this.setDeltaMovement(orbitAround.add(orbitAdd).subtract(this.position()));
            if (!level().isClientSide) {
                if (orbitFor > 0 && entity.isAlive()) {
                    orbitFor--;
                } else {
                    this.setStab(Math.min(this.getStab() + 0.2F, 1F));
                }
                if (this.getStab() >= 1F) {
                    Entity player = getPlayer();
                    Entity damageFrom = player == null ? this : player;
                    float damage = 2 + this.getItemStack().getEnchantmentLevel(ACEnchantmentRegistry.IMPENDING_STAB.get()) * 2F;
                    if (entity.hurt(ACDamageTypes.causeDesolateDaggerDamage(this.level().registryAccess(), damageFrom), damage)) {
                        this.playSound(ACSoundRegistry.DESOLATE_DAGGER_HIT.get());
                        int healBy = this.getItemStack().getEnchantmentLevel(ACEnchantmentRegistry.SATED_BLADE.get());
                        if(healBy > 0 && damageFrom instanceof Player healPlayer && healPlayer.getFoodData().getSaturationLevel() < 5F){
                            healPlayer.getFoodData().setSaturation(healPlayer.getFoodData().getSaturationLevel() + healBy * 0.1F);
                        }
                    }
                    this.discard();
                }
            }
            double d1 = entity.getZ() - this.getZ();
            double d3 = entity.getEyeY() - this.getEyeY();
            double d2 = entity.getX() - this.getX();
            float f = Mth.sqrt((float) (d2 * d2 + d1 * d1));
            this.setYRot(-((float) Mth.atan2(d2, d1)) * (180F / (float) Math.PI));
            this.setXRot(-(float) (Mth.atan2(d3, f) * (double) (180F / (float) Math.PI)));
        } else if (tickCount > 3) {
            this.noPhysics = false;
            this.discard();
        }
        this.move(MoverType.SELF, this.getDeltaMovement());
        this.setDeltaMovement(this.getDeltaMovement().scale(0.9F));

        if (this.level().isClientSide) {
            if (this.lSteps > 0) {
                double d5 = this.getX() + (this.lx - this.getX()) / (double) this.lSteps;
                double d6 = this.getY() + (this.ly - this.getY()) / (double) this.lSteps;
                double d7 = this.getZ() + (this.lz - this.getZ()) / (double) this.lSteps;
                this.setYRot(Mth.wrapDegrees((float) this.lyr));
                this.setXRot(this.getXRot() + (float) (this.lxr - (double) this.getXRot()) / (float) this.lSteps);
                --this.lSteps;
                this.setPos(d5, d6, d7);
            } else {
                this.reapplyPosition();
            }
        }
    }

@Override
    public void tick() {
        float progress = this.getProgress();
        this.prevProgress = progress;
        if(tickCount < 1){
            onJoinWorld();
        }else if(tickCount == 1){
            if(!this.level().isClientSide){
                this.playSound(AMSoundRegistry.TENDON_WHIP.get(),1.0F, 0.8F + this.random.nextFloat() * 0.4F);
            }
        }
        super.tick();
        Entity creator = getCreatorEntity();
        Entity current = getToEntity();
        if(progress < MAX_EXTEND_TIME && !this.isRetracting()){
            this.setProgress(progress + 1);
        }
        if(progress > 0F && this.isRetracting()){
            this.setProgress(progress - 1);
        }
        if(progress == 0F && this.isRetracting()){
            Entity from = this.getFromEntity();
            if(from instanceof EntityTendonSegment){
                EntityTendonSegment tendonSegment = (EntityTendonSegment) from;
                tendonSegment.setRetracting(true);
                updateLastTendon(tendonSegment);
            }else{
                updateLastTendon(null);
            }

            this.remove(RemovalReason.DISCARDED);
        }
        if (creator instanceof LivingEntity) {
            if (current != null) {
                Vec3 target = new Vec3(current.getX(), current.getY(0.4F), current.getZ());
                Vec3 lerp = target.subtract(this.position());
                this.setDeltaMovement(lerp.scale(0.5F));
                if(!this.level().isClientSide){
                    if(!hasTouched && progress >= MAX_EXTEND_TIME){
                        hasTouched = true;
                        Entity entity = getCreatorEntity();
                        if(entity instanceof LivingEntity){
                            if(current != creator && current.hurt(damageSources().mobProjectile(this, (LivingEntity)entity), (float) getDamageFor((LivingEntity)creator, (LivingEntity)entity))){
                                this.doEnchantDamageEffects((LivingEntity) creator, entity);
                            }
                        }
                    }
                }
            }
        }
        Vec3 vector3d = this.getDeltaMovement();
        if(!this.level().isClientSide){
            if(!hasChained){
                if(this.getTargetsHit() > 3){
                    this.setRetracting(true);
                }else if(creator instanceof LivingEntity && this.getProgress() >= MAX_EXTEND_TIME) {
                    Entity closestValid = null;
                    for (Entity entity : this.level().getEntitiesOfClass(LivingEntity.class, this.getBoundingBox().inflate(8.0D))) {
                        if (!entity.equals(creator) && !previouslyTouched.contains(entity) && isValidTarget((LivingEntity) creator, entity) && this.hasLineOfSight(entity)) {
                            if (closestValid == null || this.distanceTo(entity) < this.distanceTo(closestValid)) {
                                closestValid = entity;
                            }
                        }
                    }
                    if(closestValid != null){
                        createChain(closestValid);
                        hasChained = true;
                    }else{
                        this.setRetracting(true);
                    }
                }
            }
        }
        final double d0 = this.getX() + vector3d.x;
        final double d1 = this.getY() + vector3d.y;
        final double d2 = this.getZ() + vector3d.z;
        this.setDeltaMovement(vector3d.scale(0.99F));
        this.setPos(d0, d1, d2);
    }

@Override
	public void tick() {
		Entity thrower = getOwner();
		if (!(thrower instanceof Player player) || !thrower.isAlive()) {
			if (!level().isClientSide) {
				discard();
			}
			return;
		}
		if (!level().isClientSide) {
			ItemStack stack = PlayerHelper.getFirstHeldItem(player, BotaniaItems.kingKey);
			boolean newCharging = !stack.isEmpty() && KeyOfTheKingsLawItem.isCharging(stack);
			if (isCharging() != newCharging) {
				setCharging(newCharging);
			}
		}

		Vec3 mot = getDeltaMovement();

		int liveTime = getLiveTicks();
		int delay = getDelay();
		boolean charging = isCharging() && liveTime == 0;

		if (charging) {
			setDeltaMovement(Vec3.ZERO);

			int chargeTime = getChargeTicks();
			setChargeTicks(chargeTime + 1);

			if (level().random.nextInt(20) == 0) {
				level().playSound(null, getX(), getY(), getZ(), BotaniaSounds.babylonSpawn, SoundSource.PLAYERS, 0.1F, 1F + level().random.nextFloat() * 3F);
			}
		} else {
			if (liveTime < delay) {
				setDeltaMovement(Vec3.ZERO);
			} else if (liveTime == delay) {
				Vec3 playerLook;
				BlockHitResult rtr = ToolCommons.raytraceFromEntity(player, 64, true);
				if (rtr.getType() != HitResult.Type.BLOCK) {
					playerLook = player.getLookAngle().scale(64).add(player.position());
				} else {
					playerLook = Vec3.atCenterOf(rtr.getBlockPos());
				}

				Vec3 thisVec = VecHelper.fromEntityCenter(this);

				mot = playerLook.subtract(thisVec.x, thisVec.y, thisVec.z).normalize().scale(2);
				level().playSound(null, getX(), getY(), getZ(), BotaniaSounds.babylonAttack, SoundSource.PLAYERS, 2F, 0.1F + level().random.nextFloat() * 3F);
			}

			if (!level().isClientSide) {
				setLiveTicks(liveTime + 1);
				AABB axis = new AABB(getX(), getY(), getZ(), xOld, yOld, zOld).inflate(2);
				List<LivingEntity> entities = level().getEntitiesOfClass(LivingEntity.class, axis);
				for (LivingEntity living : entities) {
					if (living == thrower) {
						continue;
					}

					if (living.hurtTime == 0) {
						living.hurt(level().damageSources().playerAttack(player), 20);
						onHit(new EntityHitResult(living));
						return;
					}
				}
			}
		}

		super.tick();

		// Apply after super tick so drag is not applied by super
		setDeltaMovement(mot);

		if (level().isClientSide && liveTime > delay) {
			WispParticleData data = WispParticleData.wisp(0.3F, 1F, 1F, 0F, 1);
			level().addParticle(data, getX(), getY(), getZ(), 0, -0F, 0);
		}

		if (!level().isClientSide && liveTime > 200 + delay) {
			discard();
		}
	}

@Override
    public void tick() {
        super.tick();

        var level = getCommandSenderWorld();

        var particleCenter = this.position().add(this.getDeltaMovement().scale(-1F));

        for (int i = 0; i < 5; i++)
            level.addParticle(ParticleUtils.constructSimpleSpark(new Color(50 + random.nextInt(100), 0, 150 + random.nextInt(100)), 0.1F + random.nextFloat() * 0.15F, 5 + random.nextInt(10), 0.85F),
                    particleCenter.x() + MathUtils.randomFloat(random) * 0.25F, particleCenter.y(), particleCenter.z() + MathUtils.randomFloat(random) * 0.25F, 0F, 0F, 0F);

        var currentTarget = getTarget();

        if (currentTarget != null && (this.position().distanceTo(currentTarget.position()) >= 16F || currentTarget.isDeadOrDying()))
            currentTarget = null;

        if (!level.isClientSide()) {
            LivingEntity potentialTarget = null;

            var candidateEntities = locateNearestTargets();

            candidateEntities.removeIf(entity -> blacklistedTargets.contains(entity.getStringUUID()));

            var targetEntities = candidateEntities.stream()
                    .filter(entity -> {
                        var uuid = entity.getStringUUID();

                        return !bouncedTargets.contains(uuid) && !blacklistedTargets.contains(uuid);
                    })
                    .toList();

            if (!targetEntities.isEmpty())
                potentialTarget = targetEntities.getFirst();
            else if (!candidateEntities.isEmpty()) {
                bouncedTargets.clear();

                potentialTarget = candidateEntities.getFirst();
            }

            if (potentialTarget != null && (currentTarget == null || !currentTarget.getStringUUID().equals(potentialTarget.getStringUUID()))) {
                NetworkHandler.sendToClientsTrackingEntity(new S2CSyncEntityTargetPacket(this.getId(), potentialTarget.getId()), this);

                setTarget(potentialTarget);

                currentTarget = potentialTarget;
            }
        }

        if (currentTarget == null || currentTarget.isDeadOrDying() || this.tickCount >= 250 || getBounces() >= getMaxBounces()) {
            if (!level.isClientSide())
                this.discard();

            return;
        }

        if (this.getEyePosition().distanceTo(currentTarget.getEyePosition()) <= 1.5F) {
            currentTarget.invulnerableTime = 0;

            if (currentTarget.hurt(level.damageSources().thrown(this, getOwner()), getDamage())) {
                bouncedTargets.add(currentTarget.getStringUUID());
                lastTarget = currentTarget;

                setTarget(null);
                addBounces(1);

                if (random.nextDouble() <= getChance()) {
                    var entity = new ShadowGlaiveEntity(RelicsEntities.SHADOW_GLAIVE.get(), level);

                    entity.setMaxBounces(getMaxBounces());
                    entity.setBounces(getBounces());
                    entity.setPos(getEyePosition());
                    entity.setDamage(getDamage());
                    entity.setOwner(getOwner());

                    level.addFreshEntity(entity);
                }
            } else {
                blacklistedTargets.add(currentTarget.getStringUUID());

                setTarget(null);
            }
        } else {
            this.setDeltaMovement(currentTarget.getEyePosition().subtract(this.getEyePosition()).normalize());
        }
    }

public void attackTargetEntityWithCurrentItem(Entity targetEntity, Player player, float damageMult, float knockbackMult) {
        if (!CommonHooks.onPlayerAttackTarget(player, targetEntity) || !targetEntity.isAttackable()) {
            return;
        }

        ItemStack oldStack = player.getMainHandItem();
        ItemStack newStack = getAxeStack();
        resetModifiers(player, oldStack, newStack);
        player.setItemInHand(InteractionHand.MAIN_HAND, newStack);

        // Check this after swapping main hand in cases the main hand item impacts the result
        if (targetEntity.skipAttackInteraction(player)) {
            resetModifiers(player, newStack, oldStack);
            player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
            return;
        }

        if (targetEntity.getType().is(EntityTypeTags.REDIRECTABLE_PROJECTILE) && targetEntity instanceof Projectile projectile && projectile.deflect(ProjectileDeflection.AIM_DEFLECT, this, this, true)) {
            this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, this.getSoundSource());
            resetModifiers(player, newStack, oldStack);
            player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
            return;
        }

        DamageSource damageSource = damageSources().playerAttack(player);

        float attackDamage = (float) player.getAttributeValue(Attributes.ATTACK_DAMAGE) * damageMult;
        float enchantedDamage = player.getEnchantedDamage(targetEntity, attackDamage, damageSource);

        if (attackDamage > 0 || enchantedDamage > 0) {
            boolean wasSprinting = false;

            if (player.isSprinting()) {
                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_KNOCKBACK, player.getSoundSource(), 1.0F, 1.0F);
                wasSprinting = true;
            }

            attackDamage += newStack.getItem().getAttackDamageBonus(targetEntity, attackDamage, damageSource);
            float damage = attackDamage + enchantedDamage;
            float targetHealth = targetEntity instanceof LivingEntity livingTarget ? livingTarget.getHealth() : 0;

            Vec3 targetMovement = targetEntity.getDeltaMovement();
            boolean wasHurt = targetEntity.hurt(damageSource, damage);

            if (wasHurt) {
                float knockback = player.getKnockback(targetEntity, damageSource) + (wasSprinting ? 1 : 0);

                if (knockback > 0) {
                    if (targetEntity instanceof LivingEntity livingTarget) {
                        livingTarget.knockback(knockback * 0.5F * knockbackMult, Mth.sin(player.getYRot() * ((float) Math.PI / 180F)), -Mth.cos(player.getYRot() * ((float) Math.PI / 180F)));
                    } else {
                        targetEntity.push(-Mth.sin(player.getYRot() * ((float) Math.PI / 180F)) * knockback * 0.5F * knockbackMult, 0.1D, Mth.cos(player.getYRot() * ((float) Math.PI / 180F)) * knockback * 0.5F * knockbackMult);
                    }

                    player.setDeltaMovement(player.getDeltaMovement().multiply(0.6D, 1.0D, 0.6D));
                    player.setSprinting(false);
                }

                if (targetEntity instanceof ServerPlayer && targetEntity.hurtMarked) {
                    ((ServerPlayer) targetEntity).connection.send(new ClientboundSetEntityMotionPacket(targetEntity));
                    targetEntity.hurtMarked = false;
                    targetEntity.setDeltaMovement(targetMovement);
                }

                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_STRONG, player.getSoundSource(), 1.0F, 1.0F);

                if (enchantedDamage > 0) {
                    player.magicCrit(targetEntity);
                }

                player.setLastHurtMob(targetEntity);
                Entity entity = targetEntity;

                if (targetEntity instanceof PartEntity<?> part) {
                    entity = part.getParent();
                }

                ItemStack copy = newStack.copy();
                boolean hurtEnemy = false;

                if (level() instanceof ServerLevel serverLevel) {
                    if (entity instanceof LivingEntity livingEntity) {
                        hurtEnemy = newStack.hurtEnemy(livingEntity, player);
                    }

                    EnchantmentHelper.doPostAttackEffects(serverLevel, targetEntity, damageSource);
                }

                if (!level().isClientSide() && !copy.isEmpty() && entity instanceof LivingEntity livingEntity) {
                    if (hurtEnemy) {
                        newStack.postHurtEnemy(livingEntity, player);
                    }

                    if (newStack.isEmpty()) {
                        EventHooks.onPlayerDestroyItem(player, copy, InteractionHand.MAIN_HAND);
                        player.setItemInHand(InteractionHand.MAIN_HAND, ItemStack.EMPTY);
                    }
                }

                if (targetEntity instanceof LivingEntity livingTarget) {
                    float healthDifference = targetHealth - livingTarget.getHealth();
                    player.awardStat(Stats.DAMAGE_DEALT, Math.round(healthDifference * 10));

                    if (level() instanceof ServerLevel serverLevel && healthDifference > 2) {
                        int particleCount = (int) ((double) healthDifference * 0.5);
                        serverLevel.sendParticles(ParticleTypes.DAMAGE_INDICATOR, targetEntity.getX(), targetEntity.getY(0.5), targetEntity.getZ(), particleCount, 0.1, 0.0, 0.1, 0.2);
                    }
                }

                player.causeFoodExhaustion(0.1F);
            } else {
                player.level().playSound(null, player.getX(), player.getY(), player.getZ(), SoundEvents.PLAYER_ATTACK_NODAMAGE, player.getSoundSource(), 1.0F, 1.0F);
            }
        }

        resetModifiers(player, newStack, oldStack);
        player.setItemInHand(InteractionHand.MAIN_HAND, oldStack);
    }

@WrapWithCondition(method = "method_31420", at = @At(
		value = "INVOKE",
		target = "Lnet/minecraft/server/level/ServerLevel;guardEntityTick(Ljava/util/function/Consumer;Lnet/minecraft/world/entity/Entity;)V"
	))
	private boolean slowTime(ServerLevel instance, Consumer<?> consumer, Entity entity) {
		if(ArcanusHelper.shouldTimeDilate(entity, this) && getGameTime() % 2 == 0) {
			entity.setOldPosAndRot();
			entity.tickCount++;
			return false;
		}

		return true;
	}

private void knockbackExhilaration(Player attacker, Vec3 origin, LivingEntity target, long timeLimit, double multiplier) {
        ServerScheduler.schedule(20, () -> {
            if (target.onGround()) {
                double distance = Math.min(20, origin.distanceTo(target.position()));
                int amplifier = (int) (distance * multiplier) - 1;
                if (amplifier >= 0) {
                    attacker.addEffect(new MobEffectInstance(SmallStrengthPotionEffect.instance, 200, amplifier, false, true));
                }
            } else if (target.level().getGameTime() < timeLimit) {
                knockbackExhilaration(attacker, origin, target, timeLimit, multiplier);
            }
        });
    }

public static void onSpellResolve(SpellResolveEvent.Pre pre) {
        HitResult hitResult = pre.rayTraceResult;
        if (pre.context.getUnwrappedCaster() instanceof Breeze) {
            return;
        }
        if (hitResult instanceof EntityHitResult entityHitResult
                && !(pre.shooter instanceof FakePlayer fakePlayer)
                && entityHitResult.getEntity() instanceof Breeze breeze
                && pre.resolver.spell.getCastMethod() instanceof MethodProjectile) {
            pre.setCanceled(true);
            EntityOrbitProjectile orbitProjectile = new EntityOrbitProjectile(breeze.level, new SpellResolver(SpellContext.fromEntity(pre.spell, breeze, ItemStack.EMPTY)), entityHitResult.getEntity());
            breeze.level.addFreshEntity(orbitProjectile);
            EventQueue.getServerInstance().addEvent(new BreezeEvent(breeze, orbitProjectile, pre.shooter));
        }
    }

@Override
	public void effect(@Nullable LivingEntity caster, @Nullable Entity sourceEntity, Level level, HitResult target, List<SpellEffect> effects, ItemStack stack, double potency) {
		if(target.getType() == HitResult.Type.BLOCK) {
			BlockHitResult blockHit = (BlockHitResult) target;
			BlockPos pos = blockHit.getBlockPos().relative(blockHit.getDirection());

			if(level.getBlockState(pos).canBeReplaced() && (!(caster instanceof Player player) || level.mayInteract(player, pos))) {
				level.setBlock(pos, ArcanusBlocks.MAGIC_BLOCK.get().defaultBlockState(), Block.UPDATE_CLIENTS);
				level.scheduleTick(pos, level.getBlockState(pos).getBlock(), (int) (ArcanusConfig.UtilityEffects.BuildEffectProperties.baseLifeSpan * potency));

				if(caster != null) {
					level.getBlockEntity(pos, ArcanusBlockEntities.MAGIC_BLOCK.get()).ifPresent(blockEntity -> ArcanusHelper.copyMagicColor(blockEntity, caster));
				}
			}
		}
	}

private void checkMistFormTrigger() {
        long gameTime = this.level().getGameTime();
        if (gameTime < this.mistCooldownUntil) return;
        this.recentDamage.removeIf(p -> gameTime - p.getFirst() > 100);
        float total = 0;
        for (Pair<Long, Float> p : this.recentDamage) {
            total += p.getSecond();
        }
        if (total > this.getMaxHealth() * 0.2f) {
            this.setState(DraculaState.MIST);
            this.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
            this.mistStartTime = gameTime;
            this.mistCooldownUntil = gameTime + MIST_COOLDOWN;
            this.recentDamage.clear();
        }
    }

public void fulfilRequest() {
		if (!hasPendingRequest()) {
			return;
		}

		CorporeaSpark spark = CorporeaHelper.instance().getSparkForBlock(level, requestPos);
		if (spark != null) {
			BlockEntity te = spark.getSparkNode().getWorld().getBlockEntity(spark.getSparkNode().getPos());
			if (te instanceof CorporeaRequestor requestor) {
				requestor.doCorporeaRequest(request, requestCount, spark, null);

				forget();
				setChanged();
			}
		}
	}

private void updateTimes(Level level) {
		if (paused) {
			unpause(level);
			return;
		}

		if (isBurning(level)) {
			remainingBurnTime = getBurnTimeFinish() - level.getGameTime();
		} else {
			remainingBurnTime = 0;
		}
		if (isCooking()) {
			remainingCookTime = getCookTimeFinish() - level.getGameTime();
		} else {
			remainingCookTime = 0;
		}
	}

@Override
    public boolean canUse() {
        long worldTime = this.seagull.level().getGameTime() % 10;
        if (this.seagull.getNoActionTime() >= 100 && worldTime != 0 || seagull.isSitting() || !AMConfig.seagullStealing) {
            return false;
        }
        if (this.seagull.getRandom().nextInt(12) != 0 && worldTime != 0 || seagull.stealCooldown > 0) {
            return false;
        }
        if(this.seagull.getMainHandItem().isEmpty()){
            Player valid = getClosestValidPlayer();
            if(valid != null){
                target = valid;
                return true;
            }
        }
        return false;
    }

public boolean boost(ItemStack stack, LivingEntity entity, int time) {

        if (!entity.getItemBySlot(EquipmentSlot.CHEST).canElytraFly(entity)) {
            return false;
        }
        boolean isPlayer = entity instanceof Player;
        boolean isCreative = isPlayer && ((Player) entity).abilities.instabuild;
        if (!useEnergy(stack, getEnergyPerUse(true) * time / energyUseInterval, isCreative)) {
            return false;
        }
        if (!entity.isFallFlying() && isPlayer) {
            ((Player) entity).startFallFlying();
        }
        propel(entity, propelSpeed);
        stack.getOrCreateTag().putLong(NBTTags.TAG_TIME, entity.level.getGameTime());

        return true;
    }

@Override
	public void neighborChanged(BlockState state, Level level, BlockPos pos, Block block, BlockPos fromPos,
		boolean isMoving) {
		if (level.isClientSide)
			return;

		Direction blockFacing = state.getValue(FACING);
		if (fromPos.equals(pos.relative(blockFacing.getOpposite()))) {
			if (!canSurvive(state, level, pos)) {
				level.destroyBlock(pos, true);
				return;
			}
		}

		if (!level.getBlockTicks()
			.willTickThisTick(pos, this))
			level.scheduleTick(pos, this, 1);
	}

@Override
    public void tick(boolean serverSide) {
        ticks++;
        if (ticks < 5)
            return;
        if (!serverSide || level.getGameTime() % 3 != 0)
            return;

        boolean destroyPortal = false;
        boolean placingFrame = !framePos.isEmpty();
        if (placingFrame) {
            BlockPos pos = framePos.get(0);
            framePos.remove(pos);
            BlockState bs = level.getBlockState(pos);
            if (bs.is(BlockTagProvider.DECORATIVE_AN) || level.getBlockEntity(pos) instanceof TemporaryTile tile && tile.mimicState.is(BlockTagProvider.DECORATIVE_AN)) {
                tick(true);
                if (level.getBlockEntity(pos) instanceof TemporaryTile tile) {
                    tile.mimicState = BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState();
                    tile.tickDuration = 20 * 60;
                    tile.gameTime = level.getGameTime();
                    tile.updateBlock();
                }
                return;
            }
            if (bs.canBeReplaced() || level.getBlockEntity(pos) instanceof TemporaryTile tile && tile.mimicState.is(BlockTagProvider.DECORATIVE_AN)) {
                level.setBlock(pos, BlockRegistry.TEMPORARY_BLOCK.get().defaultBlockState(), 3);
                if (level.getBlockEntity(pos) instanceof TemporaryTile tile) {
                    tile.mimicState = BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState();
                    tile.tickDuration = 20 * 60;
                    tile.gameTime = level.getGameTime();
                    tile.updateBlock();
                }
                level.playSound(null, pos, BlockRegistry.getBlock(LibBlockNames.SOURCESTONE).defaultBlockState().getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
                ParticleUtil.spawnTouchPacket(level, pos, ParticleColor.makeRandomColor(255, 255, 255, level.random));
                placedBlocks.add(pos);
                return;
            } else {
                destroyPortal = true;
                ServerLevel serverLevel = (ServerLevel) level;
                serverLevel.sendParticles(ParticleTypes.EXPLOSION, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0);
            }
        }
        boolean placingPortal = !portalPos.isEmpty() && framePos.isEmpty() && !destroyPortal;
        if (placingPortal) {
            for (BlockPos pos : portalPos) {
                if (level.getBlockState(pos).canBeReplaced()) {
                    level.setBlock(pos, BlockRegistry.PORTAL_BLOCK.defaultBlockState().setValue(PortalBlock.AXIS, direction.getAxis()), 2);
                    level.playSound(null, pos, BlockRegistry.PORTAL_BLOCK.get().defaultBlockState().getSoundType().getPlaceSound(), SoundSource.BLOCKS, 1.0F, 1.0F);
                    placedBlocks.add(pos);
                } else {
                    destroyPortal = true;
                    ServerLevel serverLevel = (ServerLevel) level;
                    serverLevel.sendParticles(ParticleTypes.EXPLOSION, pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5, 1, 0, 0, 0, 0);
                    break;
                }
            }
            portalPos.clear();
        }
        if (destroyPortal) {
            for (BlockPos pos : placedBlocks) {
                level.destroyBlock(pos, false);
            }
            level.playSound(null, targetPos, SoundRegistry.GAIA_SPELL_SOUND.getSoundEvent().value(), SoundSource.BLOCKS, 1.0F, 1.0F);
            portalPos.clear();
            framePos.clear();
            return;
        }
        if (portalPos.isEmpty()) {
            level.playSound(null, targetPos.above(2), SoundRegistry.TEMPESTRY_SPELL_SOUND.getSoundEvent().value(), SoundSource.BLOCKS, 1.0F, 1.0F);
            for (BlockPos pos : placedBlocks) {
                if (level.getBlockEntity(pos) instanceof PortalTile portalTile) {
                    portalTile.setFromScroll(warpScrollData);
                }
            }
        }
    }

public boolean onUsedByWand(Player player, ItemStack stack, Level world, BlockPos pos) {
		if (world.isClientSide) {
			return false;
		}

		if (player == null || player.isShiftKeyDown()) {
			world.destroyBlock(pos, true);
		} else {
			GlobalPos clicked = GlobalPos.of(world.dimension(), pos.immutable());
			if (WandOfTheForestItem.getBindMode(stack)) {
				activeBindingAttempts.put(player.getUUID(), clicked);
				world.playSound(null, pos, BotaniaSounds.ding, SoundSource.BLOCKS, 0.5F, 1F);
			} else {
				var data = WorldData.get(world);
				if (XplatAbstractions.INSTANCE.isDevEnvironment()) {
					BotaniaAPI.LOGGER.info("PistonRelay pairs");
					for (var e : data.mapping.entrySet()) {
						BotaniaAPI.LOGGER.info("{} -> {}", e.getKey(), e.getValue());
					}
				}
				BlockPos dest = data.mapping.get(pos);
				if (dest != null) {
					XplatAbstractions.INSTANCE.sendToNear(world, pos, new BotaniaEffectPacket(EffectType.PARTICLE_BEAM,
							pos.getX() + 0.5, pos.getY() + 0.5, pos.getZ() + 0.5,
							dest.getX(), dest.getY(), dest.getZ()));
				}
			}
		}

		return true;
	}

public static void onLevelTick(Level level) {
		if(!level.isClientSide()) {
			for(Entity entity : toUpdate.keySet()) {
				if(!entity.hurtMarked) { // Allow velocity change packets to take priority.
					MotionUpdate update = toUpdate.get(entity);
					if(update != null) { // Edge case where the entity expired in the ms between calls
						Vec3 total = update.predicted.add(update.unpredicted);
						//We want a player's motion to be handled client-side to ensure movement consistency
						//Otherwise it feels jerky.
						if(entity instanceof ServerPlayer player) {
							reduceAboveGroundTicks(player, entity);
							if(!update.predicted.equals(Vec3.ZERO)) {
								PsiNetwork.sendToPlayer(player, new MessageAdditiveMotion(entity.getId(), update.predicted.x, update.predicted.y, update.predicted.z, true));
							}
							if(!update.unpredicted.equals(Vec3.ZERO)) {
								PsiNetwork.sendToPlayer(player, new MessageAdditiveMotion(entity.getId(), update.unpredicted.x, update.unpredicted.y, update.unpredicted.z, false));
							}
							reduceAboveGroundTicks(player, entity);
						} else {
							entity.push(total.x, total.y, total.z);
						}
						if(entity.level() instanceof ServerLevel) {
							PsiNetwork.sendToPlayersTracking(entity, new MessageAdditiveMotion(entity.getId(), total.x, total.y, total.z, false));
						}

					}
				}
			}

			toUpdate.clear();
		}
	}

public void activateDeferred() {
		if (cannotLaunch())
			return;
		Direction facing = getFacing();
		List<Entity> entities =
			level.getEntitiesOfClass(Entity.class, new AABB(worldPosition).inflate(-1 / 16f, 0, -1 / 16f));

		// Launch Items
		boolean doLogic = !level.isClientSide || isVirtual();
		if (doLogic)
			launchItems();

		// Launch Entities
		for (Entity entity : entities) {
			boolean isPlayerEntity = entity instanceof Player;
			if (!entity.isAlive())
				continue;
			if (entity instanceof ItemEntity)
				continue;
			if (entity instanceof PackageEntity)
				continue;
			if (entity.getPistonPushReaction() == PushReaction.IGNORE)
				continue;

			entity.setOnGround(false);

			if (isPlayerEntity != level.isClientSide)
				continue;

			entity.setPos(worldPosition.getX() + 0.5, worldPosition.getY() + 1.0, worldPosition.getZ() + 0.5);
			launcher.applyMotion(entity, facing);

			if (!isPlayerEntity)
				continue;

			Player playerEntity = (Player) entity;

			if (launcher.getHorizontalDistance() * launcher.getHorizontalDistance()
				+ launcher.getVerticalDistance() * launcher.getVerticalDistance() >= 25 * 25)
				CatnipServices.NETWORK.sendToServer(new EjectorAwardPacket(worldPosition));

			if (!(playerEntity.getItemBySlot(EquipmentSlot.CHEST)
				.getItem() instanceof ElytraItem))
				continue;

			playerEntity.setXRot(-35);
			playerEntity.setYRot(facing.toYRot());
			playerEntity.setDeltaMovement(playerEntity.getDeltaMovement()
				.scale(.75f));
			deployElytra(playerEntity);
			CatnipServices.NETWORK.sendToServer(new EjectorElytraPacket(worldPosition));
		}

		if (doLogic) {
			lidProgress.chase(1, .8f, Chaser.EXP);
			state = State.LAUNCHING;
			if (!level.isClientSide) {
				level.playSound(null, worldPosition, SoundEvents.WOODEN_TRAPDOOR_CLOSE, SoundSource.BLOCKS, .35f, 1f);
				level.playSound(null, worldPosition, SoundEvents.CHEST_OPEN, SoundSource.BLOCKS, .1f, 1.4f);
			}
		}
	}

@Override
		public void tick() {
			super.tick();

			if (getPassengers().isEmpty() && !level().isClientSide) {
				discard();
				return;
			}

			boolean isItem = getPassengers().stream().allMatch(ItemEntity.class::isInstance);
			if (!isItem && tickCount % 30 == 0) {
				playSound(BotaniaSounds.lightRelay, 0.25F, (float) Math.random() * 0.3F + 0.7F);
			}
			if (!isItem && tickCount % 10 == 0) {
				gameEvent(GameEvent.ELYTRA_GLIDE);
			}

			BlockPos pos = blockPosition();
			BlockPos exitPos = getExitPos();

			if (!level().isClientSide && pos.equals(exitPos)) {
				boolean done = true;
				BlockEntity tile = level().getBlockEntity(pos);
				if (tile instanceof LuminizerBlockEntity relay) {
					BlockState state = level().getBlockState(pos);
					if (state.is(BotaniaBlocks.lightRelayDetector)) {
						level().setBlockAndUpdate(pos, state.setValue(BlockStateProperties.POWERED, true));
						level().scheduleTick(pos, state.getBlock(), 2);
					}

					BlockPos bind = relay.getNextDestination();
					if (bind != null && relay.isValidBinding()) {
						setExit(bind);
						done = false;
					}
				}

				if (done) {
					for (Entity e : getPassengers()) {
						e.stopRiding();
					}
					discard();
					return;
				}
			}
			Vec3 thisVec = position();
			Vec3 motVec = thisVec.reverse().add(exitPos.getX() + 0.5, exitPos.getY() + 0.5, exitPos.getZ() + 0.5).normalize().scale(0.5);

			int color;

			int count = 4;
			for (int i = 0; i < count; i++) {
				color = Mth.hsvToRgb(tickCount / 36F + 1F / count * i, 1F, 1F);
				double rad = Math.PI * 2.0 / count * i + tickCount / Math.PI;
				double cos = Math.cos(rad);
				double sin = Math.sin(rad);
				double s = 0.4;

				int r = (color >> 16) & 0xFF;
				int g = (color >> 8) & 0xFF;
				int b = color & 0xFF;
				SparkleParticleData data = SparkleParticleData.sparkle(1.2F, r / 255F, g / 255F, b / 255F, 10);
				level().addParticle(data, getX() + cos * s, getY() - 0.5, getZ() + sin * s, 0, 0, 0);
			}

			setPos(getX() + motVec.x, getY() + motVec.y, getZ() + motVec.z);
		}

@Override
    public void tickServer() {
        super.tickServer();

        isCoreLoaded = inv.isCorePresent();

        if (isOpen() && isCoreLoaded && inv.getStats().getUnusedPercentage() > 0 && getPressure() <= getMinWorkingPressure()) {
            if ((nonNullLevel().getGameTime() & 0xf) == 0) {
                scanForEntities();
            }
            Vec3 trapVec = Vec3.atCenterOf(worldPosition);
            double min = nonNullLevel().getFluidState(worldPosition).getType() == Fluids.WATER ? 2.5 : 1.75;
            for (Mob e : targetEntities) {
                if (!e.isAlive() || e.getTags().contains(DEFENDER_TAG)) continue;
                // kludge: mobs in water seem a bit flaky about getting close enough so increase the absorb dist a bit
                if (e.distanceToSqr(trapVec) <= min) {
                    absorbEntity(e);
                    addAir((int) (PneumaticValues.USAGE_VACUUM_TRAP * e.getHealth()));
                } else {
                    e.getNavigation().moveTo(trapVec.x(), trapVec.y(), trapVec.z(), 1.2);
                }
            }
        }
        if (!isCoreLoaded)
            problem = Problems.NO_CORE;
        else if (inv.getStats().getUnusedPercentage() == 0)
            problem = Problems.CORE_FULL;
        else if (!isOpen())
            problem = Problems.TRAP_CLOSED;
        else
            problem = Problems.OK;
    }

@Override
    public StarbyState onDestinationReached() {
        this.starbuncle.getNavigation().stop();

        IItemHandler iItemHandler = behavior.getItemCapFromTile(targetPos, behavior.TO_DIRECTION_MAP.get(targetPos.hashCode()));
        if (iItemHandler == null) {
            starbuncle.addGoalDebug(this, new DebugEvent("NoItemHandler", "No item handler at " + targetPos.toString()));
            return nextState;
        }

        boolean didDeposit = depositStack(iItemHandler);
        if (!didDeposit) {
            starbuncle.setBackOff(5 + starbuncle.level.random.nextInt(20));
            starbuncle.addGoalDebug(this, new DebugEvent("no_room", targetPos.toString()));
            return nextState;
        }

        OpenChestEvent event = new OpenChestEvent((ServerLevel) starbuncle.level, targetPos, 20);
        event.open();
        EventQueue.getServerInstance().addEvent(event);

        ItemStack left = starbuncle.getHeldStack();
        starbuncle.addGoalDebug(this, new DebugEvent("stored_item", "successful at " + targetPos.toString() + "set stack to " + left.getCount() + "x " + left.getHoverName().getString()));
        boolean fetchPassengerStack = left.isEmpty();
        while (fetchPassengerStack) {
            fetchPassengerStack = false;
            starbuncle.getNextItemFromPassengers();
            if (!starbuncle.getHeldStack().isEmpty()) {
                fetchPassengerStack = depositStack(iItemHandler) && starbuncle.getHeldStack().isEmpty();
            }
        }
        return nextState;
    }

@Override
    public void tick() {
        if (isDecorative && level.isClientSide) {
            makeParticle(color.nextColor((int) level.getGameTime() * 20), color.nextColor((int) level.getGameTime() * 20 + 200), 10);
            return;
        }


        if (level.isClientSide && ritual != null) {
            makeParticle(ritual.getCenterColor(), ritual.getOuterColor(), ritual.getParticleIntensity());
        }
        if (isOff)
            return;
        if (ritual != null) {

            if (ritual.getContext().isDone) {
                ritual.onEnd();
                ritual = null;
                getLevel().playSound(null, getBlockPos(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0f, 1.0f);
                getLevel().setBlock(getBlockPos(), getLevel().getBlockState(getBlockPos()).setValue(RitualBrazierBlock.LIT, false), 3);
                updateBlock();
                return;
            }
            if (!ritual.isRunning() && !level.isClientSide && level.getGameTime() % 5 == 0) {
                level.getEntitiesOfClass(ItemEntity.class, new AABB(getBlockPos()).inflate(1)).forEach(i -> {
                    tryBurnStack(i.getItem());
                });
            }
            if (ritual.consumesSource() && ritual.needsSourceNow()) {
                if (this.sourceBackoff-- <= 0) {
                    int cost = ritual.getSourceCost();
                    if (SourceUtil.takeSourceMultipleWithParticles(getBlockPos(), getLevel(), 6, cost) != null) {
                        ritual.setNeedsSource(false);
                        this.sourceBackoff = 0;
                        updateBlock();
                    } else {
                        this.sourceBackoff = 20;
                        return;
                    }
                } else {
                    return;
                }
            }
            if (this.relayPos != null && level.isLoaded(this.relayPos) && level.getBlockEntity(this.relayPos) instanceof BrazierRelayTile relayTile) {
                ritual.tryTick(relayTile);
                relayTile.ticksToLightOff = 2;
                relayTile.isDecorative = false;
            } else {
                ritual.tryTick(this);
            }
        }
    }

