@Override
	public void onUpdate() {
		if (getEntityWorld().isRemote) {
	            if (isInWater() && !getEntityWorld().getBlockState(getPosition().down()).getMaterial().isSolid())
					motionY -= 0.2D;

			if (isBeingRidden() && getJawAngle() == 16)
				if (getEntityWorld().getTotalWorldTime() % 20 == 0)
					spawnEatingParticles();
			if (getPearlTimer() == 1)
				spawnSpittingParticles();
			if (getPearlTimer() >= 30)
				if (getEntityWorld().getTotalWorldTime() % 10 == 0)
					spawnMakingParticles();
		}

		if (!getEntityWorld().isRemote) {
			if (getPearlTimer() < 0) {
				if (getEntityWorld().getTotalWorldTime() % 5 == 0)
					checkAreaHere();

				if (getAttackTarget() != null) {
					if (!isBeingRidden() && getJawAngle() < 80) {
						setJawAngle(getJawAngle() + 8);
						if (getEatingHeight() > 0)
							setEatingHeight(0);
					}
					if (isBeingRidden() && getJawAngle() > 16)
						setJawAngle(getJawAngle() - 8);
				}

				if (getAttackTarget() == null) {
					if (!isBeingRidden()) {
						if (getJawAngle() > 0 && getTendrilCount() <= 0)
							setJawAngle(getJawAngle() - 8);
					}
				}

				if (isBeingRidden() && getJawAngle() == 16 && getPlacedByPlayer()) {
					if (getEntityWorld().getTotalWorldTime() % 20 == 0) {

						setEatingHeight(getEatingHeight() + 1);
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_EAT, SoundCategory.HOSTILE, 1F, 1F);
						getPassengers().get(0).attackEntityFrom(DamageSource.GENERIC, 0F);
						if (getEatingHeight() == 10 && getPassengers().get(0) != null) {
							setContainedXP(getContainedXP() + Math.round(getXPEaten((EntityLivingBase) getPassengers().get(0)) * 0.5F));
							getPassengers().get(0).setDead();
							if(getContainedXP() >= 10)
								setPearlTimer(PEARL_CREATION_TIME);
							setEatingHeight(0);
							setJawAngle(0);
						}
					}
				}

				if (isBeingRidden() && getJawAngle() == 16 && !getPlacedByPlayer())
					if (getEntityWorld().getTotalWorldTime() % 20 == 0) {
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_EAT, SoundCategory.HOSTILE, 1F, 1F);
						getPassengers().get(0).attackEntityFrom(DamageSource.causeMobDamage(this), (float) getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());
					}

			} else {
				if (getPearlTimer() >= 0) {
					setPearlTimer(getPearlTimer() - 1);
					if (getEntityWorld().getTotalWorldTime() % 20 == 0 && getPearlTimer() >= 30)
						getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_DIGEST, SoundCategory.HOSTILE, 1F, 0.8F + rand.nextFloat() * 0.5F);
				}

				if (getPearlTimer() == 0) {
					int quotient = getContainedXP() / 10;
				    int result = getContainedXP() - quotient * 10;
					setContainedXP(result);
					ItemStack pearl = new ItemStack(ItemRegistry.ROCK_SNOT_PEARL, quotient);
					EntityItem item = new EntityItem(world, posX, posY + 0.5D, posZ, pearl);
					item.motionX = item.motionZ = 0D;
					item.motionY = 0.4D;
					world.spawnEntity(item);
					getEntityWorld().playSound(null, getPosition(), SoundRegistry.ROCK_SNOT_SPIT, SoundCategory.HOSTILE, 1F, 1F);
				}
			}
		}
		super.onUpdate();
	}

public BlockPos groundBlock(boolean ignoreAir) {
        Block block = this.blockState.getBlock();
        BlockPos blockpos = this.blockPosition();
        BlockState blockstate = this.level.getBlockState(blockpos);
        boolean isConcrete = this.blockState.getBlock() instanceof ConcretePowderBlock;
        boolean isConcreteInWater = isConcrete && this.level.getFluidState(blockpos).is(FluidTags.WATER);
        this.setDeltaMovement(this.getDeltaMovement().multiply(0.7D, -0.5D, 0.7D));
        if (blockstate.is(Blocks.MOVING_PISTON))
            return null;
        if (this.cancelDrop) {
            this.discard();
            this.callOnBrokenAfterFall(block, blockpos);
            return null;
        }
        boolean canBeReplaced = blockstate.canBeReplaced(new DirectionalPlaceContext(this.level, blockpos, Direction.DOWN, ItemStack.EMPTY, Direction.UP));
        boolean isFreeBelow = FallingBlock.isFree(this.level.getBlockState(blockpos.below())) && (!isConcrete || !isConcreteInWater);
        boolean canSurvive = this.blockState.canSurvive(this.level, blockpos) && (!isFreeBelow || ignoreAir);
        if (canBeReplaced && canSurvive) {
            if (this.blockState.hasProperty(BlockStateProperties.WATERLOGGED) && this.level.getFluidState(blockpos).getType() == Fluids.WATER) {
                this.blockState = this.blockState.setValue(BlockStateProperties.WATERLOGGED, Boolean.TRUE);
            }

            if (this.level.setBlock(blockpos, this.blockState, 3)) {
                ((ServerLevel) this.level).getChunkSource().chunkMap.broadcast(this, new ClientboundBlockUpdatePacket(blockpos, this.level.getBlockState(blockpos)));
                this.discard();
                if (block instanceof Fallable fallable) {
                    fallable.onLand(this.level, blockpos, this.blockState, blockstate, new FallingBlockEntity(level, this.getX(), this.getY(), this.getZ(), this.blockState));
                } else if (context != null && resolver != null) {
                    RewindAttachment.get(context).addRewindEvent(level.getGameTime(), new EntityToBlockRewind(this, blockpos, this.blockState));
                    ShapersFocus.tryPropagateBlockSpell(new BlockHitResult(
                            new Vec3(blockpos.getX(), blockpos.getY(), blockpos.getZ()), Direction.DOWN, blockpos, false
                    ), level, getOwner(), context, resolver);
                }

                if (this.blockData != null && this.blockState.hasBlockEntity()) {
                    BlockEntity blockentity = this.level.getBlockEntity(blockpos);
                    if (blockentity != null) {

                        try {
                            blockentity.loadWithComponents(this.blockData, level.registryAccess());
                            if (blockentity instanceof SkullBlockEntity sk && this.blockData != null && this.blockData.contains("SkullOwner")) {
                                sk.setOwner(ANCodecs.decode(level.registryAccess(), ResolvableProfile.CODEC, this.blockData.getCompound("SkullOwner")));
                            }
                        } catch (Exception exception) {
                            exception.printStackTrace();
                        }

                        blockentity.setChanged();
                    }
                }
                if (this.level.getBlockEntity(blockpos) instanceof MageBlockTile mbt) {
                    if (context != null) {
                        mbt.color = context.getSpell().particleTimeline().get(ParticleTimelineRegistry.MAGEBLOCK_TIMELINE.get()).getColor();
                    }
                    mbt.setChanged();
                }

                return blockpos;
            } else if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                this.discard();
                this.callOnBrokenAfterFall(block, blockpos);
                ItemStack itemstack = new ItemStack(block);
                if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                    ResolvableProfile.CODEC
                            .parse(NbtOps.INSTANCE, blockData.get("profile"))
                            .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));
                }
                this.spawnAtLocation(itemstack);
                return null;
            }
        } else {
            this.discard();
            if (this.dropItem && this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                this.callOnBrokenAfterFall(block, blockpos);
                ItemStack itemstack = new ItemStack(block);
                if (this.blockData != null && this.getBlockState().is(Blocks.PLAYER_HEAD)) {
                    ResolvableProfile.CODEC
                            .parse(NbtOps.INSTANCE, blockData.get("profile"))
                            .resultOrPartial().ifPresent(profile -> itemstack.set(DataComponents.PROFILE, profile));

                }
                this.spawnAtLocation(itemstack);
            }
        }
        return null;
    }

@Override
    public void tick() {
        super.tick();
        if (level.isClientSide && !initMusic) {
            initMusic = true;
            ((Runnable) () -> ChimeraMusic.play(WildenChimera.this)).run();
        }

        // written like this allows for hotswap
        // this.goalSelector.getAvailableGoals().stream().filter(WrappedGoal::isRunning).map(WrappedGoal::getGoal).forEach(System.out::println);


        if (!level.isClientSide && isDefensive()) {
            this.getNavigation().stop();
        }
        if (level.isClientSide && isFlying() && random.nextInt(18) == 0) {

            this.level.playLocalSound(this.getX(), this.getY(), this.getZ(), SoundEvents.BAT_LOOP, this.getSoundSource(),
                    0.95F + this.random.nextFloat() * 0.05F,
                    0.3f + this.random.nextFloat() * 0.05F,
                    false);

        }

        if (!level.isClientSide && this.isInLava() && this.level.getGameTime() % 10 == 0) {
            this.addEffect(new MobEffectInstance(MobEffects.MOVEMENT_SPEED, 20, 4));
            this.addEffect(new MobEffectInstance(MobEffects.DAMAGE_RESISTANCE, 20, 3));
            this.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 20));
            this.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 20, 3));

        }

        if (this.isFlying()) {
            this.navigation.stop();
            flyingNavigator.tick();
        }

        if (!level.isClientSide) {
            // Reduce skill cooldown
            if (diveCooldown > 0) {
                diveCooldown--;
                if (this.isInLava() || this.isInWater())
                    diveCooldown -= 2;
            }
            if (summonCooldown > 0) summonCooldown--;
            if (spikeCooldown > 0) spikeCooldown--;
            if (ramCooldown > 0) ramCooldown--;

            if (getTarget() != null && this.invulnerableTime == 0 && !this.isDefensive() && !this.isFlying() && (this.onGround() || isInWater())) {
                var path = getNavigation().createPath(getTarget(), 1);
                if (path == null || !path.canReach() || getTarget().getY() - (this.getY() + 2) >= 3) {
                    rageTimer--;
                }
            }

        }

        if (!level.isClientSide && getPhaseSwapping() && !this.dead) {
            if (swapTicks < 60) {
                swapTicks++;
                this.navigation.stop();
            } else {
                this.removeAllEffects();
                this.setPhaseSwapping(false);
                for (LivingEntity e : level.getEntitiesOfClass(Player.class, new AABB(this.blockPosition()).inflate(5))) {
                    EntitySpellResolver resolver = new EntitySpellResolver(new SpellContext(level, new Spell().add(MethodTouch.INSTANCE)
                            .add(EffectLaunch.INSTANCE)
                            .add(AugmentAmplify.INSTANCE, 2)
                            .add(EffectDelay.INSTANCE)
                            .add(EffectKnockback.INSTANCE)
                            .add(AugmentAmplify.INSTANCE, 2)
                            , this, new LivingCaster(this)));
                    resolver.onCastOnEntity(ItemStack.EMPTY, e, InteractionHand.MAIN_HAND);
                }
                getRandomUpgrade();
                ParticleUtil.spawnPoof((ServerLevel) level, blockPosition().above());
                if (getPhase() == 1)
                    rageTimer = 200;
                swapTicks = 0;
            }
        }

        if (getPhaseSwapping() && level.isClientSide) {
            spawnPhaseParticles(blockPosition(), level, getPhase());
        }
    }

public void tick() {
        if (this.level.hasNeighborSignal(this.getBlockPos())) {
            this.miningTime = 0;
            return;
        }
        if (!this.level.isClientSide()) {
            ItemStack input = this.inputHandler.getStackInSlot(0);

            if (!this.cachedEnchantment) {
                this.setCachedEnchantment();
                this.cachedEnchantment = true;
            }

            // handle unusing enchantment from evilcraft, see
            // https://github.com/klikli-dev/occultism/issues/909
            if (input.isEnchanted() && input.getMaxDamage() - input.getDamageValue() < 6 &&
                    this.UNUSING != null && input.getEnchantmentLevel(this.UNUSING) > 0) {
                this.miningTime = 0;
                return;
            }

            if (this.miningTime > 0) {

                int efficiency = this.bonusEfficiency && input.isEnchanted() ? input.getEnchantmentLevel(this.EFFICIENCY) : 0;
                if (efficiency > 0) {
                    int extra1 = this.level.getRandom().nextIntBetweenInclusive(0, efficiency);
                    int extra2 = this.level.getRandom().nextIntBetweenInclusive(0, efficiency);
                    efficiency = Math.min(extra1, extra2);
                }

                this.miningTime -= 1 + efficiency;

                if (this.miningTime <= 0 && !this.level.isClientSide()) {
                    this.mine();
                }

                if (input.getItem() != this.currentInputType) {
                    this.miningTime = 0;
                    this.possibleResults = null;
                }

                // handled by delta check
            } else if (!input.isEmpty()) {

                this.currentInputType = input.getItem();

                forceInitStackNBT(input, (ServerLevel) this.level);
                this.maxMiningTime = getMaxMiningTime(input);
                this.rollsPerOperation = getRollsPerOperation(input);
                this.outputMultiplier = getOutputMultiplier(input);
                this.miningTime = this.maxMiningTime;
            }

            // Sync Logic
            boolean needsSync = this.maxMiningTime != this.lastSyncedMaxMiningTime;

            // Sync if max mining time changed (e.g. new item with different stats)

            // Sync if mining active state changes (0 <-> >0)
            boolean wasActive = this.lastSyncedMiningTime > 0;
            boolean isActive = this.miningTime > 0;
            if (wasActive != isActive) {
                needsSync = true;
            }

            // Syncs if progress drifts by 10
            if (Math.abs(this.miningTime - this.lastSyncedMiningTime) >= 10) {
                needsSync = true;
            }
            // Also sync if we just finished (already covered by 0 check above? sorta).

            if (needsSync) {
                this.markNetworkDirty();
            }

            if (this.outputDirty) {
                this.setChanged();
                this.outputDirty = false;
            }
        } else {
            if (this.miningTime > 0 && this.level.getGameTime() % 10 == 0) {
                this.level.addParticle(ParticleTypes.PORTAL, this.worldPosition.getX() + 0.5f,
                        this.worldPosition.getY() + 0.5, this.worldPosition.getZ() + 0.5f, 0.0D, 0.0D, 0.0D);
            }
        }
    }

private void onImpactEntity(EntityHitResult entityRayTrace) {
    Entity entityHit = entityRayTrace.getEntity();
    if (entityHit == null || !entityHit.isAlive()) {
      return;
    }
    Entity owner = getOwner();
    if (owner == entityHit) {
      //player catch it on return 
      dropAsItem();
      return;
    }
    switch (this.boomerangType) {
      case CARRY:
        if (!entityHit.level().isClientSide) {
          entityHit.startRiding(this);
        }
      break;
      case DAMAGE:
        if (entityHit instanceof LivingEntity) {
          LivingEntity live = (LivingEntity) entityHit;
          float damage = Mth.nextFloat(level().random, ConfigRegistry.BOOMERANG_DAMAGE_MIN.get().floatValue(), ConfigRegistry.BOOMERANG_DAMAGE_MAX.get().floatValue());
          boolean attackSucc = live.hurt(level().damageSources().thrown(this, owner), damage);
          if (attackSucc && live.isAlive() == false) {
            //           ("killed one");
          }
        }
      break;
      case STUN:
        //!entityHit.getUniqueID().equals(owner.getUniqueID()) 
        if (entityHit != owner && entityHit instanceof LivingEntity
            && !(entityHit instanceof Player)) {
          LivingEntity live = (LivingEntity) entityHit;
          if (!live.hasEffect(PotionEffectRegistry.STUN)) {
            live.addEffect(new MobEffectInstance(PotionEffectRegistry.STUN, ConfigRegistry.BOOMERANG_STUN_SECONDS.get() * Const.TICKS_PER_SEC, 1, false, true, true));
            SoundUtil.playSound(live, SoundEvents.IRON_GOLEM_ATTACK);
          }
        }
      break;
      default:
      break;
    }
  }

public void attackMobs(ItemStack pStack, LivingEntity pTarget, Player pPlayer){
        int enchantment = pStack.getEnchantmentLevel(ModEnchantments.SOUL_EATER.get());
        int soulEater = Mth.clamp(enchantment + 1, 1, 10);
        if (SEHelper.getSoulGiven(pTarget) > 0) {
            SEHelper.increaseSouls(pPlayer, ItemConfig.DarkScytheSouls.get() * soulEater);
        }

        float f = (float)pPlayer.getAttributeValue(Attributes.ATTACK_DAMAGE);
        float f1 = EnchantmentHelper.getDamageBonus(pPlayer.getMainHandItem(), pTarget.getMobType());
        float f2 = pPlayer.getAttackStrengthScale(0.5F);
        f = f * (0.2F + f2 * f2 * 0.8F);
        f1 = f1 * f2;
        f = f + f1;

        if (f > 0.5F || f1 > 0.5F) {
            float f3 = 1.0F + EnchantmentHelper.getSweepingDamageRatio(pPlayer) * f;
            int j = EnchantmentHelper.getFireAspect(pPlayer);
            double area = 1.0D;
            if (f2 > 0.9F) {
                area = 2.0D;
            }
            for (LivingEntity livingentity : pPlayer.level.getEntitiesOfClass(LivingEntity.class, pTarget.getBoundingBox().inflate(area, 0.25D, area))) {
                if (livingentity != pPlayer && livingentity != pTarget && !pPlayer.isAlliedTo(livingentity) && (!(livingentity instanceof ArmorStand) || !((ArmorStand) livingentity).isMarker()) && pPlayer.distanceToSqr(livingentity) < 16.0D && livingentity != pPlayer.getVehicle()) {
                    livingentity.knockback(0.4F, (double) Mth.sin(pPlayer.getYRot() * ((float) Math.PI / 180F)), (double) (-Mth.cos(pPlayer.getYRot() * ((float) Math.PI / 180F))));
                    if (livingentity.hurt(livingentity.damageSources().playerAttack(pPlayer), f3)) {
                        if (j > 0) {
                            livingentity.setSecondsOnFire(j * 4);
                        }
                        pStack.hurtAndBreak(1, pPlayer, (p_220045_0_) ->
                                p_220045_0_.broadcastBreakEvent(EquipmentSlot.MAINHAND));
                        boolean giveSoul = false;
                        if (livingentity instanceof OwnableEntity owned){
                            if (owned.getOwner() != pPlayer){
                                giveSoul = true;
                            }
                        } else {
                            giveSoul = true;
                        }
                        if (giveSoul) {
                            if (SEHelper.getSoulGiven(livingentity) > 0) {
                                SEHelper.increaseSouls(pPlayer, ItemConfig.DarkScytheSouls.get() * soulEater);
                            }
                        }
                        EnchantmentHelper.doPostHurtEffects(livingentity, pPlayer);
                        EnchantmentHelper.doPostDamageEffects(pPlayer, livingentity);
                    }
                }
            }
        }

        pPlayer.level.playSound((Player) null, pPlayer.getX(), pPlayer.getY(), pPlayer.getZ(), ModSounds.SCYTHE_SWING.get(), pPlayer.getSoundSource(), 1.0F, 1.0F);
        pPlayer.sweepAttack();
    }

@Override
	protected void onImpact(RayTraceResult rayTrace){

		if(!this.world.isRemote){

			Entity entityHit = rayTrace.entityHit;

			if(entityHit != null){
				// This is if the spark bomb gets a direct hit
				float damage = Spells.spark_bomb.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

				this.playSound(WizardrySounds.ENTITY_SPARK_BOMB_HIT, 1.0F, 1.2F / (this.rand.nextFloat() * 0.2F + 0.9F));

				entityHit.attackEntityFrom(
						MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.SHOCK).setProjectile(),
						damage);
			}

			double seekerRange = Spells.spark_bomb.getProperty(Spell.EFFECT_RADIUS).doubleValue() * blastMultiplier;

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(seekerRange, this.posX, this.posY,
					this.posZ, this.world);

			List<Integer> secondaryTargetIDs = new ArrayList<>();

			for(int i = 0; i < Math.min(targets.size(), Spells.spark_bomb.getProperty(SECONDARY_MAX_TARGETS).intValue()); i++){

				boolean flag = targets.get(i) != entityHit && targets.get(i) != this.getThrower()
						&& !(targets.get(i) instanceof EntityPlayer
								&& ((EntityPlayer)targets.get(i)).isCreative());

				if(flag){
					EntityLivingBase target = targets.get(i);

					target.playSound(WizardrySounds.ENTITY_SPARK_BOMB_CHAIN, 1.0F, rand.nextFloat() * 0.4F + 1.5F);

					target.attackEntityFrom(
							MagicDamage.causeIndirectMagicDamage(this, this.getThrower(), DamageType.SHOCK),
							Spells.spark_bomb.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier);

					secondaryTargetIDs.add(target.getEntityId());
				}
			}

			// Notify clients to play the explosion effect, including lightning arcs to secondary targets
			int[] idArray = secondaryTargetIDs.stream().mapToInt(Integer::intValue).toArray();
			WizardryPacketHandler.net.sendToAllAround(
					new PacketBombExplosion.Message(PacketBombExplosion.SPARK_BOMB, posX, posY + height / 2, posZ,
							blastMultiplier, idArray),
					new NetworkRegistry.TargetPoint(world.provider.getDimension(), posX, posY, posZ, 64));

			this.playSound(WizardrySounds.ENTITY_SPARK_BOMB_HIT_BLOCK, 0.5f, 0.5f);
		}

		this.setDead();
	}

@Override
    public boolean attackEntityFrom(DamageSource damageSource, float amount) {
        boolean canHarmInCreative = damageSource.canHarmInCreative();
        Entity attacker = damageSource.getTrueSource();

        if (!this.isCarcass()) {
            if (this.getHealth() - amount <= 0.0F) {
                if (!canHarmInCreative) {
                    this.playSound(this.getSoundForAnimation(EntityAnimation.DYING.get()), this.getSoundVolume(), this.getSoundPitch());
                    this.setHealth(this.getMaxHealth());
                    this.setCarcass(true);
                    return true;
                }

                if (attacker instanceof DinosaurEntity) {
                    this.getRelationship(attacker, true).onAttacked(amount);
                }

                return super.attackEntityFrom(damageSource, amount);
            } else {
                if (this.getAnimation() == EntityAnimation.RESTING.get() && !this.world.isRemote) {
                    this.setAnimation(EntityAnimation.IDLE.get());
                    this.isSittingNaturally = false;
                }

                if (!this.world.isRemote) {
                    if (!((float)this.hurtResistantTime > (float)this.maxHurtResistantTime / 2.0F))
                        this.setAnimation(EntityAnimation.INJURED.get());
                }

                if (this.shouldSleep()) {
                    this.disturbSleep();
                }

                if(attacker instanceof EntityLivingBase) {
                    this.respondToAttack((EntityLivingBase)attacker);
                }

                return super.attackEntityFrom(damageSource, amount);
            }
        } else if (!this.world.isRemote) {

            if(!(((float)this.hurtResistantTime > (float)this.maxHurtResistantTime / 2.0F))) {
                boolean carcassAllowed = RebornConfig.ENTITIES.allowCarcass;
                if(!carcassAllowed) {
                    this.dropMeat(attacker);
                    this.onDeath(damageSource);
                    this.setDead();
                }

                if (damageSource != DamageSource.DROWN) {
                    if (!this.dead && this.carcassHealth >= 0 && this.world.getGameRules().getBoolean("doMobLoot")) {
                        this.dropMeat(attacker);
                    }

                    if (this.carcassHealth <= 0) {
                        this.onDeath(damageSource);
                        this.setDead();
                    }

                    this.carcassHealth--;
                }

                if (canHarmInCreative) {
                    return super.attackEntityFrom(damageSource, amount);
                }

                if (this.hurtResistantTime <= this.maxHurtResistantTime / 2.0F) {
                    this.hurtTime = this.maxHurtTime = 10;
                }
            }
        }

        return false;
    }

@SubscribeEvent
    public static void AttackEvent(LivingAttackEvent event){
        LivingEntity victim = event.getEntity();
        Entity source = event.getSource().getEntity();
        Entity direct = event.getSource().getDirectEntity();
        if (!event.getEntity().level.isClientSide) {
            if (MiscCapHelper.getShields(victim) > 0
                    && !event.getSource().is(DamageTypeTags.BYPASSES_EFFECTS)
                    && !event.getSource().is(DamageTypeTags.BYPASSES_INVULNERABILITY)){
                if (MiscCapHelper.getShieldCool(victim) <= 0) {
                    MiscCapHelper.decreaseShields(victim);
                    if (SpellConfig.BulwarkShieldBreakExtra.get() > 0.0D) {
                        int extra = Mth.floor(event.getAmount() / SpellConfig.BulwarkShieldBreakExtra.get());
                        if (extra >= 1) {
                            for (int i = 0; i < extra; ++i) {
                                MiscCapHelper.decreaseShields(victim);
                            }
                        }
                    }
                    MiscCapHelper.setShieldCool(victim, 10);
                    if (event.getSource().getEntity() instanceof LivingEntity livingEntity){
                        MobUtil.knockBack(livingEntity, victim, 1.0D, 0.2D, 1.0D);
                    }
                }
                event.setCanceled(true);
            }
            if (MainConfig.GoodwillNoDamage.get()) {
                Player player = null;
                if (source instanceof Player player1) {
                    player = player1;
                } else if (MobUtil.getOwner(source) instanceof Player player1) {
                    player = player1;
                }
                if (player != null) {
                    if (SEHelper.isAlly(player, victim)) {
                        event.setCanceled(true);
                    }
                } else if (source instanceof IOwned owned) {
                    if (owned.isAllyWith(victim)) {
                        event.setCanceled(true);
                    }
                }
            }
            if (victim instanceof Witch witch) {
                double d0 = witch.getAttributeValue(Attributes.FOLLOW_RANGE);
                AABB axisalignedbb = AABB.unitCubeFromLowerCorner(witch.position()).inflate(d0, 10.0D, d0);
                List<Mob> list = witch.level.getEntitiesOfClass(Mob.class, axisalignedbb);

                for (Mob mob : list){
                    if (mob.getTarget() == null && witch.getLastHurtByMob() != null && !(witch.getLastHurtByMob() instanceof Raider) && !MobUtil.areAllies(witch.getLastHurtByMob(), witch)) {
                        if (mob instanceof Cultist && !mob.getType().is(Tags.EntityTypes.BOSSES) && EntitySelector.NO_CREATIVE_OR_SPECTATOR.test(witch.getLastHurtByMob())) {
                            mob.setTarget(witch.getLastHurtByMob());
                        }
                    }
                }
            }
        }

        if (event.getSource() instanceof NoKnockBackDamageSource){
            if (!victim.level.isClientSide) {
                CompoundTag tag = victim.getPersistentData();
                tag.putInt(NO_KNOCKBACK_TAG, victim.tickCount);
            }
        }

        if (source instanceof IOwned owned){
            if (owned.getMasterOwner() instanceof Player player) {
                victim.lastHurtByPlayer = player;
                victim.lastHurtByPlayerTime = 100;
            }
        }

        if (direct instanceof AbstractArrow arrowEntity){
            if (arrowEntity.getTags().contains(ConstantPaths.rainArrow()) || arrowEntity.getOwner() instanceof Apostle){
                if (arrowEntity.getOwner() != null) {
                    if (victim instanceof IOwned ownedEntity) {
                        if (ownedEntity.getTrueOwner() != null) {
                            if (ownedEntity.getTrueOwner() == arrowEntity.getOwner()) {
                                event.setCanceled(true);
                            }
                        }
                    }
                    if (victim == arrowEntity.getOwner()){
                        event.setCanceled(true);
                    }
                }
            }
            if (!(arrowEntity.getOwner() instanceof Apostle && victim.level.getDifficulty() == Difficulty.HARD)) {
                if (victim instanceof Player player) {
                    if (MobUtil.starAmuletActive(player)) {
                        event.setCanceled(true);
                    }
                }
            }
        }
    }

@Override
	public boolean cast(World world, EntityPlayer caster, EnumHand hand, int ticksInUse, SpellModifiers modifiers){

		WizardData data = WizardData.get(caster);

		Vec3d origin = caster.getPositionEyes(1);

		float extensionSpeed = getProperty(EXTENSION_SPEED).floatValue() * modifiers.get(SpellModifiers.POTENCY);

		RayTraceResult hit = data.getVariable(TARGET_KEY);

		// Initial targeting
		if(hit == null){
			hit = findTarget(world, caster, origin, caster.getLookVec(), modifiers);
			data.setVariable(TARGET_KEY, hit);
			caster.swingArm(hand);
			// This condition prevents the sound playing every tick after a missed shot has finished extending
			if(hit.typeOfHit != RayTraceResult.Type.MISS
					|| ticksInUse * extensionSpeed < getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade)){
				this.playSound(world, caster, ticksInUse, -1, modifiers, "shoot");
			}
		}

		Vec3d target = hit.hitVec;

		if(hit.entityHit instanceof EntityLivingBase){
			// If the target is an entity, we need to use the entity's centre rather than the original hit position
			// because the entity will have moved!
			target = GeometryUtils.getCentre(hit.entityHit);
		}

		double distance = origin.distanceTo(target);
		Vec3d direction = target.subtract(origin).normalize();

		double maxLength = getProperty(RANGE).floatValue() * modifiers.get(WizardryItems.range_upgrade) * STRETCH_LIMIT;

		// If the vine stretched too far
		if(distance > maxLength){
			if(world.isRemote && (ticksInUse-1) * extensionSpeed < distance){
				spawnLeafParticles(world, origin.subtract(0, SpellRay.Y_OFFSET, 0), direction, distance);
			}
			data.setVariable(TARGET_KEY, null);
			return false; // The spell is finished
		}

		boolean extending = ticksInUse * extensionSpeed < distance;

		if(extending){
			// Extension
			if(world.isRemote){
				// world.getTotalWorldTime() - ticksInUse generates a constant but unique seed each time the spell is cast
				ParticleBuilder.create(Type.VINE).entity(caster).pos(0, caster.getEyeHeight() - SpellRay.Y_OFFSET, 0)
						.target(origin.add(direction.scale(ticksInUse * extensionSpeed))).tvel(direction.scale(extensionSpeed))
						.seed(world.getTotalWorldTime() - ticksInUse).spawn(world);
			}

		}else{
			// Retraction
			Vec3d velocity = direction.scale(getProperty(REEL_SPEED).floatValue() * modifiers.get(SpellModifiers.POTENCY));

			int retractTime = ticksInUse - (int)(distance/extensionSpeed);

			switch(hit.typeOfHit){

				case BLOCK:
					// Payout
					if(caster.isSneaking() && ItemArtefact.isArtefactActive(caster, WizardryItems.charm_abseiling))
						velocity = new Vec3d(velocity.x, distance < maxLength-1 ? -PAYOUT_SPEED : distance-maxLength+1, velocity.z);

					// Reel the caster towards the block hit
					double ax = (velocity.x - caster.motionX) * REEL_ACCELERATION;
					double ay = (velocity.y - caster.motionY) * REEL_ACCELERATION;
					double az = (velocity.z - caster.motionZ) * REEL_ACCELERATION;
					caster.addVelocity(ax, ay, az);

					if(caster.motionY > 0 && !Wizardry.settings.replaceVanillaFallDamage) caster.fallDistance = 0; // Reset fall distance if the caster moves upwards

					if(world.isRemote){
						ParticleBuilder.create(Type.VINE).entity(caster).pos(0, caster.getEyeHeight() - SpellRay.Y_OFFSET, 0)
								.target(target).seed(world.getTotalWorldTime() - ticksInUse).spawn(world);
					}

					if(retractTime == 1){ // Just hit
						this.playSound(world, caster, ticksInUse, -1, modifiers,  "pull");
						this.playSound(world, hit.hitVec, ticksInUse, -1, modifiers,  "attach");
					}

					break;

				case ENTITY:
					// Payout
					if(caster.isSneaking() && ItemArtefact.isArtefactActive(caster, WizardryItems.charm_abseiling))
						velocity = new Vec3d(velocity.x, distance < maxLength-1 ? PAYOUT_SPEED : maxLength-1-distance, velocity.z);

					// Reel the entity hit towards the caster
					Entity entity = hit.entityHit;

					if(distance > MINIMUM_REEL_DISTANCE){
						double ax1 = (-velocity.x - entity.motionX) * REEL_ACCELERATION;
						double ay1 = (-velocity.y - entity.motionY) * REEL_ACCELERATION;
						double az1 = (-velocity.z - entity.motionZ) * REEL_ACCELERATION;
						entity.addVelocity(ax1, ay1, az1);
						// Player motion is handled on that player's client so needs packets
						if(entity instanceof EntityPlayerMP){
							((EntityPlayerMP)entity).connection.sendPacket(new SPacketEntityVelocity(entity));
						}
					}

					if(world.isRemote){
						ParticleBuilder.create(Type.VINE).entity(caster).pos(0, caster.getEyeHeight() - SpellRay.Y_OFFSET, 0)
								.target(entity).seed(world.getTotalWorldTime() - ticksInUse).spawn(world);
					}

					if(retractTime == 1){ // Just hit
						this.playSound(world, caster, ticksInUse, -1, modifiers,  "pull");
						this.playSound(world, entity.posX, entity.posY, entity.posZ, ticksInUse, -1, modifiers,  "attach");
					}

					break;

				default:
					// Missed
					if(world.isRemote && (ticksInUse-1) * extensionSpeed < distance){
						spawnLeafParticles(world, origin.subtract(0, SpellRay.Y_OFFSET, 0), direction, distance);
					}
					//caster.resetActiveHand();
					data.setVariable(TARGET_KEY, null);
					return false; // The spell is finished
			}
		}

		return true;
	}

public static boolean onDamageSourceBlocking(LivingEntity blocker, ItemStack useItem, DamageSource source,
												 CallbackInfoReturnable<Boolean> info) {
		if (blocker instanceof Player player && useItem != null) {
			boolean blocking = ((IProperShieldUser)blocker).isActuallyReallyBlocking();

			if (!blocking)
				return false;

			if (useItem.getItem() instanceof InfernalShield) {
				boolean piercingArrow = false;
				Entity entity = source.getDirectEntity();

				if (entity instanceof AbstractArrow arrow) {
					if (arrow.getPierceLevel() > 0) {
						piercingArrow = true;
					}
				}

				piercingArrow = false; // defend against Piercing... for now

				if (!source.is(DamageTypeTags.BYPASSES_SHIELD) && !piercingArrow) {
					Vec3 sourcePos = source.getSourcePosition();

					if (sourcePos != null) {
						Vec3 lookVec = blocker.getViewVector(1.0F);
						Vec3 sourceToSelf = sourcePos.vectorTo(blocker.position()).normalize();
						sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);

						if (sourceToSelf.dot(lookVec) < 0.0D) {
							int strength = -1;

							if (player.hasEffect(EnigmaticEffects.BLAZING_STRENGTH)) {
								MobEffectInstance effectInstance = player.getEffect(EnigmaticEffects.BLAZING_STRENGTH);
								strength = effectInstance.getAmplifier();
								player.removeEffect(EnigmaticEffects.BLAZING_STRENGTH);
								strength = strength > 2 ? 2 : strength;
							}

							player.addEffect(new MobEffectInstance(EnigmaticEffects.BLAZING_STRENGTH, 1200, strength + 1, true, true));

							if (source.getDirectEntity() instanceof LivingEntity living && living.isAlive()) {
								if (!living.fireImmune() && !(living instanceof Guardian)) {
									StackTraceElement[] stacktrace = Thread.currentThread().getStackTrace();

									// Ensure that we will not be caught in any sort of StackOverflow because of thorns-like effects
									if (Arrays.stream(stacktrace).filter(element -> {
										return SuperpositionHandler.class.getName().equals(element.getClassName());
									}).count() < 2) {
										living.invulnerableTime = 0;
										living.hurt(living.damageSources().source(DamageTypes.ON_FIRE, player), 4F);
										living.setSecondsOnFire(4);
										EnigmaticEventHandler.KNOCKBACK_THAT_BASTARD.remove(living);
									}
								}
							}

							return true;
						}
					}
				}
			} else if (useItem.getItem() instanceof EldritchPan) {
				Entity projectile = source.getDirectEntity();

				if (!(projectile instanceof Projectile))
					return false;

				if (!source.is(DamageTypeTags.BYPASSES_SHIELD)) {
					Vec3 sourcePos = source.getSourcePosition();

					if (sourcePos != null) {
						Vec3 lookVec = blocker.getViewVector(1.0F);
						Vec3 sourceToSelf = sourcePos.vectorTo(blocker.position()).normalize();
						sourceToSelf = new Vec3(sourceToSelf.x, 0.0D, sourceToSelf.z);

						if (sourceToSelf.dot(lookVec) < 0.0D) {
							projectile.kill();

							FoodData data = player.getFoodData();
							data.eat(4, 0.5F);

							player.level().playSound(null, player.getX(), player.getY(), player.getZ(),
									SoundEvents.PLAYER_BURP, SoundSource.PLAYERS, 0.5F,
									player.level().random.nextFloat() * 0.1F + 0.9F);

							player.gameEvent(GameEvent.EAT);

							if (projectile instanceof LargeFireball fireball) {
								fireball.explosionPower = 0;
							}

							if (player.level() instanceof ServerLevel level) {
								Vec3 angle = player.getLookAngle();
								angle.multiply(1, 0, 1).normalize().multiply(0.5, 0.5, 0.5);

								level.sendParticles(new ItemParticleOption(ParticleTypes.ITEM,
										new ItemStack(Items.FIRE_CHARGE)), player.getX() + angle.x,
										player.getY() + player.getEyeHeight() - 0.1, player.getZ() + angle.z,
										10, 0.3D, 0.3D, 0.3D, 0.03D);
							}

							return true;
						}
					}
				}
			}
		}

		return false;
	}

private boolean doCasting(World world, EntityLivingBase caster, SpellModifiers modifiers){

		if(world.canBlockSeeSky(new BlockPos(caster))){

			double maxRadius = getProperty(EFFECT_RADIUS).doubleValue();

			for(int i = 0; i < getProperty(LIGHTNING_BOLTS).intValue(); i++){

				double radius = maxRadius * CENTRE_RADIUS_FRACTION + world.rand.nextDouble() * maxRadius
						* (1 - CENTRE_RADIUS_FRACTION) * modifiers.get(WizardryItems.blast_upgrade);
				float angle = world.rand.nextFloat() * (float)Math.PI * 2;

				double x = caster.posX + radius * MathHelper.cos(angle);
				double z = caster.posZ + radius * MathHelper.sin(angle);
				Integer y = BlockUtils.getNearestFloor(world, new BlockPos(x, caster.posY, z), (int)maxRadius);

				if(y != null){

					if(!world.isRemote){
						EntityLightningBolt lightning = new EntityLightningBolt(world, x, y, z, false);
						lightning.getEntityData().setUniqueId(LightningBolt.SUMMONER_NBT_KEY, caster.getUniqueID());
						lightning.getEntityData().setFloat(LightningBolt.DAMAGE_MODIFIER_NBT_KEY, modifiers.get(SpellModifiers.POTENCY));
						world.addWeatherEffect(lightning);
					}

					// Secondary chaining effect
					List<EntityLivingBase> secondaryTargets = EntityUtils.getLivingWithinRadius(
							getProperty(SECONDARY_RANGE).doubleValue(), x, y + 1, z, world);

					for(int j = 0; j < Math.min(secondaryTargets.size(), getProperty(SECONDARY_MAX_TARGETS).intValue()); j++){

						EntityLivingBase secondaryTarget = secondaryTargets.get(j);

						if(AllyDesignationSystem.isValidTarget(caster, secondaryTarget)){

							if(world.isRemote){

								ParticleBuilder.create(Type.LIGHTNING).pos(x, y, z).target(secondaryTarget).spawn(world);

								ParticleBuilder.spawnShockParticles(world, secondaryTarget.posX,
										secondaryTarget.posY + secondaryTarget.height / 2,
										secondaryTarget.posZ);
							}

							playSound(world, secondaryTarget, 0, -1, modifiers);

							secondaryTarget.attackEntityFrom(MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
									getProperty(SECONDARY_DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));

							// Tertiary chaining effect

							List<EntityLivingBase> tertiaryTargets = EntityUtils.getLivingWithinRadius(
									getProperty(TERTIARY_RANGE).doubleValue(), secondaryTarget.posX,
									secondaryTarget.posY + secondaryTarget.height / 2, secondaryTarget.posZ, world);

							for(int k = 0; k < Math.min(tertiaryTargets.size(), getProperty(TERTIARY_MAX_TARGETS).intValue()); k++){

								EntityLivingBase tertiaryTarget = tertiaryTargets.get(k);

								if(!secondaryTargets.contains(tertiaryTarget)
										&& AllyDesignationSystem.isValidTarget(caster, tertiaryTarget)){

									if(world.isRemote){
										ParticleBuilder.create(Type.LIGHTNING).entity(secondaryTarget)
												.pos(0, secondaryTarget.height / 2, 0).target(tertiaryTarget).spawn(world);
										ParticleBuilder.spawnShockParticles(world, tertiaryTarget.posX,
												tertiaryTarget.posY + tertiaryTarget.height / 2,
												tertiaryTarget.posZ);
									}

									playSound(world, tertiaryTarget, 0, -1, modifiers);

									tertiaryTarget.attackEntityFrom(
											MagicDamage.causeDirectMagicDamage(caster, DamageType.SHOCK),
											getProperty(TERTIARY_DAMAGE).floatValue() * modifiers.get(SpellModifiers.POTENCY));
								}
							}
						}
					}
				}
			}

			return true;
		}

		return false;
	}

