				player.getGameProfile().getName(), player.level().dimension(), player.getX(), player.getY(), player.getZ());
	}

public boolean tick() {
			// If empty, this swapper is done.
			if (candidateQueue.isEmpty()) {
				return false;
			}

			int remainingSwaps = BLOCK_SWAP_RATE;
			while (remainingSwaps > 0 && !candidateQueue.isEmpty()) {
				SwapCandidate cand = candidateQueue.poll();

				// If we've already completed this location, move along, as this
				// is just a suboptimal one.
				if (completedCoords.contains(cand.coordinates)) {
					continue;
				}

				// If this candidate is out of range, discard it.
				if (cand.range <= 0) {
					continue;
				}

				// Otherwise, perform the break and then look at the adjacent tiles.
				ToolCommons.removeBlockWithDrops(player, truncator, world,
						cand.coordinates,
						state -> state.is(BlockTags.MINEABLE_WITH_AXE) || state.is(BlockTags.LEAVES));

				remainingSwaps--;

				completedCoords.add(cand.coordinates);

				// Then, go through all of the adjacent blocks and look if
				// any of them are any good.
				for (BlockPos adj : adjacent(cand.coordinates)) {
					var state = world.getBlockState(adj);

					boolean isWood = state.is(BlockTags.LOGS);
					boolean isLeaf = state.is(BlockTags.LEAVES);
					// TODO: Make "blocks the axe will propagate through" a tag
					boolean shouldPropagateThrough = isWood || isLeaf
							|| state.is(Blocks.MANGROVE_ROOTS);

					if (!shouldPropagateThrough) {
						continue;
					}

					// If this is a leaf, it gets
					// the minimum of the leaf range and the current range - 1.
					// Otherwise, it gets the standard range - 1.
					int newRange = isLeaf ? Math.min(LEAF_BLOCK_RANGE, cand.range - 1) : cand.range - 1;

					candidateQueue.offer(new SwapCandidate(adj, newRange));
				}
			}

			// If we did any iteration, then hang around until next tick.
			return true;
		}

@SubscribeEvent
        public static void onLivingDamageModifiers(LivingDamageEvent.Pre event) {
            var target = event.getEntity();
            var source = event.getSource().getEntity();

            if (!target.level().isClientSide() && target.getPersistentData().getLong(FOG_SUFFOCATION_UNTIL_TAG) >= target.level().getGameTime()
                    && event.getSource().is(DamageTypes.IN_WALL)) {
                var modifier = target.getPersistentData().getFloat(FOG_SUFFOCATION_DAMAGE_TAG);

                event.setNewDamage((float) (event.getNewDamage() * (1D + modifier)));
            }

            if (!target.level().isClientSide()) {
                var targetId = target.getStringUUID();

                for (var player : target.level().players()) {
                    for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                        var relic = (GhostlyMantleItem) stack.getItem();
                        var marks = relic.getReprisalMarks(stack);
                        var modifier = marks.remove(targetId);

                        if (modifier == null)
                            continue;

                        var original = event.getNewDamage();
                        var modified = original * (1D + modifier);
                        var extra = modified - original;

                        event.setNewDamage((float) modified);
                        relic.setReprisalMarks(stack, marks);

                        var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("spectral_escape");

                        ability.getStatisticData().getMetricData("reprisal_damage").addValue(extra);

                        if (extra > 0D) {
                            var experience = player.getRandom().nextInt((int) (extra + 1D));

                            if (experience > 0)
                                relic.getRelicData(player, stack).getLevelingData().addExperience("spectral_escape", "reprisal_damage", experience);
                        }

                        return;
                    }
                }
            }

            if (!(target instanceof Player player) || !(source instanceof LivingEntity attacker) || source == target)
                return;

            for (var stack : EntityUtils.findEquippedCurios(player, RelicsItems.GHOSTLY_MANTLE.get())) {
                var relic = (GhostlyMantleItem) stack.getItem();
                var ability = relic.getRelicData(player, stack).getAbilitiesData().getAbilityData("gaze");

                if (!ability.canPlayerUse(player))
                    continue;

                var data = relic.getGazeCharges(stack).get(attacker.getStringUUID());

                if (data == null || data.charges() <= 0)
                    continue;

                var original = event.getNewDamage();
                var reduction = data.charges() * ability.getStatData("weakness").getValue();

                event.setNewDamage((float) Math.max(0D, original * (1D - reduction)));
                ability.getStatisticData().getMetricData("damage_reduced").addValue(original - event.getNewDamage());

                return;
            }
        }

@Override
    public void onUpdate() {
    	super.onUpdate();
    	renderYawOffset = rotationYaw;
		double a = Math.toRadians(rotationYaw);
		double offSetX = -Math.sin(a) * 1.5D;
		double offSetZ = Math.cos(a) * 1.5D;
		tailPart[0].setLocationAndAngles(posX - offSetX, posY, posZ - offSetZ, 0.0F, 0.0F);

		if (getEntityWorld().getTotalWorldTime()%5 == 0)
			if (getEntityWorld().isRemote)
				flameParticles(getEntityWorld(), tailPart[0].posX, tailPart[0].posY + 0.25, tailPart[0].posZ, rand);

		checkCollision();

		if (getEntityWorld().isRemote) {
			if (getIsCastingSpell()) {
				prevAnimationTicks = animationTicks;

				if (animationTicks <= 1F)
					animationTicks += 0.1F;

			}
			if (!getIsCastingSpell()) {
				prevAnimationTicks = animationTicks;

				if (animationTicks >= 0.1F)
					animationTicks -= 0.1F;

				if (animationTicks < 0F)
					animationTicks = 0F;
			}
		}
		if (!getEntityWorld().isRemote && recentlyHit > 40)
			if(getIsCastingSpell())
				setIsCastingSpell(false);

		if (getEntityWorld().isRemote) {
			if(rand.nextInt(4) == 0) {
				ParticleArgs<?> args = ParticleArgs.get().withDataBuilder().setData(2, this).buildData();
					args.withColor(1F, 1F, 1F, 1F);
					args.withScale(0.75F + rand.nextFloat() * 0.75F);
				BLParticles.EMBER_SWIRL.spawn(getEntityWorld(), posX, posY, posZ, args);
			}
		}
    }

@SubscribeEvent(priority = EventPriority.HIGHEST)
	public void playerTick(TickEvent.PlayerTickEvent event) {
		//Leaving the underowrld
		if (event.player.getEntityWorld().provider.getDimension() == Wizardry.underWorld.getId()) {
			if (event.player.posY < 0) {
				//Gets the players spwanpoint and sets the location to teleport to around that
				event.player.isDead = false;
				BlockPos spawn = event.player.isSpawnForced(0) ? event.player.getBedLocation(0) : event.player.world.getSpawnPoint().add(event.player.world.rand.nextGaussian() * 16, 0, event.player.world.rand.nextGaussian() * 16);
				BlockPos teleportTo = spawn.add(0, 300 - spawn.getY(), 0);
				//stops fall damage
				fallResetter.add(event.player.getUniqueID());
				TeleportUtil.teleportToDimension(event.player, 0, teleportTo.getX(), teleportTo.getY(), teleportTo.getZ());
			}
		}
		//adds pass to check if player on bedrock after reached velocity
		if (event.player.getEntityWorld().provider.getDimension() == 0 && ConfigValues.underworldFallSpeed <= 0) {
			if (event.player.motionY < ConfigValues.underworldFallSpeed || passmap.get(event.player.getEntityId()) != null) {
				passmap.put(event.player.getEntityId(), true);
				BlockPos location = event.player.getPosition();
				BlockPos bedrock = PosUtils.checkNeighborBlocksThoroughly(event.player.getEntityWorld(), location, Blocks.BEDROCK);
				if (bedrock != null) {
					event.player.isDead = false;
					fallResetter.add(event.player.getUniqueID());
					TeleportUtil.teleportToDimension(event.player, Wizardry.underWorld.getId(), 0, 300, 0);
					passmap.remove(event.player.getEntityId());
				} else if (event.player.motionY > ConfigValues.underworldFallSpeed) {//resets pass if stopped falling or slowed down alot
					passmap.remove(event.player.getEntityId());
				}
			}
		}

		if (!event.player.world.isRemote) {
			for (ItemStack stack : event.player.inventory.mainInventory) {
				if (stack.getItem() == ModItems.LEVITATION_ORB) {

					if (stack.getItemDamage() + 1 > stack.getMaxDamage()) {
						stack.shrink(1);
						continue;
					}

					if (event.player.world.getTotalWorldTime() % 10 == 0)
						stack.setItemDamage(stack.getItemDamage() + 1);

					if (!event.player.isPotionActive(ModPotions.LOW_GRAVITY)) {
						event.player.addPotionEffect(new PotionEffect(ModPotions.LOW_GRAVITY, 3, 3, false, false));
					}
					break;
				}
			}
		}
	}

public void use(int hammerLevel, float hammerEfficiency, float angle) {
        ServerLevel serverLevel = (ServerLevel) getLevel();
        int count = 4 + (int) hammerEfficiency / 4;
        double cone = (20 + hammerLevel * 6) * Math.PI / 180;
        int ox = SectionPos.blockToSectionCoord(getBlockPos().getX());
        int oz = SectionPos.blockToSectionCoord(getBlockPos().getZ());

        int preResultSize = scanResults.size();
        AtomicInteger stagger = new AtomicInteger();

        ChunkPos.rangeClosed(new ChunkPos(-32, -32), new ChunkPos(32, 32))
                .filter(pos -> Math.abs(Mth.atan2(pos.x, pos.z) - angle) < cone)
                .sorted(Comparator.comparingInt(pos -> pos.x * pos.x + pos.z * pos.z))
                .map(pos -> new ChunkPos(pos.x + ox, pos.z + oz))
                .filter(pos -> Math.abs(pos.x - ox) + Math.abs(pos.z - oz) < 20)
                .filter(pos -> scanResults.stream().noneMatch(result -> result.chunkX == pos.x && result.chunkZ == pos.z))
                .limit(count)
                .forEach(pos -> {
//                    boolean wasLoaded = serverLevel.hasChunk(pos.x, pos.z);
//                    System.out.println("has chunk [" + pos.x + ", " + pos.z + "]: " + wasLoaded);
//                    serverLevel.getChunkSource().getGenerator().findNearestMapStructure()
                    long timestamp = this.getTimestamp(serverLevel.getGameTime(), pos.x - ox, pos.z - oz) + stagger.getAndIncrement() * 3L;
                    int height = serverLevel.getChunk(pos.x, pos.z, ChunkStatus.SURFACE).getHeight(Heightmap.Types.WORLD_SURFACE_WG, pos.x, pos.z);

                    BlockPos centerPos = pos.getMiddleBlockPosition(height);
                    float temperature = level.getBiome(centerPos).value().getTemperature(centerPos);
                    List<String> structures =
                            Arrays.stream(getScannableStructures())
                                    .filter(id -> ScanHelper.hasStructure(id, serverLevel, pos)).toList();
                    scanResults.add(new ScanResult(pos.x, pos.z, height, temperature, structures, timestamp));


//                    if (!wasLoaded) {
//                        System.out.println("[post]  Was not loaded, is now: " + serverLevel.hasChunk(pos.x, pos.z));
//                        ServerScheduler.schedule(100, () -> System.out.println("[delayed] Was not loaded, is now: " + serverLevel.hasChunk(pos.x, pos.z)));
//                    }


                    ServerScheduler.schedule((int) ((timestamp - serverLevel.getGameTime())), () ->
                            serverLevel.playSound(null, getBlockPos(), TetraSounds.scanMiss, SoundSource.PLAYERS, 0.01f, 1.0f + (float) Math.random() * 0f));
                    if (!structures.isEmpty()) {
                        ServerScheduler.schedule((int) ((timestamp - serverLevel.getGameTime()) + 20), () ->
                                serverLevel.playSound(null, getBlockPos(), TetraSounds.scanHit, SoundSource.PLAYERS, 0.1f, 1.0f));
                    }

                });

        if (preResultSize != scanResults.size()) {
            setChanged();
            level.sendBlockUpdated(worldPosition, getBlockState(), getBlockState(), 3);
        }
    }

@Override
    protected void tick() {
        Level world = getWorld();
        int radius = 3;
        if (world.isClientSide) {
            BlockPos pos = getPos();
            ParticleUtil.spawnRitualAreaEffect(getPos(), getWorld(), rand, getCenterColor(), radius);
        }
        if (!getWorld().isClientSide && world.getGameTime() % 60 == 0) {
            boolean didWorkOnce = false;
            Level level = getWorld();
            BlockPos pos = getPos();
            //Get nearby source jars
            for (BlockPos blockPos : BlockPos.betweenClosed(pos.offset(-radius, -radius, -radius), pos.offset(radius, radius, radius))) {
                if (level.getBlockState(blockPos).getBlock() instanceof MobJar) {
                    MobJarTile tile = (MobJarTile) level.getBlockEntity(blockPos);
                    if (tile == null || tile.getEntity() != null) {
                        continue;
                    }
                    for (Entity e : level.getEntities((Entity) null, new AABB(tile.getBlockPos()).inflate(5), this::canJar)) {
                        for (var passenger : e.getPassengers()) {
                            passenger.stopRiding();
                        }
                        if (e instanceof Mob mob && ((Mob) e).isLeashed() && e.shouldBeSaved()) {
                            if (mob.isLeashed()) {
                                mob.dropLeash(true, true);
                            }
                        }
                        if (e instanceof Raider raider && raider.hasActiveRaid()) {
                            raider.getCurrentRaid().removeFromRaid(raider, false);
                        }
                        if (e instanceof Villager villager) {
                            villager.releasePoi(MemoryModuleType.HOME);
                            villager.releasePoi(MemoryModuleType.JOB_SITE);
                            villager.releasePoi(MemoryModuleType.POTENTIAL_JOB_SITE);
                            villager.releasePoi(MemoryModuleType.MEETING_POINT);
                        }
                        if (tile.setEntityData(e)) {
                            e.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);
                            EntityFlyingItem followProjectile = new EntityFlyingItem(level, e.position, Vec3.atCenterOf(tile.getBlockPos()), 100, 50, 100);
                            level.addFreshEntity(followProjectile);
                            ParticleUtil.spawnPoof((ServerLevel) level, e.getOnPos().above());
                            didWorkOnce = true;
                            if (e instanceof Starbuncle starbuncle) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.SHRUNK_STARBY.get(), (ServerLevel) level, starbuncle.blockPosition(), 10);
                            }
                            if (e instanceof LightningBolt bolt) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.CAUGHT_LIGHTNING.get(), (ServerLevel) level, bolt.blockPosition(), 10);
                            }
                            if (e instanceof ItemEntity item && item.getItem().getItem() == Items.CLOCK) {
                                ANCriteriaTriggers.rewardNearbyPlayers(ANCriteriaTriggers.TIME_IN_BOTTLE.get(), (ServerLevel) level, item.blockPosition(), 10);
                            }
                            break;
                        }
                    }
                }
            }
            if (didWorkOnce) {
                this.setNeedsSource(true);
            }
        }
    }

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		State state = context.getState();
		IMultiblockLevel level = context.getLevel();
		final Level rawLevel = context.getLevel().getRawLevel();
		if(rawLevel instanceof ServerLevel serverLevel)
		{
			BlockPos broadcastPos = level.toAbsolute(BROADCAST_POS);
			// update the maximum range if it's undefined or every ~ 7 minutes
			if(state.rangeInChunks < 0||serverLevel.getGameTime()%8192==((broadcastPos.getX()^broadcastPos.getZ())&8191))
			{
				int maxRange = calculateMaxRange(serverLevel, broadcastPos, 4);
				state.rangeInChunks = maxRange;
			}

			// fetch the wireless handler for this world
			WirelessRedstoneHandler handler = WirelessRedstoneHandler.getHandler(serverLevel);

			// consume energy and set active state
			int consumed = IEServerConfig.MACHINES.radio_tower_consumption.get();
			int extracted = state.energy.extractEnergy(consumed, false);
			final boolean prevActive = state.active;
			state.active = extracted >= consumed;
			// if active state changed, notify the network
			if(state.active!=prevActive)
				state.markSendAndReceiveDirty();

			// register with handler if not yet done
			if(!handler.isRegistered(broadcastPos, context.getState()))
				handler.register(broadcastPos, context.getState());

			// if the sending signal has changed, notify other components
			if(state.sendingDirty)
			{
				handler.notifyComponents(broadcastPos, state);
				state.sendingDirty = false;
			}
			// if the network has changed, fetch new signal
			if(state.receivingDirty)
			{
				state.receivedSignals = state.isActive()?handler.fetchSignals(broadcastPos, state): new byte[16];
				state.bundleConnection.markDirty();
				state.receivingDirty = false;
			}
		}
	}

@Override
    public void tick() {
        if (te.isRemoved() || !hacker.isAlive()) {
            // TODO maybe find a way to catch up with hackers who disconnect just to avoid getting zapped?
            return;
        }

        boolean wasDone = isSimulationDone();

        if (!(hacker.containerMenu instanceof SecurityStationHackingMenu) && !playerSimulation.isHackComplete()) {
            // hacker closed their window before hack complete: AI wins
            for (int slot = 0; slot < HackSimulation.GRID_SIZE; slot++) {
                HackSimulation.Node node = aiSimulation.getNodeAt(slot);
                if (node != null && node.getType() == NetworkComponentType.NETWORK_IO_PORT) {
                    node.setHackProgress(slot, 1F, true);
                    break;
                }
            }
        } else if (!wasDone) {
            playerSimulation.tick();
            aiSimulation.tick();
        }

        boolean syncToClient = (te.nonNullLevel().getGameTime() & 0x7) == 0;
        if (!wasDone && aiSimulation.isHackComplete()) {
            // security station wins
            syncToClient = true;
            if (aiSimulation.isAwake()) {
                // if hack window is closed before AI detects intrustion, hacker gets away with it
                if (te.nonNullLevel().isClientSide) {
                    hacker.playSound(SoundEvents.ENDERMAN_DEATH, 1f, 1f);
                } else {
                    hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackFailed.1").withStyle(ChatFormatting.RED), false);
                    if (!justTesting) {
                        hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackFailed.2").withStyle(ChatFormatting.RED), false);
                        te.retaliate(hacker);
                    }
                }
            }
        } else if (!wasDone && playerSimulation.isHackComplete()) {
            // hacker wins
            syncToClient = true;
            if (te.nonNullLevel().isClientSide) {
                hacker.playSound(SoundEvents.PLAYER_LEVELUP, 1f, 1f);
            } else {
                hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackSucceeded.1").withStyle(ChatFormatting.GREEN), false);
                if (!justTesting) {
                    hacker.displayClientMessage(xlate("pneumaticcraft.message.securityStation.hackSucceeded.2").withStyle(ChatFormatting.GREEN), false);
                    te.addHacker(hacker.getGameProfile());
                }
            }
        }
        if (!te.nonNullLevel().isClientSide() && syncToClient) {
            NetworkHandler.sendToPlayer(PacketSyncHackSimulationUpdate.forSecurityStation(te), (ServerPlayer) hacker);
        }
    }

