            if (remove()) {
                ApugliPowers.MODIFY_ENCHANTMENT_LEVEL.get().onRemoved(power, living);
            } else {
                ApugliPowers.MODIFY_ENCHANTMENT_LEVEL.get().onAdded(power, living);
            }
        }
    });
}

