public void trackDrink(Holder<Potion> potion, ServerPlayer player) {
		//reset advancement window if potion changed. Otherwise, continue incrementing the doses
		if (this.lastUsedPotion == null || !Objects.equals(this.lastUsedPotion, potion)) {
			this.dosesDrank = 1;
			this.lastTimeStarted = player.level().getGameTime();
		} else {
			this.dosesDrank++;
		}
		this.lastUsedPotion = potion;

		if (player.isAlive()) {
			TFAdvancements.DRINK_FROM_FLASK.get().trigger(player, this.dosesDrank, Mth.floor((float) (player.level().getGameTime() - this.lastTimeStarted) / 20L), this.lastUsedPotion);
		}
	}

public static void travellersGearAutoRepair(LivingEntity livingEntity) {
		long lastHitTime = livingEntity.getData(TFDataAttachments.LAST_DAMAGE_ARMOR_TIME);
		if (livingEntity.level().getGameTime() - lastHitTime <= 10 * 20)  // 10 seconds
			return;

		for (EquipmentSlot slot : EquipmentSlotGroup.ARMOR.slots()) {
			ItemStack stack = livingEntity.getItemBySlot(slot);

			Float probability = stack.get(TFDataComponents.AUTO_REPAIR_PROBABILITY);
			if (probability == null || !TravellersModifiersManager.isModifierActive(livingEntity, stack, TravellersModifiersManager.AUTO_REPAIR_MODIFIER))
				continue;
			Level level = livingEntity.level();
			double boostedProbability = getAutoRepairChance(probability, level, livingEntity.blockPosition());

			if (boostedProbability > level.getRandom().nextFloat())
				stack.setDamageValue(Math.max(stack.getDamageValue() - 1, 0));

		}
	}

@Override
	public void onUpdate(ItemStack stack, World world, Entity entity, int slot, boolean isHeldInMainhand){
		boolean isHeld = isHeldInMainhand || entity instanceof EntityLivingBase && ItemStack.areItemStacksEqual(stack, ((EntityLivingBase) entity).getHeldItemOffhand());

		// If Wizardry.settings.wandsMustBeHeldToDecrementCooldown is false, the cooldowns will be decremented.
		// If Wizardry.settings.wandsMustBeHeldToDecrementCooldown is true and isHeld is true, the cooldowns will also be decremented.
		// If Wizardry.settings.wandsMustBeHeldToDecrementCooldown is true and isHeld is false, the cooldowns will not be decremented.
		if (!Wizardry.settings.wandsMustBeHeldToDecrementCooldown || isHeld) {
			WandHelper.decrementCooldowns(stack);
		}

		// Decrements wand damage (increases mana) every 1.5 seconds if it has a condenser upgrade
		if(!world.isRemote && !this.isManaFull(stack) && world.getTotalWorldTime() % Constants.CONDENSER_TICK_INTERVAL == 0){
			// If the upgrade level is 0, this does nothing anyway.
			int baseAmount = WandHelper.getUpgradeLevel(stack, WizardryItems.condenser_upgrade);
			int amount = (int)(baseAmount * Wizardry.settings.condenserAmountMultiplier);
			this.rechargeMana(stack, amount);
		}
	}

@Override
