        if (pEntity.level().isClientSide) return;

        ChargeMode mode = getChargeMode(pStack);
        if (pEntity instanceof Player player && mode != ChargeMode.NONE && pLevel.getGameTime() % PneumaticValues.ARMOR_CHARGER_INTERVAL == 15) {
