@Override
    protected void explode() {
        this.level().playSound(null, this.getX(), this.getY(), this.getZ(), SoundEvents.GENERIC_EXPLODE.value(),
                SoundSource.BLOCKS, 4.0F,
                (1.0F + (this.level().getRandom().nextFloat() - this.level().getRandom().nextFloat()) * 0.2F) * 32.9F);

        if (this.isInWater()) {
            return;
        }

        // TODO 1.21.4: Can likely be rewritten to use the explosion calculator
        var damageSource = Explosion.getDefaultDamageSource(this.level(), this);
        var ex = new ServerExplosion(
                (ServerLevel) this.level(),
                this,
                damageSource,
                new ExplosionDamageCalculator(),
                new Vec3(this.getX(), this.getY(), this.getZ()),
                0.2f,
                false,
                AEConfig.instance().isTinyTntBlockDamageEnabled() ? BlockInteraction.DESTROY_WITH_DECAY
                        : BlockInteraction.KEEP);
        final AABB area = new AABB(this.getX() - 1.5, this.getY() - 1.5f, this.getZ() - 1.5,
                this.getX() + 1.5, this.getY() + 1.5, this.getZ() + 1.5);
        final List<Entity> list = this.level().getEntities(this, area);

        for (Entity e : list) {
            e.hurt(level().damageSources().explosion(ex), 6);
        }

        var pos = new ArrayList<BlockPos>();
        if (AEConfig.instance().isTinyTntBlockDamageEnabled()) {
            this.setPos(this.getX(), this.getY() - 0.25, this.getZ());

            for (int x = (int) (this.getX() - 2); x <= this.getX() + 2; x++) {
                for (int y = (int) (this.getY() - 2); y <= this.getY() + 2; y++) {
                    for (int z = (int) (this.getZ() - 2); z <= this.getZ() + 2; z++) {
                        final BlockPos point = new BlockPos(x, y, z);
                        final BlockState state = this.level().getBlockState(point);
                        final Block block = state.getBlock();

                        if (!state.isAir()) {
                            float strength = (float) (2.3f
                                    - ((x + 0.5f - this.getX()) * (x + 0.5f - this.getX())
                                            + (y + 0.5f - this.getY()) * (y + 0.5f - this.getY())
                                            + (z + 0.5f - this.getZ()) * (z + 0.5f - this.getZ())));

                            final float fluidResistance = !state.getFluidState().isEmpty()
                                    ? state.getFluidState().getExplosionResistance()
                                    : 0f;
                            final float resistance = Math
                                    .max(block.getExplosionResistance(state, this.level(), point, ex), fluidResistance);
                            strength -= (resistance + 0.3F) * 0.11f;

                            if (strength > 0.01 && !state.isAir()) {
                                level().setBlock(point, Blocks.AIR.defaultBlockState(), 3);
                                state.onExplosionHit((ServerLevel) this.level(), point, ex, (stack, dropPoint) -> {
                                    Block.popResource(this.level(), dropPoint, stack);
                                });
                                pos.add(point);
                            }
                        }
                    }
                }
            }
        }
        EventHooks.onExplosionDetonate(this.level(), ex, list, pos);

        AppEng.instance().sendToAllNearExcept(null, this.getX(), this.getY(), this.getZ(), 64, this.level(),
                new MockExplosionPacket(this.getX(), this.getY(), this.getZ()));
    }

@Override
	public void onUpdate(){

		super.onUpdate();

//		if(this.ticksExisted % 20 == 1 && !this.onGround && world.isRemote){
//			// Though this sound does repeat, it stops when it hits the ground.
//			Wizardry.proxy.playMovingSound(this, WizardrySounds.ENTITY_HAMMER_FALLING, WizardrySounds.SPELLS, 3.0f, 1.0f, false);
//		}

		if(this.world.isRemote && this.ticksExisted % 3 == 0){
			ParticleBuilder.create(Type.SPARK)
					.pos(this.posX - 0.5d + rand.nextDouble(), this.posY + 2 * rand.nextDouble(), this.posZ - 0.5d + rand.nextDouble())
					.spawn(world);
		}

		this.prevPosX = this.posX;
		this.prevPosY = this.posY;
		this.prevPosZ = this.posZ;
		++this.fallTime;
		this.motionY -= 0.03999999910593033D;
		this.move(MoverType.SELF, this.motionX, this.motionY, this.motionZ);
		this.motionX *= 0.9800000190734863D;
		this.motionY *= 0.9800000190734863D;
		this.motionZ *= 0.9800000190734863D;

		if(this.onGround){

			this.motionX *= 0.699999988079071D;
			this.motionZ *= 0.699999988079071D;
			this.motionY *= -0.5D;

			this.rotationPitch = 0;
			this.spin = false;

			double seekerRange = Spells.lightning_hammer.getProperty(Spell.EFFECT_RADIUS).doubleValue();

			List<EntityLivingBase> targets = EntityUtils.getLivingWithinRadius(seekerRange, this.posX,
					this.posY + 1, this.posZ, world);

			int maxTargets = Spells.lightning_hammer.getProperty(LightningHammer.SECONDARY_MAX_TARGETS).intValue();
			while(targets.size() > maxTargets) targets.remove(targets.size() - 1);

			for(EntityLivingBase target : targets){

				if(EntityUtils.isLiving(target) && this.isValidTarget(target)
						&& target.ticksExisted % Spells.lightning_hammer.getProperty(LightningHammer.ATTACK_INTERVAL).floatValue() == 0){

					if(world.isRemote){

						ParticleBuilder.create(Type.LIGHTNING).pos(posX, posY + height - 0.1, posZ) .target(target).spawn(world);

						ParticleBuilder.spawnShockParticles(world, target.posX,
								target.posY + target.height, target.posZ);
					}

					target.playSound(WizardrySounds.ENTITY_HAMMER_ATTACK, 1.0F, rand.nextFloat() * 0.4F + 1.5F);

					float damage = Spells.lightning_hammer.getProperty(Spell.SPLASH_DAMAGE).floatValue() * damageMultiplier;

					if(this.getCaster() != null){
						EntityUtils.attackEntityWithoutKnockback(target, MagicDamage.causeIndirectMagicDamage(
								this, getCaster(), DamageType.SHOCK), damage);
						EntityUtils.applyStandardKnockback(this, target);
					}else{
						target.attackEntityFrom(DamageSource.MAGIC, damage);
					}
				}
			}

		}else{

			if(spin) this.setRotation(this.rotationYaw, this.rotationPitch + 15);

			List<Entity> collided = world.getEntitiesInAABBexcluding(this, this.getCollisionBoundingBox(), e -> e instanceof EntityLivingBase);

			float damage = Spells.lightning_hammer.getProperty(Spell.DIRECT_DAMAGE).floatValue() * damageMultiplier;

			for(Entity entity : collided){
				entity.attackEntityFrom(MagicDamage.causeIndirectMagicDamage(this, getCaster(), DamageType.SHOCK), damage);
				//if(entity instanceof EntityLivingBase) ((EntityLivingBase)entity).knockBack(this, 2, -this.motionX, -this.motionZ);
			}
		}
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		BlockPos pos = this.getPosition().down(1);
		IBlockState blockState = this.world.getBlockState(pos);

		if(!this.world.isRemote) {
			if(blockState.getBlock() == Blocks.AIR || (this.hasPlayerOwner() && !blockState.isSideSolid(this.world, pos, EnumFacing.UP))) {
				this.setDead();
			}

			Entity owner = this.getPlayerOwner();

			if(this.hasPlayerOwner() && (owner == null || owner.getDistance(this) > 32.0D)) {
				this.setHealth(0);
			} else if(owner instanceof EntityPlayer) {
				EntityPlayer player = (EntityPlayer) owner;
				if(!ItemRingOfSummoning.isRingActive(player)) {
					this.setHealth(0);
				}
			}

			if(this.despawnTicks >= 150) {
				this.setHealth(0);
			} else {
				if(this.spawnTicks >= 40) {
					this.despawnTicks++;
				}
			}
		}

		if(this.deathTicks > 0) {
			this.yOffset = -this.deathTicks / 40.0F;
		} else if(this.spawnTicks >= 40) {
			this.yOffset = 0.0F;
		}

		if(this.isEntityAlive()) {
			if(this.spawnTicks >= 4) {
				List<EntityLivingBase> targets = this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox());
				for(EntityLivingBase target : targets) {

					boolean isValidTarget;
					if(this.hasPlayerOwner()) {
						isValidTarget = target != this && target != this.getPlayerOwner() && (target instanceof EntityMob || target instanceof IMob);
					} else {
						isValidTarget = target instanceof EntityPlayer;
					}
					if(isValidTarget) {
						target.setInWeb();

						if(target.hurtResistantTime < 10) {
							DamageSource damageSource;
							Entity owner = this.getPlayerOwner();
							if(owner != null) {
								damageSource = new EntityDamageSourceIndirect("mob", this, owner);
							} else {
								damageSource = DamageSource.causeMobDamage(this);
							}

							target.attackEntityFrom(damageSource, (float) this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue());

							if(this.attackSwing <= 0) {
								this.attackSwing = 20;
							}
						}
					}
				}
			}

			if(this.spawnTicks < 40) {
				this.spawnTicks++;
				this.yOffset = -1 + this.spawnTicks / 40.0F;
			} else {
				this.yOffset = 0.0F;
			}

			if(this.attackSwing > 0) {
				this.attackSwing--;
			}
		}

		if(this.world.isRemote && this.rand.nextInt(this.yOffset < 0.0F ? 2 : 8) == 0) {
			if(blockState.getBlock() != Blocks.AIR) {
				double px = this.posX;
				double py = this.posY;
				double pz = this.posZ;
				for (int i = 0, amount = 2 + this.rand.nextInt(this.yOffset < 0.0F ? 8 : 3); i < amount; i++) {
					double ox = this.rand.nextDouble() * 0.1F - 0.05F;
					double oz = this.rand.nextDouble() * 0.1F - 0.05F;
					double motionX = this.rand.nextDouble() * 0.2 - 0.1;
					double motionY = this.rand.nextDouble() * 0.1 + 0.1;
					double motionZ = this.rand.nextDouble() * 0.2 - 0.1;
					this.world.spawnParticle(EnumParticleTypes.BLOCK_DUST, px + ox, py, pz + oz, motionX, motionY, motionZ, Block.getStateId(blockState));
				}
			}
		}
	}

@Override
	public void onUpdate() {
		super.onUpdate();

		if(!this.world.isRemote) {
			if(this.source == null) {
				this.setDead();
			} else {
				Entity shootingEntity;
				DamageSource damageSource;

				if(this.source instanceof EntityBLArrow) {
					shootingEntity = ((EntityBLArrow) this.source).getThrower();

					if(shootingEntity != null) {
						damageSource = DamageSource.causeArrowDamage((EntityBLArrow) this.source, shootingEntity);
					} else {
						damageSource = DamageSource.causeArrowDamage((EntityBLArrow) this.source, (EntityBLArrow) this.source);
					}
				} else if(this.source instanceof EntityLivingBase) {
					shootingEntity = null;
					damageSource = DamageSource.causeMobDamage((EntityLivingBase) this.source);
				} else {
					shootingEntity = null;
					damageSource = DamageSource.GENERIC;
				}

				List<Pair<Entity, Entity>> chain = new ArrayList<>();

				if(this.jumps < this.maxJumps) {
					if(this.ticksExisted != 0 && this.ticksExisted % 3 == 0) {
						Set<EntityLivingBase> newTargets = new HashSet<>();

						entityLoop: for(Entity entity : this.targets) {
							boolean isWet = entity.isWet() || entity.isInWater() || this.world.isRainingAt(entity.getPosition().up());

							List<EntityLivingBase> entities = this.world.getEntitiesWithinAABB(EntityLivingBase.class, entity.getEntityBoundingBox().grow(isWet ? 6 : 4), e -> {
								Entity riding = e.getLowestRidingEntity();

								//Passengers are handled further down
								if(riding != e && riding instanceof EntityLivingBase) {
									return false;
								}

								return true;	
							});

							if(entities.size() > 1) {
								Collections.sort(entities, (e1, e2) -> Double.compare(e1.getDistanceSq(entity), e2.getDistanceSq(entity)));

								for(int j = 1; j < entities.size(); j++) {
									EntityLivingBase newTarget = entities.get(j);

									if(!this.targets.contains(newTarget) && !newTargets.contains(newTarget)) {
										newTargets.add(newTarget);

										chain.add(Pair.of(entity, newTarget));

										float f = MathHelper.sqrt(this.source.motionX * this.source.motionX + this.source.motionY * this.source.motionY + this.source.motionZ * this.source.motionZ);

										float damage = this.damage;
										if(this.source instanceof EntityBLArrow) {
											damage = MathHelper.ceil((double)f * ((EntityBLArrow) this.source).getDamage());

											if (((EntityBLArrow) this.source).getIsCritical()) {
												damage += this.rand.nextInt((int)damage / 2 + 2);
											}
										}

										boolean blocked = false;

										for(ItemStack stack : newTarget.getEquipmentAndArmor()) {
											if(!stack.isEmpty() && stack.getItem() instanceof ItemRubberBoots) {
												stack.damageItem(2, newTarget);
												blocked = true;
											}
										}

										boolean wasShocked = false;

										if(!blocked) {
											wasShocked = newTarget.attackEntityFrom(damageSource, isWet ? 2 * damage : damage);

											//Also zap all passengers >:)
											for(Entity passenger : newTarget.getRecursivePassengers()) {
												if(passenger instanceof EntityLivingBase && !this.targets.contains(passenger) && !newTargets.contains(passenger)) {
													passenger.attackEntityFrom(damageSource, isWet ? 2 * damage : damage);
													newTargets.add((EntityLivingBase) passenger);
												}
											}
										}

										if(!wasShocked) {
											newTarget.addPotionEffect(ElixirEffectRegistry.EFFECT_SHOCKED.createEffect(newTarget instanceof EntityPlayer ? 30 : 80, 0, true, true));
										}

										continue entityLoop;
									}
								}
							}
						}

						this.targets.addAll(newTargets);

						TheBetweenlands.networkWrapper.sendToAllTracking(new MessageShockArrowHit(chain), this);

						this.jumps++;
					}
				} else {
					this.setDead();
				}
			}
		}
	}

@NotNull
	@Override
	public InteractionResult useOn(UseOnContext ctx) {
		Level world = ctx.getLevel();
		BlockPos pos = ctx.getClickedPos();
		Player player = ctx.getPlayer();

		if (player != null && player.isSecondaryUseActive()) {
			if (world.isClientSide) {
				for (int i = 0; i < 10; i++) {
					float x1 = (float) (pos.getX() + Math.random());
					float y1 = pos.getY() + 1;
					float z1 = (float) (pos.getZ() + Math.random());
					WispParticleData data = WispParticleData.wisp((float) Math.random() * 0.5F, (float) Math.random(), (float) Math.random(), (float) Math.random(), 1);
					world.addParticle(data, x1, y1, z1, 0, 0.05F - (float) Math.random() * 0.05F, 0);
				}
			} else {
				ItemStack stack = ctx.getItemInHand();
				Tag nbt = BlockPos.CODEC.encodeStart(NbtOps.INSTANCE, pos).get().orThrow();
				ItemNBTHelper.set(stack, TAG_TARGET_PREFIX + world.dimension().location(), nbt);
				world.playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.flugelEyeBind, SoundSource.PLAYERS, 1F, 1F);
			}

			return InteractionResult.sidedSuccess(world.isClientSide());
		}

		return InteractionResult.PASS;
	}

public void handle(MinecraftServer server, ServerPlayer player) {
		server.execute(() -> {
			player.level().playSound(null, player.getX(), player.getY(), player.getZ(), BotaniaSounds.dash, SoundSource.PLAYERS, 1F, 1F);

			ItemStack ringStack = EquipmentHandler.findOrEmpty(BotaniaItems.dodgeRing, player);
			if (ringStack.isEmpty()) {
				player.connection.disconnect(Component.translatable("botaniamisc.invalidDodge"));
				return;
			}

			player.causeFoodExhaustion(0.3F);
			ItemNBTHelper.setInt(ringStack, RingOfDexterousMotionItem.TAG_DODGE_COOLDOWN, RingOfDexterousMotionItem.MAX_CD);
		});
	}

public static void handleRollPublish(Packets.RollPublish packet, MinecraftServer server, ServerPlayer player) {
        ServerLevel world = Iterables.tryFind(server.getAllLevels(), (element) -> element == player.level())
                .orNull();
        final var velocity = packet.velocity();
        final var forwardPacket = new Packets.RollAnimation(player.getId(), packet.visuals(), packet.velocity());
        Platform.tracking(player).forEach(serverPlayer -> {
            try {
                if (serverPlayer.getId() != player.getId() && Platform.networkS2C_CanSend(serverPlayer, Packets.RollAnimation.PACKET_ID)) {
                    Platform.networkS2C_Send(serverPlayer, forwardPacket);
                }
            } catch (Exception e) {
                e.printStackTrace();
            }
        });

        world.getServer().executeIfPossible(() -> {
            ((RollInvulnerable)player).setRollInvulnerableTicks(CombatRollMod.config.invulnerable_ticks_upon_roll);
            player.causeFoodExhaustion(CombatRollMod.config.exhaust_on_roll);
            player.awardStat(CombatRollStats.ROLL.stat);
            // 1.5D to approximate difference between velocity and actual travel
            player.awardStat(CombatRollStats.ROLL_CM.stat, (int)(velocity.length() * 100 * 1.5D));
            var proxy = (Event.Proxy<ServerSideRollEvents.PlayerStartRolling>)ServerSideRollEvents.PLAYER_START_ROLLING;
            proxy.handlers.forEach(hander -> { hander.onPlayerStartedRolling(player, velocity);});
        });
    }

private boolean summonEntity(StoredEntity storedEntity, UseOnContext context) {
        BlockPos pos = context.getClickedPos();
        Level level = context.getLevel();
        Entity entity = storedEntity.createEntity(level);

        if (!level.getBlockState(pos).canBeReplaced(new BlockPlaceContext(context))) {
            pos = pos.relative(context.getClickedFace());
        }

        if (entity == null || !level.getBlockState(pos).canBeReplaced(new BlockPlaceContext(context))) {
            return false;
        }

        entity.setPos(pos.getX() + 0.5D, pos.getY(), pos.getZ() + 0.5D);

        if (context.getPlayer() != null) {
            entity.lookAt(EntityAnchorArgument.Anchor.EYES, context.getPlayer().position());
        }
        level.addFreshEntity(entity);

        context.getItemInHand().remove(ModDataComponents.STORED_ENTITY);

        return true;
    }

public void finishRitual(ServerLevel level, BlockPos pos, ActiveRitualData data, HephaestusForgeSharedData sharedData) {
        ServerPlayer initiator = EntityReference.get(this.ritualInitiator, level, ServerPlayer.class);

        this.resetRitual(level, sharedData);

        ItemStack result = data.finish(level, pos, initiator, sharedData.getMainSlotInventory().getStack());
        sharedData.getMainSlotInventory().setStack(result);

        level.sendParticles(ModParticles.MAGIC_EXPLOSION.get(), pos.getX() + 0.5D, pos.getY() + 1.4D, pos.getZ() + 0.5D, 1, 0.0D, 0.0D, 0.0D, 0.0D);
    }

@Override
    public void tick() {
        super.tick();
        double dist = bear.distanceTo(target);
        bear.getLookControl().setLookAt(this.target.getX(), this.target.getEyeY(), this.target.getZ());
        if(dist <= 6 && bear.hasLineOfSight(target)){
            bear.getNavigation().stop();
            if(bear.getAprilFoolsFlag() == 5){
                leapTimer++;
                if(leapTimer == 7){
                    AlexsMobs.sendMSGToAll(new MessageSendVisualFlagFromServer(target.getId(), 87));
                }
                if(leapTimer >= 10){
                    bear.setAprilFoolsFlag(0);
                    if(bear.level().getLevelData().isHardcore()){
                        target.hurt(AMDamageTypes.causeFreddyBearDamage(bear), target.getMaxHealth() - 1);
                        target.setHealth(1);
                    }else{
                        target.hurt(AMDamageTypes.causeFreddyBearDamage(bear), target.getMaxHealth() + 1000F);
                    }
                    stop();
                    return;
                }
            }else if(bear.getAprilFoolsFlag() < 4) {
                if(powerOutTimer == 0){
                    target.addEffect(new MobEffectInstance(AMEffectRegistry.POWER_DOWN.get(), 2 * (maxMusicBoxTime + 100), 0, false, false, true));
                }
                powerOutTimer++;
                if (powerOutTimer >= 60) {
                    bear.setAprilFoolsFlag(4);
                    powerOutTimer = 0;
                }else{
                    bear.setAprilFoolsFlag(3);
                }
            }else{
                if(musicBoxTimer == 0){
                    bear.level().broadcastEntityEvent(bear, (byte) 67);
                }
                musicBoxTimer++;
                if (musicBoxTimer >= maxMusicBoxTime) {
                    if(bear.getAprilFoolsFlag() != 5){
                        bear.level().broadcastEntityEvent(bear, (byte) 68);
                        bear.setAprilFoolsFlag(5);
                        bear.gameEvent(GameEvent.ENTITY_ROAR);
                        bear.playSound(AMSoundRegistry.APRIL_FOOLS_SCREAM.get(), 3, 1);
                        musicBoxTimer = 0;
                    }
                }
            }
            if(bear.getAprilFoolsFlag() < 2){
                bear.setAprilFoolsFlag(2);
            }
        }else{
            bear.getNavigation().moveTo(target, 1.2F);
            if(bear.getAprilFoolsFlag() < 1){
                bear.setAprilFoolsFlag(1);
            }
        }
    }

public void rideTick() {
        final Entity entity = this.getVehicle();
        if (this.isPassenger() && !entity.isAlive()) {
            this.stopRiding();
        } else {
            this.setDeltaMovement(0, 0, 0);
            this.tick();
            if (this.isPassenger()) {
                final Entity mount = this.getVehicle();
                if (mount instanceof final LivingEntity livingEntity) {
                    this.yBodyRot = livingEntity.yBodyRot;
                    this.setYRot(livingEntity.getYRot());
                    this.yHeadRot = livingEntity.yHeadRot;
                    this.yRotO = livingEntity.yHeadRot;
                    final float radius = 1F;
                    final float angle = (Maths.STARTING_ANGLE * livingEntity.yBodyRot);
                    final double extraX = radius * Mth.sin(Mth.PI + angle);
                    final double extraZ = radius * Mth.cos(angle);
                    this.setPos(mount.getX() + extraX, Math.max(mount.getY() + mount.getEyeHeight() * 0.25F, mount.getY()), mount.getZ() + extraZ);
                    if (!mount.isAlive() || mount instanceof Player && ((Player) mount).isCreative()) {
                        this.removeVehicle();
                    }
                    if (!this.level().isClientSide) {
                        if (drinkTime % 20 == 0 && this.isAlive()) {
                            final boolean mungus = AMConfig.warpedMoscoTransformation && mount instanceof EntityMungus && ((EntityMungus) mount).isWarpedMoscoReady();
                            if (mount.hurt(this.damageSources().mobAttack(this), mungus ? 7F : 2.0F)) {
                                if (mungus) {
                                    ((EntityMungus) mount).disableExplosion();
                                }
                                final boolean sick = this.isNonMungusWarpedTrigger(mount);
                                if (sick || mungus) {
                                    if (!this.isSick()) {
                                        for (ServerPlayer serverplayerentity : this.level().getEntitiesOfClass(ServerPlayer.class, this.getBoundingBox().inflate(40.0D, 25.0D, 40.0D))) {
                                            AMAdvancementTriggerRegistry.MOSQUITO_SICK.trigger(serverplayerentity);
                                        }
                                    }
                                    this.setSick(true);
                                    this.setFlying(false);
                                    flightTicks = -150 - random.nextInt(200);
                                }
                                this.gameEvent(GameEvent.EAT);
                                this.playSound(SoundEvents.HONEY_DRINK, this.getSoundVolume(), this.getVoicePitch());
                                this.setBloodLevel(this.getBloodLevel() + 1);
                                if (this.getBloodLevel() > 3) {
                                    this.removeVehicle();
                                    AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                                    this.setFlying(false);
                                    this.flightTicks = -15;
                                }
                            }
                        }

                        if (drinkTime > 81) {
                            drinkTime = -20 - random.nextInt(20);
                            this.removeVehicle();
                            AlexsMobs.sendMSGToAll(new MessageMosquitoDismount(this.getId(), mount.getId()));
                            this.setFlying(false);
                            this.flightTicks = -15;
                        }
                    }
                }

            }
        }

    }

private void doTick(Level level, BlockPos pos, BlockState blockState) {
		if (!(blockState.getBlock() instanceof HenostoneFireSpitterBlock fireSpitter)) return;

		Direction dir = fireSpitter.getDirection(blockState);

		rangeLen = raycastRange(level, pos, dir, 8.0);

		AABB detectionAABB = buildAABB(pos, dir, rangeLen);

		switch (state) {

		case IDLE -> {
			List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
			if (!entities.isEmpty()) {
				boolean hasValidTarget = entities.stream().anyMatch(e ->
				!(e instanceof Player player && player.isCreative()));
				if (hasValidTarget) {
					transitionTo(FireState.WARNING_1, level, pos);
				}
			}
			setPowered(level, pos, blockState, false);
		}

		case WARNING_1 -> {
			timer++;
			if (timer == WARNING_1_TICKS + 1) {
				playWarningSound(level, pos);
			}
			if (timer >= WARNING_2_TICKS) {
				transitionTo(FireState.WARNING_2, level, pos);
			}
		}

		case WARNING_2 -> {
			timer++;
			if (timer == WARNING_1_TICKS + 1) {
				playWarningSound(level, pos);
			}
			if (timer >= WARNING_2_TICKS) {
				transitionTo(FireState.WARNING_3, level, pos);
			}
		}

		case WARNING_3 -> {
			timer++;
			if (timer == WARNING_3A_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer == WARNING_3B_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer == WARNING_3C_TICKS - WARNING_3A_TICKS + 1) playWarningSound(level, pos);
			if (timer >= FIRE_START_TICKS - WARNING_3A_TICKS) {
				transitionTo(FireState.FIRING, level, pos);
			}
		}

		case FIRING -> {
			timer++;
			setPowered(level, pos, blockState, true);

			List<LivingEntity> targets = level.getEntitiesOfClass(LivingEntity.class, detectionAABB);
			double ox = pos.getX() + 0.5;
			double oy = pos.getY() + 0.5;
			double oz = pos.getZ() + 0.5;
			level.addParticle(ParticleTypes.FLAME, ox, oy, oz, dir.getStepX() * 0.5, 0, dir.getStepZ() * 0.5);
			for (LivingEntity entity : targets) {
				if (!entity.fireImmune()) {
					entity.setSecondsOnFire(8);
					entity.hurt(level.damageSources().inFire(), 1);
				}
			}

			if (timer >= FIRE_END_TICKS - FIRE_START_TICKS) {
				transitionTo(FireState.COOLDOWN, level, pos);
			}
		}

		case COOLDOWN -> {
			timer++;
			setPowered(level, pos, blockState, false);
			if (timer >= COOLDOWN_TICKS) {
				transitionTo(FireState.IDLE, level, pos);
			}
		}
		}
	}

default void kick(boolean backKick, boolean softBackKick) {
		AbstractHorse horse = (AbstractHorse) this;

		this.setKickTime(1);
		horse.setEating(false);

		AttributeInstance attributeinstance = horse.getAttribute(Attributes.MOVEMENT_SPEED);
		if (!attributeinstance.hasModifier(SPEED_MODIFIER_KICKING.id()))
			attributeinstance.addTransientModifier(SPEED_MODIFIER_KICKING);

		if (!backKick) {
			this.playFrontKickAnim();
			horse.level().broadcastEntityEvent(horse, (byte) 8);
		} else {
			this.playBackKickAnim();
			horse.level().broadcastEntityEvent(horse, (byte) 9);
		}

		List<LivingEntity> nearby = horse.level().getEntitiesOfClass(LivingEntity.class, horse.getBoundingBox().inflate(1.0F), KICKABLE_PREDICATE);
		for (LivingEntity living : nearby) {
			Vec3 attackAngleVector = living.position().subtract(horse.position()).normalize();
			attackAngleVector = new Vec3(attackAngleVector.x, 0.0D, attackAngleVector.z);

			float rot = horse.getVisualRotationYInDegrees();
			float x = Mth.sin(rot * Mth.DEG_TO_RAD);
			float z = -Mth.cos(rot * Mth.DEG_TO_RAD);
			double angle = attackAngleVector.dot(Vec3.directionFromRotation(0.0F, rot).normalize());
			boolean jumpkick = this.canJumpKick();

			if (!backKick && angle > 0.7D || backKick && angle < -0.7D) {
				DamageSource source;
				LivingEntity rider = horse.getControllingPassenger();
				if (rider != null) {
					source = EnvironmentalDamageTypes.ridingZebra(horse.level(), horse, rider);
				} else {
					source = horse.damageSources().mobAttack(horse);
				}
				float damage = (float) horse.getAttributeValue(Attributes.ATTACK_DAMAGE);
				float knockback = (float) horse.getAttributeValue(Attributes.ATTACK_KNOCKBACK);

				if (jumpkick) {
					float f = this.getJumpStrength();
					if (rider != null && rider.zza <= 0.0F)
						f *= 0.5F;
					damage += f * 6.0F;
					knockback = knockback * 0.8F + f * 1.1F;
				} else if (backKick) {
					if (!softBackKick)
						damage += 2.0F;
					else if (damage > 1.0F)
						damage = 1.0F;
					knockback *= 1.2F;
				} else {
					knockback *= 0.8F;
				}

				if (living.hurt(source, (int) damage)) {
					if (horse.level() instanceof ServerLevel serverLevel) {
						EnchantmentHelper.doPostAttackEffects(serverLevel, living, source);
					}

					if (!backKick)
						living.knockback(knockback, x, z);
					else
						living.knockback(knockback, -x, -z);
				}
			}
		}
	}

protected void pushEntitiesAway() {
		boolean collision = false;

		double maxReverseX = -1;
		double maxReverseZ = -1;

		AxisAlignedBB collisionAABB = this.getCollisionBoundingBox();
		if(collisionAABB != null) {
			List<Entity> entities = this.world.getEntitiesWithinAABBExcludingEntity(this, collisionAABB);

			for(Entity entity : entities) {
				if(entity.canBeCollidedWith()) {
					if(!entity.canBePushed() && entity instanceof EntityMovingWall == false) {
						collision = true;
					} else {
						AxisAlignedBB entityAABB = entity.getEntityBoundingBox();
						boolean squished = false;
						double dx = Math.max(collisionAABB.minX - entityAABB.maxX, entityAABB.minX - collisionAABB.maxX);
						double dz = Math.max(collisionAABB.minZ - entityAABB.maxZ, entityAABB.minZ - collisionAABB.maxZ);

						if(Math.abs(dz) < Math.abs(dx)) {
							entity.move(MoverType.PISTON, 0, 0, (dz - 0.005D) * Math.signum(this.posZ - entity.posZ));
							entityAABB = entity.getEntityBoundingBox();
							dz = Math.max(collisionAABB.minZ - entityAABB.maxZ, entityAABB.minZ - collisionAABB.maxZ);

							if(-dz > 0.025D) {
								squished = true;
								maxReverseZ = Math.max(-dz, maxReverseZ);
							}
						} else {
							entity.move(MoverType.PISTON, (dx - 0.005D) * Math.signum(this.posX - entity.posX), 0, 0);
							entityAABB = entity.getEntityBoundingBox();
							dx = Math.max(collisionAABB.minX - entityAABB.maxX, entityAABB.minX - collisionAABB.maxX);

							if(-dx > 0.025D) {
								squished = true;
								maxReverseX = Math.max(-dx, maxReverseX);
							}
						}

						//Move slightly towards ground to update onGround state etc.
						entity.move(MoverType.PISTON, 0, -0.01D, 0);

						if(squished) {
							collision = true;

							if(!this.world.isRemote) {
								entity.attackEntityFrom(DamageSource.IN_WALL, 10F);
								setHoldStill(true);
								holdCount = 20;
								getEntityWorld().playSound(null, getPosition(), SoundRegistry.WALL_SLAM, SoundCategory.HOSTILE, 0.5F, 0.75F);
							}
						}
					}
				}
			}
		}

		if(collision) {
			if(maxReverseZ > 0) {
				this.posZ -= (maxReverseZ + 0.05D) * Math.signum(this.motionZ);
			}
			if(maxReverseX > 0) {
				this.posX -= (maxReverseX + 0.05D) * Math.signum(this.motionX);
			}

			shaking = true;
			shake_timer = 0;

			if(!this.world.isRemote) {
				motionX *= -1D;
				motionZ *= -1D;
				velocityChanged = true;
			}
		}
	}

public void tick() {
        super.tick();
        if(this.tickCount % 100 == 0){
            this.heal(2);
        }
        float f = Mth.wrapDegrees(180 + this.getYRot());
        this.yBodyRot = rotlerp(this.yBodyRot, f, 180);
        prevSquidPitch = getSquidPitch();
        prevDepressurization = getDepressurization();
        prevDryProgress = dryProgress;
        prevGrabProgress = grabProgress;
        prevCapturedProgress = capturedProgress;
        if (!this.isInWater() && dryProgress < 5F) {
            dryProgress++;
        }
        if (this.isInWater() && dryProgress > 0F) {
            dryProgress--;
        }

        if (this.isGrabbing()) {
            if (grabProgress < 5F)
                grabProgress += 0.25F;
        } else {
            if (grabProgress > 0F)
                grabProgress -= 0.25F;
        }

        if (this.isCaptured()) {
            if (capturedProgress < 5F)
                capturedProgress += 0.5F;
        } else {
            if (capturedProgress > 0F)
                capturedProgress -= 0.5F;
        }

        if (this.isGrabbing()) {
            Entity target = getGrabbedEntity();
            if(!this.level().isClientSide && target != null){
                this.entityData.set(GRAB_ENTITY, target.getId());
                if (holdTime % 20 == 0 && holdTime > 30) {
                    target.hurt(this.damageSources().mobAttack(this), 3 + random.nextInt(5));
                }
            }
            if (target != null && target.isAlive()) {
                this.setXRot(0);
                float invert = 1F - grabProgress * 0.2F;
                Vec3 extraVec = new Vec3(0, 0, 2F + invert * 7F).xRot(-this.getXRot() * Mth.DEG_TO_RAD).yRot(-this.yBodyRot * Mth.DEG_TO_RAD);
                Vec3 minus = new Vec3(this.getX() + extraVec.x - target.getX(), this.getY() + extraVec.y - target.getY(), this.getZ() + extraVec.z - target.getZ());
                target.setDeltaMovement(minus);
            }
            holdTime++;
            if (holdTime > 1000) {
                holdTime = 0;
                this.setGrabbing(false);
            }
        } else {
            holdTime = 0;
        }
        if (!this.isNoAi()) {
            Vec3[] avector3d = new Vec3[this.allParts.length];
            for (int j = 0; j < this.allParts.length; ++j) {
                this.allParts[j].collideWithNearbyEntities();
                avector3d[j] = new Vec3(this.allParts[j].getX(), this.allParts[j].getY(), this.allParts[j].getZ());
            }
            final float pitch = this.getXRot() * Mth.DEG_TO_RAD * 0.8F;
            this.mantleCollisionPart.setPos(this.getX(), this.getY() - ((this.mantleCollisionPart.getBbHeight() - this.getEyeHeight()) * 0.5F) * (1F - dryProgress * 0.2F), this.getZ());
            this.setPartPositionFromBuffer(this.mantlePart1, pitch, 0.9F, 0);
            this.setPartPositionFromBuffer(this.mantlePart2, pitch, 1.6F, 0);
            this.setPartPositionFromBuffer(this.mantlePart3, pitch, 2.45F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart1, pitch, -0.8F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart2, pitch, -1.5F, 0);
            this.setPartPositionFromBuffer(this.tentaclesPart3, pitch, -2.3F, 5);
            this.setPartPositionFromBuffer(this.tentaclesPart4, pitch, -3.4F, 10);
            this.setPartPositionFromBuffer(this.tentaclesPart5, pitch, -5.4F, 15);
            this.setPartPositionFromBuffer(this.tentaclesPart6, pitch, -7.4F, 20);
            if (this.isInWaterOrBubble()) {
                if (this.mantleCollisionPart.scale != 1F) {
                    this.mantleCollisionPart.scale = 1F;
                    this.mantleCollisionPart.refreshDimensions();
                }
            } else {
                if (this.mantleCollisionPart.scale != 0.25F) {
                    this.mantleCollisionPart.scale = 0.25F;
                    this.mantleCollisionPart.refreshDimensions();
                }
            }
            for (int l = 0; l < this.allParts.length; ++l) {
                this.allParts[l].xo = avector3d[l].x;
                this.allParts[l].yo = avector3d[l].y;
                this.allParts[l].zo = avector3d[l].z;
                this.allParts[l].xOld = avector3d[l].x;
                this.allParts[l].yOld = avector3d[l].y;
                this.allParts[l].zOld = avector3d[l].z;
            }
            this.setNoGravity(this.isInWater());
        }
        if (!this.level().isClientSide) {
            if (this.getSquidPitch() > 0F) {
                float decrease = Math.min(2F, this.getSquidPitch());
                this.decrementSquidPitch(decrease);
            }
            if (this.getSquidPitch() < 0F) {
                float decrease = Math.min(2F, -this.getSquidPitch());
                this.incrementSquidPitch(decrease);
            }
            if (this.isInWaterOrBubble()) {
                float dist = (float) this.getDeltaMovement().y() * 45;
                if (entityData.get(OVERRIDE_BODYROT)) {
                    this.decrementSquidPitch(dist);
                } else {
                    this.incrementSquidPitch(dist);
                }
            }
            if (!this.onGround() && this.getFluidHeight(FluidTags.WATER) < this.getBbHeight()) {
                this.setDeltaMovement(this.getDeltaMovement().add(0, -0.1F, 0));
            }
            float pressure = getDepressureLevel();
            if (this.getDepressurization() < pressure) {
                this.setDepressurization(this.getDepressurization() + 0.1F);
            }
            if (this.getDepressurization() > pressure) {
                this.setDepressurization(this.getDepressurization() - 0.1F);
            }
        }
        if (this.isHumming()) {
            if (humTick % 20 == 0) {
                this.playSound(AMSoundRegistry.GIANT_SQUID_GAMES.get(), this.getSoundVolume(), 1);
                humTick = 0;
            }
            humTick++;
        }
        if(!this.level().isClientSide){
            if(resetCapturedStateIn > 0){
                resetCapturedStateIn--;
            }else{
                this.setCaptured(false);
            }
        }
    }

@Override
	public void onUpdate() {
		super.onUpdate();

		if (world.isRemote) {
			prevGrowCount = growCount;
			growCount = getGrowTimer();
			if(ticksExisted % 10 == 0) {
				renderParticles(world, posX, posY, posZ, rand);
			}
			if(this.sheddingProgress > this.getSheddingSpeed()) {
				this.sheddingProgress = 0;

				for(int i = 0; i < 200; i++) {
					Random rnd = world.rand;
					float rx = rnd.nextFloat() * 4.0F - 2.0F;
					float ry = rnd.nextFloat() * 4.0F - 2.0F;
					float rz = rnd.nextFloat() * 4.0F - 2.0F;
					Vec3d vec = new Vec3d(rx, ry, rz);
					vec = vec.normalize();
					BLParticles.SPLASH_TAR.spawn(this.world, this.posX + rx + 0.25F, this.posY + ry, this.posZ + rz + 0.25F, ParticleArgs.get().withMotion(vec.x * 0.5F, vec.y * 0.5F, vec.z * 0.5F));
				}
			} else if(this.isShedding() || this.sheddingProgress > 0) {
				this.sheddingProgress++;
			} else {
				this.sheddingProgress = 0;
			}

			if(this.isSucking()) {
				for(int i = 0; i < 5; i++) {
					Random rnd = world.rand;
					float rx = rnd.nextFloat() * 8.0F - 4.0F;
					float ry = rnd.nextFloat() * 8.0F - 4.0F;
					float rz = rnd.nextFloat() * 8.0F - 4.0F;
					Vec3d vec = new Vec3d(rx, ry, rz);
					vec = vec.normalize();
					this.world.spawnParticle(EnumParticleTypes.SMOKE_LARGE, this.posX + rx + 0.25F, this.posY + ry, this.posZ + rz + 0.25F, -vec.x * 0.5F, -vec.y * 0.5F, -vec.z * 0.5F);
				}
			}
		}

		if(!world.isRemote) {
			if(this.isInsideOfMaterial(BLMaterialRegistry.TAR)) {
				this.stepHeight = 2.0F;
			} else {
				this.stepHeight = 0.75F;
			}

			if(this.shedCooldown > 0 && this.getAttackTarget() != null) {
				this.shedCooldown--;
			}

			if(!this.isSucking() && !this.isPreparing()) {
				if(this.shedCooldown == 0 && this.getAttackTarget() != null && this.getAttackTarget().getDistance(this) < 6.0D && this.canEntityBeSeen(this.getAttackTarget())) {
					this.setShedding(true);
					this.shedCooldown = this.getSheddingCooldown() + this.world.rand.nextInt(this.getSheddingCooldown() / 2);
				}

				if(this.sheddingProgress > this.getSheddingSpeed()) {
					this.playSound(SoundRegistry.TAR_BEAST_LIVING, 1F, (this.rand.nextFloat() * 0.2F + 1.0F) * 0.6F);
					for(int i = 0; i < 8; i++) {
						this.playSound(SoundRegistry.TAR_BEAST_STEP, 1F, (this.rand.nextFloat() * 0.4F + 0.8F) * 0.8F);
					}
					this.sheddingProgress = 0;
					this.setShedding(false);
					if(this.getAttackTarget() != null) {
						List<EntityLivingBase> affectedEntities = (List<EntityLivingBase>)this.world.getEntitiesWithinAABB(EntityLivingBase.class, this.getEntityBoundingBox().grow(6.0F, 6.0F, 6.0F));
						for(EntityLivingBase e : affectedEntities) {
							if(e == this || e.getDistance(this) > 6.0F || !e.canEntityBeSeen(this) || e instanceof EntityTarBeast) continue;
							if(e instanceof EntityPlayer) {
								if(((EntityPlayer)e).isActiveItemStackBlocking()) continue;
							}
							double dst = e.getDistance(this);
							float dmg = (float) (this.getEntityAttribute(SharedMonsterAttributes.ATTACK_DAMAGE).getAttributeValue() / dst * 7.0F);
							e.attackEntityFrom(DamageSource.causeMobDamage(this), dmg);
							e.addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, (int)(20 + (1.0F - dst / 6.0F) * 150), 1));
						}
					}
				}

				if(this.isShedding()) {
					this.sheddingProgress++;
				} else {
					this.sheddingProgress = 0;
				}
			}

			if(this.suckingCooldown > 0 && this.getAttackTarget() != null) {
				this.suckingCooldown--;
			}

			if(!this.isShedding()) {
				if(this.suckingCooldown == 0 && this.getAttackTarget() != null && this.getAttackTarget().getDistance(this) <= 10.0D && this.canEntityBeSeen(this.getAttackTarget())) {
					this.setPreparing();
				}

				if(this.isPreparing()) {
					this.suckingPreparation++;

					if(this.suckingPreparation > this.getEntityAttribute(SUCK_PREPARATION_SPEED_ATTRIB).getAttributeValue()) {
						this.suckingPreparation = 0;

						this.setSucking(true);
						this.suckingCooldown = this.getSuckingCooldown() + this.world.rand.nextInt(this.getSuckingCooldown() / 2);
						this.playSound(SoundRegistry.TAR_BEAST_SUCK, 1F, 1F);
					}
				}

				if(this.suckingProgress > (int)this.getEntityAttribute(SUCK_LENGTH_ATTRIB).getAttributeValue()) {
					this.setSucking(false);
					this.suckingProgress = 0;
				}

				if(this.isSucking()) {
					this.suckingProgress++;

					List<Entity> affectedEntities = (List<Entity>)this.world.getEntitiesWithinAABB(Entity.class, this.getEntityBoundingBox().grow(10.0F, 10.0F, 10.0F));
					for(Entity e : affectedEntities) {
						if(e == this || e.getDistance(this) > 10.0F || !this.canEntityBeSeen(e) || e instanceof EntityTarBeast) continue;
						Vec3d vec = new Vec3d(this.posX - e.posX, this.posY - e.posY, this.posZ - e.posZ);
						vec = vec.normalize();
						float dst = e.getDistance(this);
						float mod = (float) Math.pow(1.0F - dst / 13.0F, 1.2D);
						if(e instanceof EntityPlayer) {
							if(((EntityPlayer)e).isActiveItemStackBlocking()) mod *= 0.18F;
						}
						if(dst < 1.0F && e instanceof EntityLivingBase) {
							((EntityLivingBase) e).addPotionEffect(new PotionEffect(MobEffects.WEAKNESS, 20, 3));
							((EntityLivingBase) e).addPotionEffect(new PotionEffect(MobEffects.SLOWNESS, 20, 3));
							e.motionX *= 0.008F;
							e.motionY *= 0.008F;
							e.motionZ *= 0.008F;
							if(e instanceof EntityPlayer) {
								((EntityPlayer)e).jumpMovementFactor = 0.0F;
							}
							if(this.ticksExisted % 12 == 0) {
								e.attackEntityFrom(DamageSource.DROWN, 1);
							}
						}
						e.motionX += vec.x * 0.18F * mod;
						e.motionY += vec.y * 0.18F * mod;
						e.motionZ += vec.z * 0.18F * mod;
						e.velocityChanged = true;
					}
					getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(0.75D);
				} else {
					this.suckingProgress = 0;
					getEntityAttribute(SharedMonsterAttributes.KNOCKBACK_RESISTANCE).setBaseValue(1.0D);
				}
			}

			if (getGrowTimer() < 40) {
				setGrowTimer(Math.min(40, getGrowTimer() + 1));
			}
		}
	}

@SuppressWarnings("removal")
  @SubscribeEvent
  static void onExperienceDrop(LivingExperienceDropEvent event) {
    // boost entity experience if they are under the effects of experienced
    LivingEntity entity = event.getEntity();
    MobEffectInstance instance = entity.getEffect(TinkerEffects.experienced.get());
    double multiplier = 1 + (instance != null ? instance.getAmplifier() : 0);

    // always add armor boost, unfortunately no good way to stop shield stuff here
    Player player = event.getAttackingPlayer();
    if (player != null) {
      multiplier += player.getAttributeValue(TinkerAttributes.EXPERIENCE_MULTIPLIER.get()) + ArmorStatModule.getStat(player, TinkerDataKeys.EXPERIENCE);
    }
    // if the target was killed by an experienced arrow, use that level
    TinkerDataCapability.Holder data = TinkerDataCapability.getData(entity);
    Float projectileBoost = data != null ? data.get(PROJECTILE_EXPERIENCE) : null;
    if (projectileBoost != null) {
      multiplier += projectileBoost;
    // being -1 means no projectile was involved, so boost by held tool
    } else if (player != null) {
      ToolStack tool = Modifier.getHeldTool(player, ModifierLootingHandler.getLootingSlot(player));
      if (tool != null) {
        multiplier += tool.getVolatileData().getFloat(EXPERIENCE);
      }
    }
    event.setDroppedExperience((int) (event.getDroppedExperience() * multiplier));
  }

