public void tick() {
        super.tick();
        this.prevSitProgress = this.sitProgress;

        if (this.isSitting()) {
            if (sitProgress < 5F)
                sitProgress++;
        } else {
            if (sitProgress > 0F)
                sitProgress--;
        }

        if (!this.level().isClientSide) {
            if (isSitting() && ++sittingTime > maxSitTime) {
                this.setSitting(false);
                sittingTime = 0;
                maxSitTime = 75 + random.nextInt(50);
            }
            if (this.getDeltaMovement().lengthSqr() < 0.03D && this.getAnimation() == NO_ANIMATION && !this.isSitting() && random.nextInt(500) == 0) {
                sittingTime = 0;
                maxSitTime = 200 + random.nextInt(550);
                this.setSitting(true);
            }
            if (this.isSitting() && (this.getTarget() != null || this.isInLove())) {
                this.setSitting(false);
            }
            if (this.getTarget() != null && (this.getAnimation() == ANIMATION_SWIPE_L || this.getAnimation() == ANIMATION_SWIPE_R) && this.getAnimationTick() == 7 && this.hasLineOfSight(this.getTarget()) && this.distanceTo(this.getTarget()) < this.getBbHeight() + this.getTarget().getBbHeight() + 1) {
                getTarget().knockback(0.4F, getTarget().getX() - this.getX(), getTarget().getZ() - this.getZ());
                float dmg = (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getBaseValue();
                if (this.isLeader() && getTarget() instanceof EntityGeladaMonkey monkey) {
                    if (monkey.isLeader()) {
                        monkey.setTarget(this);
                        monkey.leaderFightTime = this.leaderFightTime;
                        dmg = 0;
                    }
                }
                this.getTarget().hurt(this.damageSources().mobAttack(this), dmg);
            }
            if (this.getTarget() != null && this.getTarget().isAlive()) {
                this.setAggro(true);
                if (this.isLeader() && this.getTarget() instanceof EntityGeladaMonkey monkey) {
                    if (monkey.isLeader()) {
                        this.leaderFightTime++;
                    }
                    if(leaderFightTime < 10 && random.nextInt(5) == 0 && this.getAnimation() == NO_ANIMATION){
                        this.setAnimation(ANIMATION_CHEST);
                    }
                    if (Math.max(this.leaderFightTime, monkey.leaderFightTime) >= 250) {
                        this.resetAttackAI();
                        monkey.resetAttackAI();
                    }
                }

            } else {
                this.setAggro(false);
            }
            if (this.leaderFightTime < 0) {
                this.leaderFightTime++;
            }
        }

        if (isAggro()) {
            if (!hasSpedUp) {
                hasSpedUp = true;
                this.setSprinting(true);
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.31F);
            }
        } else {
            if (hasSpedUp) {
                hasSpedUp = false;
                this.setSprinting(false);
                this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25F);
            }
        }

        if (getClearGrassTime() > 0) {
            setClearGrassTime(getClearGrassTime() - 1);
        }
        if (getClearGrassTime() < 0) {
            setClearGrassTime(getClearGrassTime() + 1);
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        super.tick();
        prevLeftArmRot = leftArmRot;
        prevRightArmRot = rightArmRot;
        prevRunProgress = runProgress;
        float armSpinSpeed = getArmSpinSpeed();
        if (armSpinSpeed > 0 && this.isAlive()) {
            if(swingSoundTimer-- < 0){
                swingSoundTimer = 5 + level().random.nextInt(10);
                this.playSound(ACSoundRegistry.CANIAC_SWING.get());
            }
            if(this.isLeftHanded()){
                leftArmRot += armSpinSpeed;
                if(leftArmRot % 360 > 180){
                    spinSecondArm = true;
                }
                if(spinSecondArm){
                    rightArmRot += armSpinSpeed;
                }
            }else{
                rightArmRot += armSpinSpeed;
                if(rightArmRot % 360 > 180){
                    spinSecondArm = true;
                }
                if(spinSecondArm){
                    leftArmRot += armSpinSpeed;
                }
            }
            if(level().isClientSide){
                if(Mth.wrapDegrees(leftArmRot) % 180 > 70){
                    spawnArmSwingParticles(true);
                }
                if(Mth.wrapDegrees(rightArmRot) % 180 > 70){
                    spawnArmSwingParticles(false);
                }
            }else{
                if(Mth.wrapDegrees(leftArmRot) % 180 > 75){
                    hurtMobsFromArmSwing(true, (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue(), 0.1F);
                }
                if(Mth.wrapDegrees(rightArmRot) % 180 > 75){
                    hurtMobsFromArmSwing(false, (float) this.getAttribute(Attributes.ATTACK_DAMAGE).getValue(), 0.1F);
                }
            }
        }else{
            spinSecondArm = false;
            float f = this.getAnimation() == ANIMATION_LUNGE ? 40 : 15;
            if(Mth.wrapDegrees(leftArmRot) != 0){
                leftArmRot = Mth.approachDegrees(leftArmRot, 0, f);
            }
            if(Mth.wrapDegrees(rightArmRot) != 0){
                rightArmRot = Mth.approachDegrees(rightArmRot, 0, f);
            }
        }
        if (isRunning() && !hasRunningAttributes) {
            hasRunningAttributes = true;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.4D);
        }
        if (!isRunning() && hasRunningAttributes) {
            hasRunningAttributes = false;
            this.getAttribute(Attributes.MOVEMENT_SPEED).setBaseValue(0.25D);
        }
        if (isRunning() && runProgress < 5F) {
            runProgress++;
        }
        if (!isRunning() && runProgress > 0F) {
            runProgress--;
        }
        if(level().isClientSide){
            spawnPossessedParticles(getRandomX(0.5D), getRandomY(), getRandomZ(0.5D), this.level());
        }
        if(this.getAnimation() == ANIMATION_LUNGE && this.getAnimationTick() == 10){
            this.playSound(ACSoundRegistry.CANIAC_ATTACK.get());
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public void tick() {
        double distance = entity.distanceTo(inspectingTarget);
        if (entity.getInterestLevel() >= 5 && HullbreakerEntity.GLOWING_TARGET.test(inspectingTarget)) {
            if (!(inspectingTarget instanceof Player) || !((Player) inspectingTarget).isCreative()) {
                entity.setTarget(inspectingTarget);
            }
            inspectingTarget = null;
            return;
        }
        if (entity.getRandom().nextInt(20) == 0 && !HullbreakerEntity.GLOWING_TARGET.test(inspectingTarget)) {
            inspectingTarget = null;
        } else {
            if (entity.getAnimation() == HullbreakerEntity.ANIMATION_PUZZLE && entity.getAnimationTick() > 50) {
                phaseTime = maxPhaseTime;
            }
            if (phaseTime++ > maxPhaseTime) {
                entity.setInterestLevel(entity.getInterestLevel() + 1);
                staring = entity.getRandom().nextBoolean() && !staring;
                phaseTime = 0;
                startCirclingAt = inspectingTarget.getEyePosition();
                maxPhaseTime = staring ? 120 : 120 + 80 * Math.min(0, 5 - entity.getInterestLevel());
            }
            if (staring) {
                entity.lookAt(EntityAnchorArgument.Anchor.EYES, inspectingTarget.getEyePosition());
                if (isPreyWatching() && distance < 18) {
                    if (entity.getAnimation() == IAnimatedEntity.NO_ANIMATION) {
                        entity.setAnimation(HullbreakerEntity.ANIMATION_PUZZLE);
                    }
                    entity.getNavigation().stop();
                } else if (entity.getNavigation().isDone()) {
                    Vec3 frontVision = inspectingTarget.getEyePosition().add(inspectingTarget.getLookAngle().scale(12.0F));
                    entity.getNavigation().moveTo(frontVision.x, frontVision.y, frontVision.z, 1.0F);
                }
            } else {
                if (startCirclingAt == null) {
                    startCirclingAt = inspectingTarget.getEyePosition();
                }
                Vec3 circle = orbitAroundPos(inspectingTarget.getEyePosition(), 12 + Math.min(0, 5 - entity.getInterestLevel()) * 3);
                entity.getNavigation().moveTo(circle.x, circle.y, circle.z, 1.4F);
                entity.setYHeadRot(entity.yBodyRot + (clockwise ? 30 : -30));

            }
            SubmarineEntity.alertSubmarineMountOf(inspectingTarget);
        }
    }

public void tick() {
        super.tick();
        prevStandProgress = standProgress;
        prevTongueProgress = tongueProgress;
        prevLeaningProgress = leaningProgress;

        if (isStanding()) {
            if (standProgress < 5F)
                standProgress++;
        } else {
            if (standProgress > 0F)
                standProgress--;
        }

        final boolean isTongueOut = this.getAnimation() == ANIMATION_TOUNGE_IDLE;
        if (isTongueOut) {
            if (tongueProgress < 5F)
                tongueProgress++;
        } else {
            if (tongueProgress > 0F)
                tongueProgress--;
        }

        if (isLeaning()) {
            if (leaningProgress < 5F)
                leaningProgress++;
        } else {
            if (leaningProgress > 0F)
                leaningProgress--;
        }

        if (isStanding() && ++standingTime > maxStandTime) {
            this.setStanding(false);
            standingTime = 0;
            maxStandTime = 75 + random.nextInt(50);
        }

        if (this.isPassenger() && this.getVehicle() instanceof final EntityAnteater mount) {
            if (this.isBaby()) {
                this.setYRot(mount.yBodyRot);
                this.yHeadRot = mount.yBodyRot;
                this.yBodyRot = mount.yBodyRot;
            } else {
                this.removeVehicle();
            }
        }

        if (eatAntCooldown > 0) {
            eatAntCooldown--;
        }
        if (antsEatenRecently >= 3 && eatAntCooldown <= 0) {
            this.resetAntCooldown();
        }
        if (ticksAntOnTongue > 10 && this.hasAntOnTongue()) {
            this.heal(6);
            this.gameEvent(GameEvent.EAT);
            this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
            this.setAntOnTongue(false);
        }
        if (this.hasAntOnTongue()) {
            ticksAntOnTongue++;
        } else {
            ticksAntOnTongue = 0;
        }
        if (!this.level().isClientSide && getTongueStickOut() > 0.6F && !this.hasAntOnTongue() && antsEatenRecently < 3) {
            EntityLeafcutterAnt closestAnt = null;
            for (EntityLeafcutterAnt entity : this.level().getEntitiesOfClass(EntityLeafcutterAnt.class, this.getBoundingBox().inflate(2.6F))) {
                if (closestAnt == null || entity.distanceTo(this) < closestAnt.distanceTo(this) && this.hasLineOfSight(entity)) {
                    closestAnt = entity;
                }
            }
            if (closestAnt != null) {
                closestAnt.remove(RemovalReason.KILLED);
                ticksAntOnTongue = 0;
                this.setAntOnTongue(true);
                antsEatenRecently++;
            }
        }
        if (!this.getMainHandItem().isEmpty()) {
            heldItemTime++;
            if (heldItemTime > 10 && getTongueStickOut() < 0.3F && canTargetItem(this.getMainHandItem())) {
                heldItemTime = 0;
                this.heal(4);
                this.playSound(SoundEvents.GENERIC_EAT, this.getSoundVolume(), this.getVoicePitch());
                this.gameEvent(GameEvent.EAT);
                if (this.getMainHandItem().hasCraftingRemainingItem()) {
                    this.spawnAtLocation(this.getMainHandItem().getCraftingRemainingItem());
                }
                this.stopBeingAngry();
                this.getMainHandItem().shrink(1);
            }
        } else {
            heldItemTime = 0;
        }

        if (!this.level().isClientSide) {
            if (getRandom().nextInt(300) == 0)
                this.setAnimation(ANIMATION_TOUNGE_IDLE);

            final LivingEntity attackTarget = this.getTarget();
            if (attackTarget != null) {
                if (distanceTo(attackTarget) < attackTarget.getBbWidth() + this.getBbWidth() + 2) {
                    if (this.getAnimationTick() == 7) {
                        if (this.getAnimation() == ANIMATION_SLASH_L) {
                            doHurtTarget(attackTarget);
                            final float rot = getYRot() + 90;
                            attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                        } else if (this.getAnimation() == ANIMATION_SLASH_R) {
                            doHurtTarget(attackTarget);
                            final float rot = getYRot() - 90;
                            attackTarget.knockback(0.5F, Mth.sin(rot * Mth.DEG_TO_RAD), -Mth.cos(rot * Mth.DEG_TO_RAD));
                        }
                    }
                }
            }
        }

        AnimationHandler.INSTANCE.updateAnimations(this);
    }

@Override
    public void tick() {
        super.tick();
        prevUncrossedArmsProgress = uncrossedArmsProgress;
        prevTeleportingProgress = teleportingProgress;
        if (!this.areArmsCrossed() && uncrossedArmsProgress < 5F) {
            uncrossedArmsProgress++;
        }
        if (this.areArmsCrossed() && uncrossedArmsProgress > 0F) {
            uncrossedArmsProgress--;
        }
        if (this.getTeleportingToPos() != null && teleportingProgress < 40F) {
            teleportingProgress++;
        }
        if (this.getTeleportingToPos() == null && teleportingProgress > 0F) {
            teleportingProgress = Math.max(0, teleportingProgress - 10);
        }
        if (this.getAnimation() == ANIMATION_SPELL_1) {
            float f = this.getAnimationTick() < 10 ? 0.2F : this.getAnimationTick() > 40 ? -0.2F : 0;
            float backAmount = this.getAnimationTick() > 40 ? 0.0F : 0.1F;
            this.setDeltaMovement(new Vec3(0, f, 0).add(new Vec3(0, 0, -backAmount).yRot((float) -Math.toRadians(this.getYRot()))));
            this.fallDistance = 0.0F;
        }
        if (updateHeldItems && !level().isClientSide) {
            ItemStack main = ItemStack.EMPTY;
            ItemStack offhand = ItemStack.EMPTY;
            if (this.getAnimation() == ANIMATION_SPELL_0 || this.getAnimation() == ANIMATION_SPELL_1) {
                main = new ItemStack(ACItemRegistry.SUGAR_STAFF.get());
            }
            if (this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() < 90) {
                main = new ItemStack(ACBlockRegistry.CANDY_CANE.get());
            }
            if (!main.isEmpty() || this.areArmsVisuallyCrossed(1.0F)) {
                this.setItemInHand(InteractionHand.MAIN_HAND, main);
            }
            if (!offhand.isEmpty() || this.areArmsVisuallyCrossed(1.0F)) {
                this.setItemInHand(InteractionHand.OFF_HAND, offhand);
            }
        }
        if (updateFoldedArms) {
            boolean unfold = this.teleportingProgress > 0 || this.getAnimation() == ANIMATION_SPELL_0 || this.getAnimation() == ANIMATION_SPELL_1 || this.getAnimation() == ANIMATION_SWING_LEFT || this.getAnimation() == ANIMATION_SWING_RIGHT;
            this.setArmsCrossed(!unfold);
        }
        if (!level().isClientSide) {
            List<UUID> possessedIds = getPossessedUUIDs();
            if (level() instanceof ServerLevel) {
                for (UUID possessedId : possessedIds) {
                    Entity possessedEntity = ((ServerLevel) level()).getEntity(possessedId);
                    if (possessedEntity != null) {
                        this.tickPossessedEntity(possessedEntity);
                    }
                }
            }
            if (this.getHealth() < this.getMaxHealth() && this.getAnimation() == NO_ANIMATION && tickCount % 20 == 8 && eatCooldown == 0) {
                this.setAnimation(ANIMATION_EAT);
                eatCooldown = 200;
            }
            if (this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() == 90) {
                this.heal(5);
            }
            if (eatCooldown > 0) {
                eatCooldown--;
            }
        } else {
            if (this.getTeleportingToPos() != null && this.getTeleportingProgress(1.0F) < 1.0F) {
                Vec3 angle = new Vec3(random.nextBoolean() ? 0.5F : -0.5F, 2.0F, 0.0F).yRot((float) -Math.toRadians(this.yBodyRot));
                Vec3 delta = new Vec3(random.nextGaussian() * 2.0F, 4.0F, random.nextGaussian()).yRot((float) -Math.toRadians(this.yBodyRot)).add(this.position());
                this.level().addParticle(ACParticleRegistry.PURPLE_WITCH_MAGIC.get(), this.getX() + angle.x, this.getY() + angle.y, this.getZ() + angle.z, delta.x, delta.y, delta.z);
            } else if (this.random.nextFloat() < 0.003F) {
                for (int i = 0; i < this.random.nextInt(2) + 2; ++i) {
                    this.level().addParticle(ACParticleRegistry.WITCH_COOKIE.get(), this.getX() + this.random.nextGaussian() * (double) 0.13F, this.getBoundingBox().maxY + 0.5D + this.random.nextGaussian() * (double) 0.13F, this.getZ() + this.random.nextGaussian() * (double) 0.13F, 0.0D, 0.0D, 0.0D);
                }
            }
        }
        if (this.teleportingProgress >= 40 && this.getTeleportingToPos() != null) {
            Vec3 vec3 = this.getTeleportingToPos();
            this.setPos(vec3.x, vec3.y, vec3.z);
            if (!level().isClientSide) {
                this.setTeleportingToPos(null);
            } else {
                for (int i = 0; i < this.random.nextInt(8) + 8; ++i) {
                    this.level().addParticle(ACParticleRegistry.PURPLE_WITCH_EXPLOSION.get(), this.getX() + this.random.nextGaussian() * (double) 0.3F, this.getY() + this.random.nextGaussian() * (double) 1.5F, this.getZ() + this.random.nextGaussian() * (double) 0.3F, 0.0D, 0.0D, 0.0D);
                }
            }
            this.setOldPosAndRot();
            this.postTeleport();
        }
        if (this.getAnimation() == ANIMATION_EAT && this.getAnimationTick() < 90 && this.getAnimationTick() % 4 == 0) {
            this.triggerItemUseEffects(this.getItemInHand(InteractionHand.MAIN_HAND), 2);
        }
        if (teleportCooldown > 0) {
            teleportCooldown--;
        }
        AnimationHandler.INSTANCE.updateAnimations(this);
    }

public static void commonTick(Level level, BlockPos worldPosition, BlockState state, HoveringHourglassBlockEntity self) {
		int totalTime = self.getTotalTime();
		boolean dust = self.isDust();

		if (totalTime > 0 || dust) {
			if (self.move && !dust) {
				self.time++;
			}

			if (self.time >= totalTime) {
				self.time = 0;
				self.flip = !self.flip;
				self.flipTicks = 4;
				if (!level.isClientSide) {
					level.setBlock(worldPosition, state.setValue(BlockStateProperties.POWERED, true), Block.UPDATE_NEIGHBORS);
					level.scheduleTick(worldPosition, state.getBlock(), 4);
				}

				for (Direction facing : Direction.values()) {
					BlockPos pos = worldPosition.relative(facing);
					var trigger = XplatAbstractions.INSTANCE.findHourglassTrigger(level, pos,
							level.getBlockState(pos), level.getBlockEntity(pos));
					if (trigger != null) {
						trigger.onTriggeredByHourglass(self);
					}
				}
			}

			self.lastFraction = self.timeFraction;
			self.timeFraction = (float) self.time / (float) totalTime;
		} else {
			self.time = 0;
			self.lastFraction = 0F;
			self.timeFraction = 0F;
		}

		if (self.flipTicks > 0) {
			self.flipTicks--;
		}
	}

@Override
    public void tick(Level level) {
        if (!(level instanceof ServerLevel serverLevel))
            return;

        if (!isActive()) {
            if (this.nextSandstorm == -1)
                this.nextSandstorm = serverLevel.getGameTime() + this.interval.sample(serverLevel.getRandom());

            if (this.nextSandstorm <= serverLevel.getGameTime())
                start(serverLevel);

            return;
        }

        if (this.sandstormEndTime >= 0 && this.sandstormEndTime <= serverLevel.getGameTime()) {
            stop(serverLevel);

            return;
        }

        if (getIntensity(serverLevel.getGameTime()) >= 1 && serverLevel.getGameTime() % 10 == 0) {
            DamageSource source = DamageUtil.miscDamage(AoADamageTypes.SANDSTORM, serverLevel);

            Streams.stream(serverLevel.getEntities().getAll())
                    .filter(LivingEntity.class::isInstance)
                    .map(LivingEntity.class::cast)
                    .filter(this::isEntityAffected)
                    .forEach(entity -> entity.hurt(source, this.damage.sample(serverLevel.getRandom())));
        }
    }

